/* 平成20年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h20.committeeSessions.push(...[{"id":"h20-20080512-6","meetingId":"h20-cm05","date":"2008年5月12日","dateIso":"2008-05-12","committee":"区民委員会","time":"午後１時０４分～午後３時４４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１番、報告事項","agenda":"の１番、報告事項","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"説明の中では「もう設置しています」みたいな感じのニュアンスもあったんですけれど、これは既に設置されているのかどうかということと、こういう場所というのはすごく地域の方も望んでいると思うのですばらしい活動じゃないかなと思いますけれど、今回設置するに当たってどんな要望があったのかというところを伺いたいと思います。","respondent":"中山地域活動課長","answer":"既に１３地域センターに設置をしています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"例えばある政党とか、さすがにそこまで行くと「それだったら自分でやってくださいよ」という話になると思いますけれど、その団体がどこまで宗教とか政治的なのかすごく難しいので、それはある意味憲法上でも、特に政治活動というのは保障されているわけですから、とりわけそこで対象外とする根拠というのか、何か法律とかあるんでしたっけ。集会所の法律とかあるのかなとちょっと心配になってきまして。","respondent":"中山地域活動課長","answer":"集会所の利用の規定ですと、営利活動とか公共の秩序にもとるものはだめだというふうになっていまして、そういう意味では必ずしも政治・宗教活動が最初から利用できないということではないです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"活動の中身が、今回の掲示板の設置の趣旨の、地域に貢献する活動ですとか活性化とかいうことにふさわしいかどうかということで考えていくことだったんじゃないかなと思うんですけれど。今のお話ですと、何か登録団体を決めてということになるのか、そこら辺の具体的な、そういう要望があったときの受け付けてからの運用方法をもう少し詳しく教えていただければと思います。","respondent":"中山地域活動課長","answer":"掲示対象団体を登録するという考えはありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"具体的な、そういった掲示を希望して窓口に申し出た後の流れを教えていただきたいのと、そういうところを判断する方というのはだれになるのか聞きたいと思います。","respondent":"中山地域活動課長","answer":"ですから、地域センターで判断できないようなケースについては、場合によっては課単位で協議がかかってくるケースもありますけれども、ある程度地域の実情を把握しているのは地域センターであるし、私どもとしては逆に地域センターが、地域のさまざまな。","voiceIndex":11,"id":"exchange-004"},{"speaker":"渡辺委員","kind":"質問","question":"強いて言えば今後という点で、やはり施設内ですと、目的を持った人が地域センターに来られる、その人にしか目に触れないのと、外であれば散歩をしている方とかよく立ちどまってふれあい掲示板を見ていたり、そういった人に視覚で訴える効果というのは大きいと思うので、さっきのご説明にありましたガラス等でしっかり、ある意味立派な掲示板であるがゆえに外がだめなのか。","respondent":"中山地域活動課長","answer":"できるだけ長く見てもらうように、あるいは見やすくするようにが原則ということで施設外の設置を原則に考えたわけですけれども、先ほど敷地の制約と申し上げましたけれども、細かく言いますと例えば大崎第二のように。","voiceIndex":15,"id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"意見","question":"いろいろ企画、計画して地域の情報活動をやっていくのはすごくいいと思いますけれど、ちょっと僕の記憶がはっきりしないんですが、地域センターごとにホームページってありましたっけ。たしか見た記憶があるんですけれど。例えばこれをホームページに入れることも考えられるんじゃないかなと思うんですよね。活動の紹介みたいなものも何か入れられたら検討できないかなと。","respondent":"中山地域活動課長","answer":"今回のボードの表示はそれより膨らんでまいるわけですけれども、それを地域センター管轄の中に入れていくかについては、ボードの進捗も見ながら、ご質問にもありましたけれどちょっと検討の課題とさせていただきたいと思います。","voiceIndex":17,"id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"意見","question":"どの程度の人が、利用者はあるけれど一般的にどの程度見られるかなというのはこれからの課題だと思うので。やり方等、さっき言った人の問題だとか大変だと思うのでその辺よく検討してもらって、何かいい方法をつくってもらえればと思いますね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-007"},{"speaker":"川西委員長","kind":"質問","question":"私から質問します。例の1)の「ふれあい掲示板に載っていないもの」というのはどういう意味かということを、先に１つ伺います。","respondent":"中山地域活動課長","answer":"できるだけその地域でよいと思われる情報については載せられればいいわけですが、ふれあい掲示板はもともと区の広報情報として設置してまいったわけですが、ポスター等整理する中で、一定の余裕のあるスペースの中では。","voiceIndex":21,"id":"exchange-008"},{"speaker":"山路委員","kind":"質問・要望","question":"これは毎年やられているんですね。水防演習について、大体毎年同じような方法で同じ団体の方が出ているようなんですけれど、特に新しい訓練項目があったら教えていただきたいことと、参集訓練について、毎年参加できない人も何人かいるといううわさも聞くんですけれど、職員の参加率は非常にいいんでしょうか。その辺の実態について教えていただきたいと思います。","respondent":"斉藤防災安全担当課長","answer":"６月のこの時期には秋に参加しますと言っているんですけれど、何らかの行事が入ってくるということがありますので、必ずしも１００％というわけにはまいらないと思います。ただいずれにしても、ほぼ９０％に近い数字の参加率ということでは把握をしております。","voiceIndex":27,"id":"exchange-009"},{"speaker":"山路委員","kind":"質問","question":"訓練が大事なのは、実際に被害が見つかったときに最小限に食いとめられるかどうかにあると思うんですけれど、水防演習は西大井広場でやるんですよね、かなり広いところですよね。それで関係者の人がほとんど来ている、毎年来ていらっしゃるんですけれど、一般区民の方というのは呼びかけたりはしないんですか。","respondent":"斉藤防災安全担当課長","answer":"ただ、今のご指摘の話につきましては、私どもも基本的には町会長を通じましてご案内差し上げているんですけれど、より多くの人に見てもらいたいというのが私どもの本音ですので、今後は消防署のほうとも相談しながら、そのような形で進めていきたいと考えております。","voiceIndex":29,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"大田区内の各消防署の職員がいらっしゃるということですけれども、これは毎年なんですか。すごくいいことだと思いますけれど、どういう効果をねらっているのかなというのと、逆に大田区のほうでやる場合、品川の消防署の職員の方が行ったりすることはあるのかなと。聞かせてください。","respondent":"斉藤防災安全担当課長","answer":"したがって品川区で１年おきにこの規模の訓練だという形になっております。したがいまして、大田区で実施されるときには当然、品川区内の消防署から応援隊という形で訓練に参加しています。","voiceIndex":31,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"提案","question":"水防訓練は大変ご苦労する部分も十分わかっています。その辺我々から言わないと、なかなか行政側からは言えない部分だと思うので、そういう提案があったということもまた踏まえて、ほかの分にもうまく活用してもらえばと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-012"},{"speaker":"安藤委員","kind":"意見","question":"テーマということで、抽象的になってもいけないので、委員会でも議論になった末テーマを絞っていくということで「子育て」「子ども」「女性」をキーワードとしたビジネスということになったというお話なんですが、ちょっとご説明がよく……。今回の事業は国とか都からの補助みたいなものはあるのかなということを聞きたいと思います。","respondent":"金子産業振興課長","answer":"この重点化のテーマのところでご説明申し上げたところの疑問ということですけれども、委員会の結果の報告ですが、私も委員会に出ていましたのでそのときの論議というのは、やはり創業支援施設、いわゆる工業系、ものづくり系は私どもも施設を構えているわけですけれども。","voiceIndex":38,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"とにかくそういう議論になってテーマを絞り込む必要があるというところまではわかるんですけれど、いろいろなテーマがあるんですけれど今回子育てとかに特化したというのは何か議論があったと思うんですけれど、そこら辺の経緯を伺いたかったもので、もう一度お伺いしたいと思います。","respondent":"金子産業振興課長","answer":"人が来ないような施設でいいのかどうなのかというお話があったと思いますけれども、武蔵小山の駅前で武蔵小山全体もやはり発展させていかなければならない、あるいは活性化、盛り上げていかなければいけないというのが区の役割だと考えております。","voiceIndex":40,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"この２階、３階のところがそういうことなのかなと、今お話を伺ったらそういう意味なのかなと思ったんですが、施設全体として重点化のテーマとして、「子育て」「子ども」「女性」をキーワードとしたビジネスを重点支援するという話になるのかどうか、ちょっとわからなかったのでお伺いしたいのと、子育てビジネスというのは要するに保育園の運営とかになるわけですか。そこら辺もちょっとわからないので。","respondent":"金子産業振興課長","answer":"こういった意見は委員会の中で出ていました。ですので、そういう意味では保育施設そのものの機能、それからまた創業支援の機能から預ける方々へのかかわり方、そういった２つの点からこのテーマに沿ったやり方で進めていくことが可能なのではないかと思っています。","voiceIndex":42,"id":"exchange-015"},{"speaker":"稲川委員","kind":"質問","question":"もう１点が今後のスケジュールで、平成２０年度に基本設計・実施設計とあるんですけれど、実際３４ページにいろいろ出ているのは、設計とは言わないと思うんですけれど、こんな感じでつくるということはもう決まっているというか、どうなのかなと。これからスタートで、もう既にある程度決まっているのかどうかお伺いします。","respondent":"金子産業振興課長","answer":"ですので、他地区については今後の検討課題になろうかと考えているところです。","voiceIndex":44,"id":"exchange-016"},{"speaker":"渡辺委員","kind":"質問・要望","question":"ご説明で、コンセプト等全部いろいろな検討の上、かなりここまでの取りまとめは大変だったなというのはよくわかりました。その中で、この重点テーマという「子育て」「子ども」「女性」も一致しますし、各会議スペースというのもあったりして、そういう意味では何か１つ事をやろう、行事をしようとしたとき、こういった会議施設というのはすごく求められていると思いまして。","respondent":"金子産業振興課長","answer":"検討委員会の議論の中では、駐輪場は必要だろうという話はありましたけれども、どのぐらい必要かという具体的なところまでは出ておりません。","voiceIndex":46,"id":"exchange-017"},{"speaker":"渡部委員","kind":"質問・要望","question":"この冊子の地図で、この６階の貸し出しスペースって、展開図を見るだけだと意外と狭いのかなと。ページの最後のほうにいろいろなまちの例というのが出ていまして、ショップ系が多いように伺えるんですが、例えば今回武蔵小山にこのような施設をつくろうとしたとき、特段どこをモデルにして考えたみたいな、たたき台みたいな感じで、こういう行政でこういう例があるとか、何かあれば教えてほしいと思います。","respondent":"金子産業振興課長","answer":"もう１つ、モデルとしてどういうところがあるのかということですけれども、私どもも見にまいりましたが、幾つかの施設、どこをというわけではなくて、後ろのほうに出ておりますけれどもそれぞれの施設のポイント、ポイント、この部分はいいなと思ったものを。","voiceIndex":48,"id":"exchange-018"},{"speaker":"渡部委員","kind":"質問","question":"いろいろ明確にありがとうございました。たしか大阪だったでしょうか、いろいろな自治体でこの創業支援というのをやっていると思うんですけれど、障害者の方への創業とか就業とかは別問題で、創業というとすごく幅が広いと思うんです。ましてや商業系となりますと、物販から飲食から非常に幅広いと思うんですが、たしか大阪か何かで、フランチャイズ向けの講習会とかいうのを行政でやったりしているんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"意見","question":"いろいろな課題はあるけれどこれだけまとめられていて、すごくわかりやすく説明していただきました。そういう指導体制はこの相談コーナーとかいうところでやっていくとなると、その辺の専門家の配置というのは常にずっと置いていかれるのかというのが１点と。その３点をお聞かせください。","respondent":"金子産業振興課長","answer":"それから保育ですけれども、これも今の段階では一般論になるかと思いますけれども、いわゆる認可保育所、認証保育所等々の保育所でも、月極めで預かっている方とは別に一時保育の枠も持っているところがほとんどだと考えておりますので、そういう意味では今のお話のとおり。","voiceIndex":51,"id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問","question":"言っているのがちょっとわかりにくかったと思うんですが、どう言っていいかわからなかったのでうまく言えないんだけれど。そこら辺でどういう、指導のほうでよく見ていきながら……。ここのシステム、施設の運営主体になるべき団体は、主体はどこが運営していくと考えたらいいんですか。","respondent":"金子産業振興課長","answer":"後段のほうのお尋ねですけれども、運営主体としては今は明確に、こういう団体にというような像があるわけではないんですけれども、ただ施設の運営が保育機能とそのほかのことというところ、区民サービスコーナーもありますので。","voiceIndex":53,"id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今の説明はわかりました。最初に言われたとおり、やはり保育まで含めた場合には非常に難しいかなという気がしますので、これから２年、実際に始まるのはその前からスタートするんでしょうけれど、いい運営主体を見つけてもらって、まずこれが成功するような形でやっていってもらいたいというか、その辺よく検討をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":55,"id":"exchange-022"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"検討委員会のところなんですが、私がこの武蔵大学の教授を存じ上げていないので、どういったところで活躍をされている方なのかということと、メンバーが先ほど示されたんですけれど、この地域って大中小の商店街がとてもたくさんあるわけですけれども、周りの商店街と相談をされて人選がされたのか、その辺どのようにこのメンバーを選ばれたのかお聞きしたいのと。ちょっとその辺をお聞かせください。","respondent":"金子産業振興課長","answer":"それから産学公の学のことですけれども、私どもが直接というわけではないんですけれども、立正大学のほうでは五反田商店街と連携して学生のさまざまな勉強等々も実施しているので、私ども報告会に参加させていただいたりしておりまして。","voiceIndex":56,"id":"exchange-023"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"きょう、机上で報告書をいただいたんですけれども、４回会議を開かれたということなんですが、途中の報告とか品川区内の商店街の意見を聞くとか、そういうことがあったのかどうかという点と、先ほどの質問をちょっと聞き漏らしちゃったんですが、運営の主体がどのようになっていくのか、もう１回聞かせていただきたいと思います。","respondent":"金子産業振興課長","answer":"それから運営の主体ですけれども、今現在どこどこのだれだれというふうに決まっているわけではありません。今後２年間の中で鋭意検討していきたいと考えているところです。","voiceIndex":58,"id":"exchange-024"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"このスケジュールが書いてあるんですが、今年度は６００万円でしたっけ、予算がついていたと思うんですけれど、今後の建設費用とかその辺はどういうふうに増えていくのか。わかっている部分で教えてください。","respondent":"金子産業振興課長","answer":"今年度で言いますと、検討の報告に関して平成１９年度で予算が６００万円で実施してきたところでございまして、平成２０年度に関しましては基本設計・実施設計あわせて約２,０００万円の予算を計上しています。","voiceIndex":60,"id":"exchange-025"},{"speaker":"飯沼副委員長","kind":"意見","question":"今回は商業系ということですけれども、今までの西大井の創業支援センターの取り組みとか、天王洲のところは二次ということで、これは３つ目と思っていますけれども、今までにおいての総括というものはどこかでされて何か出ているのかどうか、その辺も聞かせていただいたいと。","respondent":"金子産業振興課長","answer":"ご指摘のとおり西大井と天王洲で創業支援センター施設を運営してまいりましたので、予算特別委員会あるいは決算特別委員会でもご質問いただきまして、一定の報告をしてきているところでありますが、そういう意味では先ほどから申し上げているとおり、工業系。","voiceIndex":62,"id":"exchange-026"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"これは要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"１点目と２点目の２つの項目の改正の、他区の状況というのはどうなのかなということと、２点目の件なんですけれど、国がベンチャー企業株式の取得に関する優遇措置を短縮したということで、証券税制の政策転換のため、今回こういう措置をしたということですけれども、国が短縮したという考え方は区としてどうとらえているのかということと。","respondent":"武内税務課長","answer":"２点目の国の証券税制、今回専決処分ではベンチャー企業の特定株式取得期間の短縮ということですけれども、ご案内のとおり地方税法はさまざまな改正が行われまして、その他につきましては今後２定あるいは３定でご審議いただく予定ですけれども、今回のものにつきましては。","voiceIndex":69,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"先ほどのベンチャー支援施設のお話とも絡むかもしれないんですが、今回短縮するというのも、国としては先ほどのご説明だと、ベンチャーへのさらなる投資を拡大したいという国の考えでもあるということだったんですが、今回こうした改正にしたというのは、２３区すべて共通で行っているということですけれども、独自の考え方を持って行うものなのか、それとも区として今回これを改正するというところのもとに。","respondent":"武内税務課長","answer":"一部法定外の新税の設置とかいうものについてはそれぞれの自治体にゆだねられて、特段するとかできますけれども、今回の部分については日本全国一律に廃止するということになっておりますので、ご理解いただければと思います。","voiceIndex":71,"id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問","question":"あんまり長いことやっているとあれなので、１番の住宅借入金特別税額控除申告書の提出期限の拡張ですけれど、この対象者としてはどのぐらいを見込まれるのか。それと、これは基本的に３月までにやった人と、３月以降やらなかった人たちも含めて、どのぐらいの方がもう済んでいるのか、その辺は区として数字をつかめているんですか。","respondent":"武内税務課長","answer":"今後じゃあ、どのぐらい増えるのかという部分につきましては、数百人の方は漏れているのではないかとこちらでは予定しておりまして、この方たちはじゃあ、今後どうするのかということですけれども、６月に賦課決定しましたら所得税の絡みと住民税の絡みを調査しまして。","voiceIndex":73,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ちょっとこれは記憶なんですけれど、今年初めての人でなくて、もともと住宅ローンの控除をやっている人がいますよね。その人は年末調整で今までできていた。その方たちは勤め先のほうで年末調整をやってくれればそのとき自動的になっていたと思うんですけれど、その人も新たにやらなきゃいけなかったんですよね。そういう方が今年出てきたという判断でいいわけですね。","respondent":"武内税務課長","answer":"そうしますとローン控除を本当はもっと引けるという方は、年末調整でそういう金額が入力されるようになっています。１月１日現在品川区に住民登録がある方については品川区のほうで課税をしますので、品川区のほうに確定申告をしていただくというのが原則です。","voiceIndex":75,"id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"確認","question":"その対象者がどこまで理解しているか、どこがやるべきかというのもあるんだけれど。品川区として例えばホームページだとか広報の部分に今課税されている人がわかるように、住宅ローンの関係で所得税がゼロになっている人は申告したほうがいいんじゃないですかというような、そういう呼びかけというのはしているんですか。その確認だけ。","respondent":"武内税務課長","answer":"もちろん広報またはホームページ等で何回も周知しておりまして、先ほど説明したとおり６月の賦課決定後、７月ぐらいに漏れている方を抽出しまして、ご連絡するという事務手続で、漏れのないようにしてまいります。","voiceIndex":77,"id":"exchange-032"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"住宅ローン控除の対象というか、どういう方がどのぐらいの期間受けられるのかということと、少しだけ説明があったんですけれど、税源移譲の所得税と住民税の変わってきたあたりの説明をもうちょっと詳しくしていただきたいんです。この住民税にかかわってくるあたりの説明をもうちょっと詳しくしてほしいんですけれど。","respondent":"武内税務課長","answer":"その５万円の部分を、１月１日現在品川区に住んでいる方については品川区のほうに確定申告、ローン控除の申告をしていただければ、この５万円を住民税のほうから補てんしますよという、そういうシステムです。","voiceIndex":79,"id":"exchange-033"},{"speaker":"飯沼副委員長","kind":"質問","question":"今のご説明とすると、申告漏れした方もちゃんと通知をしてくださるということなので、不利益になるような方はいらっしゃらないと受けとめてよろしいんでしょうか。","respondent":"武内税務課長","answer":"もちろんこれは申告主義ですから、ご本人が申告していただかないとこちらは何ともできませんので、そういうことを知らなかったとかいうことがないように。","voiceIndex":83,"id":"exchange-034"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"それを今回１年間またもとに戻すというあたり、どう理解していいのかなと。先ほど課長がちょっとだけ触れた中身、ほかにかわるものがあるようなところを、もうちょっとその中身を、なぜ延ばしたばかりなのにまた縮めてもとに戻すのかなというあたり率直な疑問なので、どこがどう変わってここをやめたのかというところを、もうちょっと詳しく教えていただきたいと思います。","respondent":"武内税務課長","answer":"ですから、先に優遇措置をするのか、後に優遇措置をするのかということで考えていただいて、後からやるほうについては住民税が該当したんですけれど、今回はこの住民税のほうの優遇措置がなくなりましたので、すべてベンチャー企業に対する住民税の優遇措置はなくなりました。","voiceIndex":85,"id":"exchange-035"},{"speaker":"飯沼副委員長","kind":"質問","question":"今までのが後に優遇税制、今度は先にということは、株式が譲渡されてもうかろうがマイナスになろうが先に控除がされると、ベンチャー企業株式を取得した人に対しては、いい中身に変わったという理解でよろしいんでしょうか。それが１点と。質問がよくないかもしれないですけれど教えてください。全体像がちょっと見えないのでお願いします。","respondent":"武内税務課長","answer":"株というのはベンチャー企業ということで今ご説明させていただいているんですけれど、そのほか上場株というのがあるんですね。上場株というとある程度社会が安定していれば、投資家にとっては安定していく部分があると。","voiceIndex":87,"id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"ここが具体的にパートナーを見つける場所になり得るんじゃないかと思っちゃうので、そういうのはどういうふうに考えているのかなということと。2)で相談事業を行うことになっていますけれども、事業者の施設を使うということですけれど、具体的にはどこになるのかなというのをまずお伺いします。","respondent":"小野区民課長","answer":"今回委託を予定しております業者では、まず恋愛度テストというようなもの、これはこの事業者の１つの特徴ある事業なんですが、こういうものを事前に申し込みの時点で受けていただいて自己分析、それから相性分析みたいなものもこういう中でやっていく。","voiceIndex":93,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回、民間のノウハウを生かすと。そこら辺に関してはどう考えているのかなというのと。私なんかも街頭で青年のアンケートみたいな、最近ちょっとやっているんです。ですから、そういったことを関係部署に働きかけていくとか、あるいはそういった事業方向を中に組み入れるとか、そういったことをぜひ考えていただきたいんですけれど、いかがでしょうか。","respondent":"宮地区民生活事業部長","answer":"日ごろの安藤委員のお話を聞いていれば当然のことかなと思いますが、本日は結婚サポート事業の業者選定に関するご報告ですので、そういったことはまたの機会に改めましてお答えさせていただきたいと考えております。","voiceIndex":95,"id":"exchange-038"},{"speaker":"安藤委員","kind":"意見","question":"すごく難しい問題だと思うんですが、３番目のところで入会金の割引というふうになっちゃうと、確かに安く具体的にパートナーを紹介していただくのが核と言えば核なのですごく大事なところなんですが、ここら辺がすごく難しいところだなと考えちゃうんですけれど。","respondent":"小野区民課長","answer":"これはそれぞれの業者の紹介事業、これは事業者にしても結婚サポートの核になる事業ですけれども、これに参加するというか紹介支援を受けて企業の提供する会員になるか、これは全く自由でございまして、やはり結婚ということを考えたとき、セミナーなり相談なりした上で。","voiceIndex":100,"id":"exchange-039"},{"speaker":"稲川委員","kind":"質問","question":"５番の周知方法で「広報しながわ、ホームページ、窓口用チラシ」と書いてあるんですが、委託業者は株式会社オーネットと書いてあるんですが、そのオーネットの名前というのはそういった窓口のチラシとかそういうところにも出てくるんですか。","respondent":"小野区民課長","answer":"これは最後のパートナー紹介支援事業も入ってまいりますので、チラシの中に、これはオーネットの宣伝をするわけではございませんので、大きく書くということではないかと思いますけれども、必要な部分に入ってくると考えております。","voiceIndex":102,"id":"exchange-040"},{"speaker":"稲川委員","kind":"質問","question":"オーネットというのはほんとうに大きな紹介所だと思うんですけれど、信用はおけると思うんですけれど、例えばこれは笑い話になってしまうかもしれないけれど、既存にオーネットに入っている人たちがもし何かいろいろな形で区に苦情を入れて、「私たちにも何かないのか」という話になったとき、その苦情対応とかいうのもちゃんと、今後窓口はつくるんですか。やはり中にはそういう人もいると思うんですよ。","respondent":"小野区民課長","answer":"苦情の対応ですけれども、これはオーネットのほうが品川区の受託の事業をやるに当たって、そのための電話窓口を設けますので、当然企業のほうにいく分についてはそこで対応するということですけれども、区にきたものについてはきちっとお答えする。","voiceIndex":104,"id":"exchange-041"},{"speaker":"安藤委員","kind":"確認","question":"繰り返しになって申しわけないんですが、これまでの区民健診の検査内容と比べて、なくなった項目はないということでよろしいですかという確認と、この資料を読ませていただきますと、「必要に応じ、心電図およびがん検査」ということで項目はなっていますけれど、「必要に応じ」というところがちょっと気になるので、これは前と変わらない状況なのかということをお伺いしたいと思います。","respondent":"本城国保年金課長","answer":"委員からご質問がありました検査項目についてですが、こちらにつきましては平成１９年度まで行っていました区民健診の項目を引き継いでいるものでございまして、なくなった項目は特にございません。","voiceIndex":109,"id":"exchange-042"},{"speaker":"安藤委員","kind":"質問","question":"先ほど申し上げた７５歳以上の方なんですが、すごく問題になっていますので、受けられないんじゃないかみたいな不安がかなりあふれていますが、７５歳以上の方々の後期高齢者健康診査というものがちらっとこの資料にも書いていますけれども。そういった心配はあるのかないのか。今年実施される内容だと、来年以降の見通しというのはどういうふうになっているんでしょうか。","respondent":"本城国保年金課長","answer":"今回ご説明させていただきました特定健診につきましては、国民健康保険の特定健診ということでございまして、４０歳から７４歳までの国保の対象の方の健診です。７５歳以上の方についてはいわゆる後期高齢者での健診ということでございまして、また別枠となっております。","voiceIndex":111,"id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"そういうので、やはり区としてはきちんと説明していくことがものすごく大事な部分じゃないかと思うんですけれど、このご案内を見ると何か全然わからない感じになっているので、それはやはり説明をされていく必要があると思うんですが、いかがでしょうか。","respondent":"本城国保年金課長","answer":"今回の健診については各医療保険者に分かれての実施ということになりますので、全体像がわかりづらいとご本人はさらにわかりづらいということで、今回あわせてパンフレットを同封させていただきまして、各健診の全体像がわかるようにということで同封させていただいたところです。","voiceIndex":113,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと繰り返しになって申しわけないんですが、これだけでは全然不安は払拭されないんじゃないかと思うので。実際問題、後期高齢者の方にはどういうふうに、ちゃんと不安が払拭されるような情報というのは、いつどこでどういうものをということを、つかんでいる範囲で構わないので、主体が違いますけれどもそれは当然つかむべきだと思いますけれども、そこはつかんでいる範囲でいいのでお伺いしたいのと。","respondent":"本城国保年金課長","answer":"７５歳以上の後期高齢者につきましてはちょっと所管が違うんですが、伺っている範囲では６月から実施予定だと伺っているところです。","voiceIndex":115,"id":"exchange-045"},{"speaker":"安藤委員","kind":"質問","question":"そういった点で弱いように感じるんですよね。ですから、問い合わせや苦情に対してどのように対応しようと考えているのか。","respondent":"本城国保年金課長","answer":"実際、４月からケーブルテレビ品川を活用して、そこで実際の健診等の内容をＰＲしたり、あるいは国民健康保険の被保険者の方に、「こんにちは国保です」とか、「わかりやすい国保」といったＰＲパンフレットをお配りするんですが。","voiceIndex":117,"id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"意見","question":"内容はわかりました。費用も無料という話が今あったんですけれど、この４月１１日付の広報もこの来た書類にも、無料というのは出ていないんですよね。実はうちも来ています。で、じっくりもう１回見直したんだけど、今までの区民健診はわかるんだけれど、特定健康診査、特定保健指導という言葉が出てきて、一般の区民の方から聞かれました。「中が変わってお金がかかるの」と言われた。","respondent":"本城国保年金課長","answer":"無料ということを明示していなかったと思うんですね。今お配りしたものの中で……。","voiceIndex":119,"id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"質問","question":"広報しながわに載っている、要するに利用機関に貼ってあるものには表示が見えますが。受診券の中を見て、受診した医療機関で約１週間後に血液検査等の結果を聞くことができますと。その前に２カ月たってから通知が行きますよということになっているけれど、何か異常があったとき、受診機関から直接２カ月もたたないうちにこういうところが問題がありますよというのは出ないものなんですか。","respondent":"本城国保年金課長","answer":"今までと同様に、医療機関のほうから問題についてはお知らせするような内容がですが、ほぼ２カ月後というのは、１回データを分析しまして、きちんとしたご通知書ということで品川区のほうから受診者の方にお伝えするのが２カ月後ということで。","voiceIndex":121,"id":"exchange-048"},{"speaker":"鈴木（真）委員","kind":"質問","question":"すると、「聞くことができます」というのは、本人が聞きなさいよという雰囲気に見えるじゃないですか。本人が受ける方がどうかなというのと、あとは医者に判断を任せるしかないというような、その辺がちょっと気になったので。答えはわかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-049"},{"speaker":"渡部委員","kind":"質問","question":"やはりこれが着きましていろいろな質問をもらったのが、今の無料という話の部分もあったんですが、今回その特定健康診査で引っかかった場合の保健指導が入るという部分の中で、低い人、中程度の人、高い人、治療が必要な人とかいう分類って、だれが決めるんですかね。というのがまず１つと。僕も区民健診を受けまして、医者が１週間ぐらいで結果が出るよと言ったら行きます。あわせて教えていただきますか。","respondent":"本城国保年金課長","answer":"最後の保健指導のお知らせの仕方ですが、これにつきましては２カ月後に区のほうからお知らせをするときに、詳しい内容について改めてご通知するところです。","voiceIndex":124,"id":"exchange-050"},{"speaker":"渡部委員","kind":"質問","question":"ですから、例えばかかりつけと言いますか知り合いの医者で受けたとします。だけれどそれとは別立てでデータが見られるわけですから、区からいわゆる保健指導を受けなさいよ、もしくは治療を始めなさいよという連絡が来てしまうのかどうなのか。それだけもう１回教えてほしいです。「これはそれにかわるものですよ」というものが１通ビラで入れられるか入れられないかという質問とあわせて、２つお願いします。","respondent":"本城国保年金課長","answer":"その後の判定につきましては、今回の特定健診結果の通知書というものを区のほうからご本人様宛にご通知することになりますが、その中にどこのお医者様ということで判断したかということで、お医者様の判断を併わせて書くかたちになります。","voiceIndex":126,"id":"exchange-051"},{"speaker":"飯沼副委員長","kind":"質問","question":"今回、私は５月なんですが、８月までに健診の期間が定められて、今までよりも期間が短くなったという点をもうちょっとしっかりしないと、漏れてしまう人がいるのではないかなという心配が１点と、もしこの期間に受けられなかった人はどういうふうになるのかというのをお伺いしたいのが１点です。電話がかかったり手紙が来たりという通知が来るということなのか、その辺どういう連絡が来るのか教えてください。","respondent":"本城国保年金課長","answer":"そういう意味で前倒しになっていまして、８月までに受診していただいて、継続してその後の指導の期間につなげるです。","voiceIndex":128,"id":"exchange-052"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"漏れた方については対応をぜひしていただきたいと思います。特定保健指導のところは区から通知が届くということなんですけれども、前回の報告があったとき、どこに委託をするのかというので「今、手続中だ」ということだったんですが、もう４月になって既に決まっていると思うんですが、その辺はどこに委託して、結局どういうような仕様というか中身で委託をしているかという中身を教えてください。","respondent":"本城国保年金課長","answer":"ただ金額等最終的に、実施内容について調整しているところでございまして、今後、最終的な契約をする予定です。","voiceIndex":130,"id":"exchange-053"},{"speaker":"飯沼副委員長","kind":"質問","question":"保健教育センターがどういうところなのかということと、実績というのがあったら教えてください。私も初めて聞いたところなので。区民の大事な健康の情報が行って、指導が来る、やりとりが何回も６カ月にわたって行われるということでは、かなり大切な情報を持つところなんですけれど、実績的にはどういうことをやっているところなのか、わかる範囲で教えてください。","respondent":"本城国保年金課長","answer":"実績につきましては、全国でいろいろ、特定健康診査自体は今回がもちろん初めてですが、その前段の事業で、国保ヘルスアップ事業と類似の事業がございまして、そういったところも全国的に担って、その実績も含めてあるところです。","voiceIndex":132,"id":"exchange-054"},{"speaker":"飯沼副委員長","kind":"質問","question":"こういった特定保健指導は新しい事業ですけれど、こういうのを受けることのできる受け皿というか企業というのは幾つかあるんですか。プロポーザルで選ばれたということですけれど、その辺でもしわかったら。まあ、ここで決まったということですけれどね。","respondent":"本城国保年金課長","answer":"こちらを含めて複数のところということで、全国的にどれぐらいの企業が実施体制を持っているか等につきましては、ちょっと把握していないので、これ以上詳しくお話しできないんですが。今回、数社についてはプロポーザルで、提案があったです。","voiceIndex":134,"id":"exchange-055"},{"speaker":"飯沼副委員長","kind":"質問","question":"社保の扶養家族の受け皿というのがはっきりしていなかったような気がするんですけれども、健康診査なんですけれど。国保のところでの受け皿というのはあるんでしょうか。","respondent":"本城国保年金課長","answer":"ただ、あくまでも責任主体としては、国民健康保険の実施主体が品川区の国保であるのと同様、各健康保険組合というのが基本的には実施主体ということになるわけですが、実施形態については今調整中ということで伺っているところです。","voiceIndex":136,"id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2514#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":46583,"voices":138}},{"id":"h20-20080512-7","meetingId":"h20-cm05","date":"2008年5月12日","dateIso":"2008-05-12","committee":"厚生委員会","time":"午後１時０３分～午後４時３０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"内容のことではないけれども、表紙に「平成２０年３月」と記載されていて、配られたのが５月ですね。これから各施設なり何なりに配布していこうというと、３月にでき上がっているのに５月中旬に配布と差があり、なぜ議会への報告が５月なのか、４月１５日にも委員会があったのにという思いがあるんだけれども、その辺はどうですか。","respondent":"小林保育課長","answer":"３月ぎりぎりまで具体的な内容について精査しておりまして、その結果を経て印刷、調製等に１カ月ほど時間を要してしまったということで、もっと速やかにやれればよかったと反省しているところもありますけれども、内容を慎重に精査した結果、印刷の上がりが４月末。","voiceIndex":11,"id":"exchange-001"},{"speaker":"須藤委員","kind":"質問","question":"行政で出す場合、３月までかかりましたということで３月という記載でいいという考えなのか、それとも３月までかかったけれども、発行は４月になりました、５月になりましたという、基準の考え方が決められているのですか。今まで３月に出たものは２月いっぱい検討して、３月に発行したという印象もあるけれども、その辺はどうですか。","respondent":"小林保育課長","answer":"今回の実践のてびきにつきましては、特に３月にこだわったということではございませんが、平成１９年度事業として１年間やってきた締めくくりを、現年度の中できちんと取りまとめ、それをもとにしてＰＲ等は新年度に入るにしましても。","voiceIndex":13,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"幼稚園教育要領も改定されているということを聞きましたけれども、これとの関係はどうなっているのか一つお聞かせいただきたいと思います。それから、これができたことによって、具体的に現場では何がどのように変わっていくのか、どのように活用されていくのか、イメージできるような形で教えていただきたいと思います。","respondent":"小林保育課長","answer":"内容として、例えば今回の区のてびきに影響しているところとしましては、年齢に応じたそれぞれ養護、教育の視点の明確化ですとか、また、今後取り組みますが、単に保育者だけでということではなく、保護者に対する支援の観点を明確にした等の特色が今回の改定にはありますので。","voiceIndex":15,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、今までも保育園でも保育所保育指針を参考にしながら、具体的に保育の中身をどうするかということを、それぞれの園が計画を立てて保育実践してきたというところがあると思うんですけれども、今回、保育所保育指針が改定されて、国の流れが変わったことを受けてこのてびきがつくられて、品川区でも実践の計画の参考にしていくという考え方でいいのでしょうか。","respondent":"小林保育課長","answer":"研修についてですが、年間４回程度実施というのは講演会も含めた研修で、全部セットですので、これとは別に何か技術的な研修を行うということは、今のところ予定していません。","voiceIndex":17,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つは、今、保育園の体制が大変で、本当に保育士たちもぎりぎりで疲れ果てているという話をよく聞いているんです。それから、４番の専科講師の派遣で、就学を控えた区立保育園の年長児に、専科講師による造形・音楽・体育の指導を実施するということですけれども、具体的にはどのぐらいの体制になるのかということも教えていただきたいと思います。","respondent":"小林保育課長","answer":"具体的に申し上げると、今年度につきましては３７園の保育園全園で造形を、音楽または体育はどちらかを園で選択する形で、結果的に音楽が２４園、体育が１３園、合わせまして３７園、それぞれ二つの分野につきまして、月２回程度。","voiceIndex":19,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このような幼児教育の冊子がつくられたということは、国がそのようなことを出したということで、これから他でもつくられるのかもしれませんが、品川区が先進的にやっていると考えていいのでしょうか。もう一つは、今回これをつくられて実践して、さらにもっといい中身に変えていくという評価、改善の検証も含めて、そのようなことはどのようにされていくのかお聞かせいただきたいと思います。","respondent":"小林保育課長","answer":"他の自治体につきましても、今回の国の指針から申しますと、今後、保育教育の課程を作成することが求められていくかと思いますので、それぞれの自治体でしかるべき対応は今後検討されていくものと思います。","voiceIndex":21,"id":"exchange-006"},{"speaker":"宮崎副委員長","kind":"質問","question":"それからもう一つ、ここは文教委員会ではないですけれども、品川区は小中一貫教育を全校展開でやっているんですけれども、先ほどの無理なく小学校入学へつなげるということと関連して、小中一貫教育との関係といいますか、連動性といいますか、その辺をどのように考えているのか、位置づけはどのようになっているのか伺いたいと思います。","respondent":"小林保育課長","answer":"したがいまして、可能な限り、そこに戸惑うことなく新しい環境になじんでいけるように、特に年長クラスでは学校との連携を強めて、その環境に体験的に対応していくとか、また教え導く職員の側で子どもの状況を的確に理解する、そういった接続の努力が必要ということが。","voiceIndex":23,"id":"exchange-007"},{"speaker":"宮崎副委員長","kind":"質問","question":"いまのところがよくわからないんですけれども、私が聞いたのは小中一貫教育へのステップという位置づけで考えているのかどうかということが一つ。それから、造形・音楽・体育というのは、興味を持ってもらうということで、こっちの方は専任講師でやるということですが、そうすると、言葉や文字を使ったりというのは、普通の保育士が担当してやっていくようになるのでしょうか。","respondent":"小林保育課長","answer":"しかも、それを連携を取ってできるだけ無理なく接続していくという意味ですから、当然品川区が進めております小中一貫の流れを視野に入れて、４歳児・５歳児の位置づけを考えているという意味です。","voiceIndex":25,"id":"exchange-008"},{"speaker":"宮崎副委員長","kind":"確認","question":"今の文字のところは、保育士が担当してやっていくということですけれども、そうすると、これまでどうだったのかということと、今後の変化はどのようになるのかということが一つ。それから、連続性を持っていくということで、学校にしっかりつなげていくために一定の学力をつけていくというようにも聞こえたんですけれども、そのようなねらいだということでいいのかどうか、もう１回確認したいと思います。","respondent":"小林保育課長","answer":"例えば、文字を例にすれば、難しい漢字が書ける、読めるということではなくて、文字という記号が自分たち人間の生活に対してどのような位置づけで、どのような役割を持っているものなのかというところが基本で。","voiceIndex":27,"id":"exchange-009"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"私は例えばということで４６ページを出したんですけれども、ここでは表現する手段として文字です。ですから、今の説明はここに書いてある内容と少し違うのではないかという思いがします。それから、これを見ると何歳のときにはこのようになるとか、非常に細かく書いてあります。そこのところが置き去りにならないような対応をしていただきたいということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-010"},{"speaker":"堺委員","kind":"質問・要望","question":"このことは、今日いただいたＡ４の資料の中でも事業目的の中に、滑らかに小学校へ入学するための基礎をしっかりと身につけることができるようにするために、こういう取り組みをまとめたとあります。もう一つは、保護者に向けて子育てガイドを作成して配布ということですから、希望としてはなるべく早くつくられて、一日も早く保護者の皆さんのお手元に届くようにしていただけると大変ありがたいと思います。","respondent":"小林保育課長","answer":"今回は、とりあえず一番結びつきやすい成長段階にある５歳児で導入しますが、その結果、得られたノウハウを活用して、こちらに着眼点を今回まとめさせていただきましたけれども、それを背景とした指導ができるように資質の向上に引き続き努めてまいりたいと考えております。","voiceIndex":30,"id":"exchange-011"},{"speaker":"堺委員","kind":"質問・要望","question":"今、資質の向上に向けて取り組んでいかれる趣旨の答弁をいただきましたけれども、確かにいただいた冊子の３ページに、「子どもの育ちの変化とその背景」の一番下段を読んで、確かにそのとおりだろうと私も思うんです。ですから、今もおっしゃっていただいたように、子どもたちのさらなる向上を目指して、大変なことがいろいろあるかもしれませんが、なお一層の取り組みを要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-012"},{"speaker":"高橋委員","kind":"質問・要望","question":"一つ目は、３の保幼小の交流事業ですけれども、平成１９年度はモデル実施ですけれども、今年度は全園で実施されていくのでしょうか。小学校１年生の授業を受けるのが月１回ぐらいだと慣れるという意味ではいいですが、体験というレベルでしょうか、例えば２月の間には毎週１回、保育園・幼稚園では小学校に行ってみるというモデル実施みたいなものはいかがでしょうかということです。","respondent":"小林保育課長","answer":"交流事業にかかわるお尋ねがございました。平成１９年度は交流事業をモデル実施という形で取り組みましたが、小学校は２１校が幼稚園・保育園３３園とカップリングをして実施したところです。","voiceIndex":33,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回の調査が１０年ぶりということですけれども、なぜ１０年ぶりに行ったのか、それから品川区独自のものなのか、そのことを教えていただきたいと思います。それから、今回のサンプリング６,０００人の根拠を教えていただきたいと思います。郵送でやるということであればもっとたくさん出して、人数が多いほうが全体がわかる形になるのではないかという思いがするので、その辺のところを教えてください。","respondent":"冨岡高齢福祉課長","answer":"第一期から第三期までの介護保険の基本的な区の考え方はそれほど変わっていないということで、これまで推移してきたわけですが、１０年も経つということと、第四期に向けては今の高齢者の意向はどうなっているのか調べる必要があるという判断で、今回実施したものです。","voiceIndex":40,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"第四期介護保険事業計画の資料にするということですけれども、今年度、第四期介護保険事業計画をつくって、保険料も決めていくことになると思うんですけれども、具体的にはいつ頃までにどのような形で計画がつくられていくのか、１点教えていただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"あわせてパブリックコメントにもかけていくという流れで進めてまいりたい。年度内には事業計画を策定していきたいというスケジュールです。それから、家族の数ですけれども、８１ページの表に出ているような数値の調査の仕方をしておりますけれども、ほかにはいたしておりません。","voiceIndex":42,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"第四期介護保険事業計画については、９月頃に骨子をつくり始めて、１月にパブリックコメントをかけていくことになると、議会には１２月ぐらいに報告があるという感じになるのでしょうか。それから、介護保険制度推進委員会がどのようにされていくのかということもあわせて教えていただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"介護保険制度推進委員会の関係ですが、８月に課題整理をしまして、１０月に骨子案の最初の部分でご紹介をしまして、それから最終的には１２月あるいは１月ぐらいに策定の部分でご審議をいただくという予定をしております。","voiceIndex":44,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１０月に介護保険制度推進委員会に骨子案の紹介をされるということであれば、議会にもぜひお願いしたいと思います。第四期介護保険事業計画を今年度つくっていくわけですけれども、パブリックコメントとあわせて区民に対しての説明会を開いていただきたいということを要望させていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-017"},{"speaker":"須藤委員","kind":"質問","question":"アンケートを取って、課題が幾つかまとめられてきているんですけれども、その辺に対して今後の考え方はどのように整理していくのかということが１点。それから、健康の状態で充分な睡眠時間を取ることというけれども、高齢者にとっての充分な睡眠時間というのはどのぐらいを考えているのか。７時間ぐらいがいいということを言われているけれども、実際にはどうなのか教えてください。","respondent":"冨岡高齢福祉課長、倉橋品川区保健センター所長","answer":"今後は、特に引きこもりがちな高齢者の方には出てきていただくようなことも含めて、検討してまいりたいと思っているところです。充分な睡眠時間というのは、大変難しい問題です。今、委員がご指摘のように、７時間ぐらいが標準的な答えになるかと思いますが、もともと必要な睡眠時間というのは個人差が大きいものです。","voiceIndex":47,"id":"exchange-018"},{"speaker":"須藤委員","kind":"質問・要望","question":"先ほどいただいた「しながわいきいきガイド」の中にある７項目が、元気でという一つの考え方だと思います。あまり大上段に構えて、「さあ、いらっしゃい」と言っても、我々は元気なのに介護予防というのはあまり行かないだろうと思うので、その辺を上手にやりながら、介護予防の施策を考えていかれたらと思うんですが、いかがでしょうか。","respondent":"冨岡高齢福祉課長","answer":"ご指摘のとおり、やはり大事なのはいつまでも元気に高齢者の方が活躍していただくために、どのような事業があるのか、どのような健康活動があるのかということだと思いますので、あくまでも介護予防というのは、ただ事業を展開していく符丁というような意味ですので。","voiceIndex":50,"id":"exchange-019"},{"speaker":"宮崎副委員長","kind":"質問","question":"アンケートを見ますと聞きたいことがたくさんあるんですが、絞って聞きたいと思います。１０年前から今回まで１０年間あるんですけれども、前回の質問との関係で大分内容は変わっているのでしょうか。要するに、普通は前回と今回の比較があるんですけれども、今回はそのような比較がないんですけれども。","respondent":"冨岡高齢福祉課長","answer":"前回と基本的には同じで、むしろ質問数が増えているところがあります。前回との結果につきましても、ご覧いただきますとほとんどの部分で１９９８年度と比較しておりますので、ある程度の比較がおわかりいただけるかと理解しています。","voiceIndex":52,"id":"exchange-020"},{"speaker":"宮崎副委員長","kind":"質問","question":"私が探していたのは、質問の一番最後の「品川区の介護保険のサービス水準と保険料の関係について」ですけれども、今回は回答数の中で例えば比率１のところですと、１の回答が３５.２％、２のところが２６.３％となっています。やはり、後期高齢者医療制度だけではなく、今の高齢者の暮らしがどうなっているのかという角度から見ていかなければいけないのではないかと思うんです。","respondent":"冨岡高齢福祉課長","answer":"これは介護保険制度が始まる前ですので、「わからない」という答えは想定していないこともありますけれども、今回につきましては、決めかねている方もいる可能性があるということで、「わからない」という部分を入れさせていただきまして。","voiceIndex":54,"id":"exchange-021"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"繰り返しになりますけれども、今の高齢者の暮らしが本当に大変だということは、収入のところを見ると、一面ですけれども出てきていると思います。ちなみに、最後のところは意見・要望が自由記入になっているんですけれども、ここはどのぐらい書かれていて、特徴的な意見・要望はどのような内容があったのか聞きたいと思います。","respondent":"木下福祉高齢事業部長、冨岡高齢福祉課長","answer":"聞き方の部分については、例えば４９ページをご覧いただきたいと思うんですけれども、上の表にありますが、この聞き方は世論調査との整合性もありますので、このような聞き方をこの間ずっとしてきております。どのような意見とか要望があったかですが、手元に個々のものは持っておりませんが、報告書の５０ページに傾向が出ておりまして、一番多かったのが生活や健康面の現状報告等にあたるものが一番多く。","voiceIndex":56,"id":"exchange-022"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"とりわけ第四期介護保険事業計画をつくっていく場合には、介護保険特別会計の積立金も約２０億円ありますし、これをしっかり活用していきながらサービスの充実をやってほしいと思います。これは非常に高い要望なので、ここのところは真摯に受けて、第四次長期基本計画の中でも早期に実施する計画にしていただきたいということを言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"実際に介護を受けている方の実態、また事業展開をされている方の労働者の実態も踏まえる必要があるのではないかと思うんですけれども、その辺のところの実態調査、アンケートをぜひしていただきたいと思うんですがいかがでしょうか。","respondent":"冨岡高齢福祉課長","answer":"個々の認定者の方との連絡状況ですけれども、区内に１９カ所あります在宅介護支援センターでは、絶えず認定者の方と連絡を取り合いながら、十分状況については把握しています。","voiceIndex":60,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"渋谷区で区独自の対策を取る中で、２.５時間まで増やされたというのが紹介をされていました。実際に介護を受けられている方の困っている実態を、データとして把握していただきたいと思うんです。事業所を閉鎖するというヘルパーステーションも随分増えているということもあるので、改めて実態をデータとして、また声として把握するということで、ぜひ調査・アンケートをやっていただきたいと思います。","respondent":"木下福祉高齢事業部長","answer":"そういうことも含めまして、検討をさせていただきたいと思います。","voiceIndex":62,"id":"exchange-025"},{"speaker":"高橋委員","kind":"質問","question":"７５ページに「保健福祉サービスについてお伺いします」とありますが、「ご存知ですか」と聞いて「いいえ」と答える方が３０％、４０％、５０％いるんですが、この事業は何かという説明をした文書は入っているのでしょうか。","respondent":"冨岡高齢福祉課長","answer":"おっしゃるとおり、「ご存知ですか」と「参加・利用したいですか」と聞いておりますので、利用したい方は把握しておりますので、今後どうするか検討します。","voiceIndex":64,"id":"exchange-026"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"後期高齢者医療制度の健康診査についてお聞きしたいんですが、国民健康保険の健康診査は生まれた月によって何月から何月までと分かれて、今までは一年中自由に区民健診を受けられましたけれども、そのような仕組みではなくなりましたけれども、後期高齢者の健康診査は国民健康保険と同じような形になっていくのかということと、それは後期高齢者にお知らせをしているのかということについてお聞かせください。","respondent":"永尾高齢事業課長","answer":"通知に関してですけれども、生まれ月によりまして二つに分かれておりまして、４月から９月生まれの方については受診券の発送を５月下旬に予定しております。１０月から３月生まれの方につきましては、７月下旬を予定しています。","voiceIndex":69,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3202#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":28391,"voices":74}},{"id":"h20-20080512-8","meetingId":"h20-cm05","date":"2008年5月12日","dateIso":"2008-05-12","committee":"建設委員会","time":"午後１時０１分～午後２時５９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"に入ります。 (1)の都市高速道路中央環状品川線南品川換気所下部工事説明会","agenda":"に入ります。 (1)の都市高速道路中央環状品川線南品川換気所下部工事説明会","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"工事説明会お知らせのお願いのところに、「地元の皆様方に対して「配布もれ」がないよう十分注意をしましたが」とありますけれども、前回の説明会なんかでも意見交換会の場か、何らかの場所でこういうご意見が上がったのかなと思うんですけど、それについてどういう状況だったのかをご説明いただきたいと思います。","respondent":"梶都市計画課長","answer":"この説明会のほかにも４月２７日には一般の方々で意見交換会を行ってございまして、例えば、この意見交換会などのお知らせにつきましては、各町会の掲示板に掲示したりといった手法もとってございまして、こちらのほうもさまざまな手法をとりながら。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"お伺いしたかったのは、この「「配布もれ」がないよう十分注意しましたが」と書いてあるんですが、前回そういう漏れがあったから、こういうことになったんじゃないのかなと思って、その前回の漏れがどういう状況だったのかなというのが１点と、その品川線の環境の問題も地域の方々にとって非常に関心が高い、まだまだ理解、納得が得られない部分がたくさんある部分ですから。","respondent":"梶都市計画課長","answer":"実は、この説明会のほかにも意見交換会がたびたび開かれているとお話ししたこともあるんですけれども、そのときは、１月の意見交換会の中でどういった形で、全戸でビラを配るのかというご質問も出てございまして、その時期につきましては。","voiceIndex":7,"id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"改築工事が始まって３４回ですか、計画が進められていますが、そのことについて品川区としては、どのように、ここにも書かれているので、働きかけをしていくのかというところを実際にお伺いしたいと思います。","respondent":"梶都市計画課長","answer":"こちらについてなんですけれども、建物につきましては３０ｍということなので、現在ぎりぎりの高さでございまして、それが３０ｍという形だと聞いております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"表立って品川区が対応しなければならないという状況になるときに、その高い建物がもう既に始まっているところで、もう少し吹き上がったところに直接、高層マンションが近くにかかるわけだから、そのことを品川区としてはどういうふうに考えてその対策をとっていくのかということを、環境課が含めてやるんですけど、今、建設の段階でそういうことが予想される中で。","respondent":"梶都市計画課長","answer":"そういうことも含めまして、住民の方にそういった影響が出ないように、私どもとしては、その時代、その時代にですね、最善の方法と申しますか、十分な要望を出しているです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"井上委員","kind":"意見","question":"今回、この環境アセスのことでメッセージを２００４年４月に出したことで、対策を講じられたいということが幾つか出されているんですが、そのことについても東京都の回答はどういうふうになっているのかわかりますか。","respondent":"梶都市計画課長","answer":"山手通りより低い騒音しか発しないと、そういった話を説明会では回答が出ておりますので、そういった形では対応はなされていると考えております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問・要望","question":"品川区長として回答を出されている中で、環境とこういう建物と私は分けて考えられないものだと思うので、たまたまこの品川区が議会の構成というか、委員会で環境と建設が分かれているという状況ではありますけれども、ここのところについてはしっかりと共通認識として持たれていただきたいということを要望しておきますので、その辺はしっかりとお願いしたいということです。","respondent":"梶都市計画課長","answer":"私どものほうも今までも工事、あるいは、住民説明の場につきましては、住民の方に不安が生じないように、十分な対応を、対応というのが説明会だけではなくて、広報等につきまして細心の注意をとる形で要望を出しておりますし、また。","voiceIndex":15,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"３階建て、もしくは４階建てというふうになると、６階建てぐらいの高さの建物になると、下につけるか、上につけるかというのはまだ公開されていませんから、その部分はわからないんですが、教育委員会ではどういう調整をされているのかということを確認だけさせてください。","respondent":"梶都市計画課長","answer":"先ほど出ました除塵の方ではなくて、窒素関係、浮遊物関係につきましては、今、東京都の方で、平成２２年の供用開始までに結論を出すということで、そちらのほうは検討していただくという形でお話を伺ってあります。","voiceIndex":17,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ちょっと確認だけさせてください。今、これは説明会を下部工事でやるんだけれども、今みたいなご質問があった場合、これは上部のことも含めて答えるように言ってあるんだよね。その辺のところはどう思われているのかというのが２点目。それから、これはどこがこの資料をつくったのかというのを教えていただきたい。多いのは。何かここら辺のことはどう思ってこの地図でＯＫしたのかも教えてもらいたい。","respondent":"梶都市計画課長","answer":"今現在、町会の中ではなくて、これからできるマンションについては、東京都の方に十分情報提供をしているところなんですが、これからもこういった意見を、これにつきましては要望という形でなくて、意見、そういった状況も含めながら説明していきたいと考えています。","voiceIndex":19,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今みたいな上部の質問がばんばん来たときに、それは「今日は下部工事の説明会ですので」という態度で臨むのか、上部の話も出れば、それは当日、丁寧に地域の方にちゃんと説明をするという話でいくのか、それを教えていただきたい。そういうことでやるんですかということを聞きたい。だけど、ここは３０ｍ。それでも大丈夫なんですか。そこら辺をちゃんと理論武装を準備しているんですかということを聞きたい。","respondent":"梶都市計画課長、岩田まちづくり事業部長","answer":"今回の説明会という話なんですけども、実際問題、この東京都に関しましたら、いろいろな工事の説明会の中で、地域の方々、いわゆる町会の方々と勉強会、意見交換会というものを持ってございまして、こういった４月２８日のビラ配りの前。ただ、現在これまでの東京都の住民に対する説明の仕方を見ますと、こういう説明会だからといって、事業そのものの説明は質問が出ても答えないとか、そういうひどいことはやっていなくて。","voiceIndex":21,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回の工事説明会のお知らせで印象に残ったのは、やっぱり一番下のお願いのところです。それで、お願いもあるんですが、何か区のほうで建築確認をとって建築説明会、建築紛争等もいろいろあると思うんですが、そのときに業者のほうにやはりこういう一文を書いたものを説明会の案内とともに、案内状を必ず近隣に配布すると思うんですが、これをつけてくれると非常にいいんじゃないかと。それだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-010"},{"speaker":"阿部委員","kind":"質問・要望","question":"この下部工事をすることによって、周辺の主に交通とか騒音とかの問題が必ず出てくると思うんですけど、その内容は現段階である程度把握されているかということと、それから、それについては教育委員会とすり合わせをされていないということだったんですけれども、これは１７日までには学校の要望なんかはきちんと伝わるようになっている、まちづくりは直接ここには関係しないかもしれないんですけれども。","respondent":"梶都市計画課長","answer":"ただいまの工事に関する影響という形なんですけど、こちらの下部工事の説明会が５月１７日に行われるわけなんですけれども、こちらの部分に関しましては、その前に昨年の１０月のときにこちらの委員会にも報告したと思うんですけれども、この工台のほう。","voiceIndex":25,"id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"そうすると、４月末までの工台の工事と、それからこれから始まる下部工事で、特に交通量の増減はないというふうに理解してよろしいんでしょうか。","respondent":"梶都市計画課長","answer":"交通量の増大というのは、その工事に使う車両という形で、これは工事に使う車両なんですけれども、例えば、こちらのところで使う工事のほうなんですけど、土を掘ってそれを捨てたり取るわけなんですが。","voiceIndex":27,"id":"exchange-012"}]},{"id":"topic-02","title":"の大崎駅西口Ｃ地区都市計画素案","agenda":"の大崎駅西口Ｃ地区都市計画素案","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"私からは日影のことと風のことをお伺いしたいんですけれども、まず、日影のほうですけれども、１５枚目の資料を見ると、ちょうど朝方に芳水小学校にかかってきますよね。","respondent":"青木都市開発課長","answer":"ですが、委員ご指摘のとおり、当然、市街地ですので、いろいろな建物が複合して日影が落ちていくというのは事実でございまして、今回、この計画を検討するに当たりまして、私どもが協議していく中で、基本的にはＥ東地区、既にシンクパークタワーが建っているところから。","voiceIndex":33,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"私は学校の太陽を奪うような計画は絶対あってはならないと思うんですけれども、これはまだ手前の西口中地区のいろいろなものの影響はどのように考えているのか教えてください。一緒に風の影響のほうですけれども、１３ページですね。勘違いだったら、指摘してください。今回こういう調査をした理由とか背景とか何かございましたら、ご説明いただけますか。","respondent":"青木都市開発課長","answer":"これもそれぞれの開発の中で個別に検討しておりまして、当時わかっているものについては複合的なことも配慮しながら、学校だから影を落とさないで普通のお宅に影を落としていいという理屈はないんですけれども、市街地程度の影響を少なくすることは配慮しているものです。","voiceIndex":35,"id":"exchange-014"},{"speaker":"中塚委員","kind":"意見","question":"風のほうですけど、風影響評価とかそういうことをしているということですけど、この評価をどんなふうに区は分析されているのか。冒頭のざっとした説明の中ではそれを期待していたので、そこをご説明いただけますか。","respondent":"青木都市開発課長","answer":"大崎駅西口につきましては、実はシンクパークタワーができた後、地元から風が強くなったのではないかというご指摘をいただいておりまして、これはまたそれぞれの事業者のほうに追跡調査するようにと指示しておりますし、また私どもとしても。","voiceIndex":37,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"簡単に質問いたしますと、要はこの１３ページの右と左に前と後があるんですけど、この変化をどんなふうに区は評価しているのかという質問です。今のお話ですと、安全性、快適性に影響はないというふうに結論されているのか、それとも、どうなのか、そこをご説明をいただけますか。","respondent":"青木都市開発課長","answer":"端的に申し上げて、このとおりにちゃんとシミュレーションの結果どおりになるなら、問題ないと考えております。","voiceIndex":39,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"そこなんですけど、大崎にシンクパークタワーができてから、僕は何人かの方に風が強くなったと。区のほうがどう思っていらっしゃるかお伺いしたいんですけど、これは予測と実態にずれが起きていると感じるんですよね。ですから、この予測がどういう予測なのか、実際に説明会で使う資料だというならなおさらですけど、これがよくわからないんですよね。予測と実態がずれていることをどう認識されていますか。","respondent":"青木都市開発課長","answer":"風を検討するのは非常に、口頭で申し上げるのは非常に難しいんですけれども、今、一般的にはこの風工学研究所のやり方などの方式で風環境というのを計るのが最も普及しているもので他とも比べやすいということでこれを採用してもらっているところです。","voiceIndex":41,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"私も風工学というところは全然よくわからないので深めていきたいと思うんですけれども、区として、前と後がどう変化したのかという、今の話ですと、これから検証を進めていきたいというお話ですけど、検証のためにも、その前と後がなければ、検証しようにもできないわけですから、風害を科学的に調査したり分析したり評価する、そういう試験ってどこが強いか。予測の想定の中に。","respondent":"岩田まちづくり事業部長","answer":"ただ、風洞実験の場合はある一定方向から直線的な風を送ります。建物はぐるっと回して実験をしていくわけですけれども、ですから、１年中通じて、北から、ずっと東、西の風、全部に対応して、その最大の数値が出るポイントをここに落としているんです。","voiceIndex":43,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"この計算とかを確率から出している。だから検証を進めていきたいというお話があって、その具体的な中身にはちょっと触れなかったので、これはもう一遍伺いたいと思うので、ご答弁ください。それと、この１３ページのこの表はよくわからない。いろんなシミュレーションがある中でこれを選んだ理由が、有名だからという話がありましたけど、もっと風の影響について十分な資料が必要なんじゃないかなと。","respondent":"青木都市開発課長","answer":"そういった点では、行政だけではなくて民間の方も含めまして、風について一般の区民の方々の理解を深めるという点では、委員のご指摘のとおり、まだまだこれからなのかなですけれども、こういう普及しているものをうまく活用しながら。","voiceIndex":45,"id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"大変に不勉強なので教えていただきたいんですが、これは延べ床面積約１２万５,０００m2で、研究開発型オフィスだと書いてある。一般論でいいんですけど、教えていただきたいのと、こういう場合の通常のオフィスだったら、昼間の来訪者は大体どれぐらいと見るのか。こういう開発型オフィスだとどれぐらいと見るのか、こういう一般的な話でいいですが、もしわかれば、教えてください。","respondent":"青木都市開発課長","answer":"順番逆転しますけど、この建物ですけれども、この建物は研究開発型ということで、若干一般のオフィスビルよりも低めに見積もってございまして、１日の出入り、出る人と入る人、それぞれ１人ずつ数えますと、２万１,５００人ほどの出入りということで想定しておりまして。","voiceIndex":47,"id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"必ずオフィスの本当の面積の部分というのがありますよね。これほど規模の大きい会社だと、例えば、開発だとか研究開発はまた別として、こういうオフィスの場合だと、１人当たり何m2ぐらいが、一番そういう仕事をするに当たってだいたいあてがわれるかというのは、各企業が持っていると思うんですけど、それくらいの部分はこういうときって何か計算式に出てくるものですか。","respondent":"青木都市開発課長、片田建築課長","answer":"そこでは、９.５９ｈａの床面積に対して、１日の入退館が１万８,０００人。ですから、９,０００人近くだそうです。建築計画の中では、机と机の間を３.２ｍと想定して、反対側のオフィスの机が並んでいるその中心間隔が３.２ｍだと。なんですけれども、大体１人当たり三、四m2。代器を置いたりとか、本棚とか、机とかなんかがありますと、たしか、記憶の中では４m2とか５m2ぐらいまでの幅の中で、想定を考えていくといったことがあります。","voiceIndex":49,"id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"意見","question":"どうしてこんなことを聞いたかというと、多分この上場企業というかソニークラスの会社は、結構平米数は余裕を持っているんですよ、必ず。だけど、それは一上場企業であるとするなら、区は職員の方々に平米数があるわけです、必ず１人当たり。多分この上場企業の方々より、区の平米数はそれより異様に少ないですよね。やっぱりそういうことは、上場企業はこれぐらいは使っていますよと。","respondent":"片田建築課長","answer":"特に庁舎なんかですと、会議室とか、それ以外の執務空間とは別に、集会を行ったりとか、会議を行ったりの場でとられる場所もありますので、そういうのを基本的に参考にしながら効率的な計画を進めていくというような状況ですので。","voiceIndex":52,"id":"exchange-022"},{"speaker":"三上委員","kind":"意見","question":"このＣ地区の計画は今回わかりましたけれども、西口南地区、要するに区が絡む計画についてはどうなっていますか。","respondent":"青木都市開発課長","answer":"南地区につきましては、都市計画変更、地区計画の変更と、さらに市街再開発事業の都市計画決定というものを昨年平成１９年８月２２日に告示しています。","voiceIndex":55,"id":"exchange-023"},{"speaker":"三上委員","kind":"質問","question":"そうすると、先ほどちょっと風の問題が出たけれども、この今のソニーの部分だけの風を計算した部分で処理されているのか、それとも、今、中地区それから南地区という部分が、既にそういう建物ができあがったという状態での計算されたような風の流れというふうに読んだらいいのか、どっちなんですか。","respondent":"青木都市開発課長","answer":"ですから、若干問題になりますのは、今申し上げましたように、それぞれの事業時期がずれますので、その建物が建つすべての計画が完了するまでの間は、実はシミュレーション結果と違った風が悪さする可能性がありまして、今回、地元でいろいろご指摘いただいているのは。","voiceIndex":57,"id":"exchange-024"},{"speaker":"三上委員","kind":"質問・要望","question":"今後の問題もあるんだけど、最初にそういうことを説明するときに、それをきちんと前提はこうですよということを言っていただいて、説明していただいたほうがわかりいいのかな。もう少し研究していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-025"},{"speaker":"阿部委員","kind":"質問","question":"この計画の最初の１枚目のところで、平成２１年着手、平成２３年竣工予定とあるんですけれども、ここの周辺区画道路ですとか、あるいは、交通広場といったものは同時に竣工ということになりますか。これより早くなるのか遅くなるのか教えてください。","respondent":"青木都市開発課長","answer":"駅前広場につきましては、区のほうで施工することになるだろうというふうな調整をしていますけれども、来年度に設計して、平成２１年度に施行したいと予定しております。ソニー地区の完成と同時にオープンすると。","voiceIndex":60,"id":"exchange-026"},{"speaker":"阿部委員","kind":"質問","question":"この最初におっしゃった区画道路は、中地区との間は１号だと思いますけれども、南地区との間の２号というのはいかがでしょうか。公園など半分以上が南地区に入っているということなんですけど、例えば、部分的にでも供用するということは考えていないですね。そういったお考えがあるかどうか。","respondent":"青木都市開発課長","answer":"これにつきましては、地元の声を踏まえて、部分開業することも不可能ではないので、検討してまいりたいと思います。","voiceIndex":62,"id":"exchange-027"},{"speaker":"阿部委員","kind":"質問","question":"先ほどから風の話が出ていますが、地上の人に当たる風向きだけではなくて、今、都市部では上昇気流がビルの中から発生して、それが都市型集中豪雨の原因になっているような話も聞くことがあります。例えば、こういった高いビルができることで、そういったリスクが増す、増さないといったような検討というのはされているのでしょうか。","respondent":"青木都市開発課長","answer":"その対策としては緑化をするとか、蒸散作用があるもので、地表の温度上昇を防ぐとか、対策が検討されておりまして今回の建物では敷地の５０％近くを緑化する対策で何とかヒートアイランドに対するひとつの答えを出していきたいと計画されているものです。","voiceIndex":64,"id":"exchange-028"}]},{"id":"topic-03","title":"の大崎ウェルカム・ビジョン","agenda":"の大崎ウェルカム・ビジョン","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"この大崎ウェルカム・ビジョンって、でっかいテレビのことだと思うんですけれども、これは幾らかかるんですか。ランニングコストの面で教えていただきたい。補助金というんですか、税金が入っているのか、いないのかそこの確認だけお願いします。そこのところをあわせてご説明いただけますか。","respondent":"青木都市開発課長","answer":"それと「有限責任中間法人大崎エリアマネージメント」の活動範囲ということなんですけれども、これも、設立のときのご報告で、うちの委員からも十分気をつけて使っていきなさいというご指摘いただいておりまして、私どもも注意していますけれども、基本的には。","voiceIndex":70,"id":"exchange-029"},{"speaker":"井上委員","kind":"確認","question":"今のところで、確認なんですけれども、先ほど、地域の企業の広告とかというところの話もあったんですけど、結局この施設としては、この大崎のまちづくりのこちらの関係のものということで、区としての関与、コスト・税金として投入されるものということは、運営費として６０万７０万を按分するというお話でしたので、区としてそういう支出をするものはないのかということと。","respondent":"青木都市開発課長","answer":"一方で、どうしても赤字ばっかり垂れ流しになってしまうということであっては、これはせっかくつくった地元の組織が立ち行かなくなってしまいますので、あまりにもひどい場合には区が何らかの支援を行えるのかどうか、そういったことも現在検討しています。","voiceIndex":72,"id":"exchange-030"},{"speaker":"井上委員","kind":"質問","question":"使用許可というのは無償提供ということなのかということと、これからの協議の問題というところにも含まれているんですけれども、ここにずっと赤字が続いたようなときには、補てんをするとかというのは、どこでどういうふうに協議をして決定される仕組みをつくっていこうとしているのか。協議の段階でこの検討ということもあるかもしれませんけど、区としての考えはどういったものでしょうか。","respondent":"青木都市開発課長","answer":"特別な規定があることによって、一般的に減額、あるいは免除、あるいは特別な協定等によって免除というような方法が幾つかありますので、その中で今回の設備の趣旨、あるいは大崎エリアマネージメントという団体の設立趣旨などを踏まえて。","voiceIndex":74,"id":"exchange-031"},{"speaker":"井上委員","kind":"質問","question":"初めは運用開始が平成２０年６月ということは、もう一月ぐらいしかないんですけれども、それまでに今お話をされたことは決定をされていくというスケジュールでしょうか。","respondent":"青木都市開発課長","answer":"ご指摘のとおりです。","voiceIndex":76,"id":"exchange-032"},{"speaker":"阿部委員","kind":"質問・要望","question":"確認させていただきたいんですが、今、この場所では、白い幕がかかった巨大な物が置かれていると思うんですけど、これがウェルカム・ビジョンということでよろしいんでしょうか。ちゃんとクオリティーの高いものを提供していかなければ、目障りなだけですから、そこら辺をどういうふうにつくっていくか。それを効率をどのように維持にしていくのかということを教えてください。","respondent":"青木都市開発課長","answer":"６月半ばには何らかのささやかなオープニングイベントをやろうと考えています。現在そのコンテンツなどの充実が間に合っていないものですから、ハードができ上がったけど、オープニングができないという状況です。","voiceIndex":78,"id":"exchange-033"},{"speaker":"阿部委員","kind":"質問","question":"コンテンツについてもう少し伺いたいんですけれども、これは基本的に静止情報、イベント情報とか、あるいは店舗情報も含めて、それとも、これ専用の番組というものをつくっていくものなのか。","respondent":"青木都市開発課長","answer":"現在考えていますのは、独自の映像をつくって流す。ただ、立ち止まって見ていただくものではないので、なるべくアイキャッチ的な、１０秒、１５秒とかの内容を繰り返し流せるもののイメージが強くなっています。","voiceIndex":80,"id":"exchange-034"},{"speaker":"阿部委員","kind":"質問","question":"もちろん、地元の物を流すというのもいいことだと思います。しかし、公共の場ですので。鑑賞に耐えるものでなければならないのです。一番右下のにぎわいフラッグという写真が絵があって、青い旗に品川区と書いてある。これは参考までに書いたということですか。実際この青い品川区の旗は。","respondent":"青木都市開発課長","answer":"それと同じようなものをやっていきたいということで、たまたま今回、資料としてまだ具体的なスポンサーはついていませんので、たまたま品川区というものをモンタージュしてあそこにつけたものです。","voiceIndex":82,"id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"質問","question":"間違っていたら、教えてください。ここって、自由通路って、道路の一部だったと思うんだけど、もし違ったらごめんなさい。道路の位置づけだとしたら、こういうものを行政財産に企業広告を行うというのは、どういう許可に基づいてというか、どういう方法論でというか、どういう理由づけをしたというか、言いわけをうまくつけたのか、それを教えて。","respondent":"青木都市開発課長","answer":"道路じゃないけれども、区の財産であるという位置づけになっていまして、結論から言うと、道路法の適用を受けないので、屋外広告物条例の適用も入らないということで、こういったことが可能になった。けがの功名という形です。","voiceIndex":84,"id":"exchange-036"},{"speaker":"石田（秀）委員","kind":"意見","question":"今、ちょっと意味がわからなかったんですけど、線路の上はかからないということですね。線路じゃなくて道路の上はいいのか。これはよくわからないんだけど、私のイメージでは今までは全部道路という位置づけかなと思っていたんだけど、それは違うということで理解するのか。この線路よりこっち側の道路の上にあるよね。それは道路なのかということも改めて。","respondent":"青木都市開発課長","answer":"デッキとしては一連のものなんですけれども、ゲートシティーの敷地の中は民間の施設です。山手通り、都道環状６号線の上と区道補助１６３号線および、この付属する交通広場の上のデッキ部分については、これは区道。","voiceIndex":86,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"お話の中で、ソフト面のところをもう少しお伺いしたかったんですけど、さまざまな情報や番組を、という話の中で、品川区のかかわりの形が見えてこないんです。説明の中では広報広聴を図ったり、ケーブルテレビ品川自身にも品川区のかかわりがあるんだけども、番組の制作とか情報の提供とか、どういう権限でどういう参加をしているのか、そういうことが形が見えない。","respondent":"青木都市開発課長","answer":"広報広聴課が持っている映像コンテンツ、あるいは写真などを、この事業のために活用してほしいということで、提供することは、この地域活用の支援という位置づけで品川区からの情報提供があるという。","voiceIndex":88,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問","question":"区としての権限では使用許可というところで権限として握っているというんですけど、行政財産を使って行うわけですから、歯止めというか、物差しというか、基準というか、それがよくわからない。話の節々の中で、例えば企業のＣＭがじゃんじゃん流れると、これはどうなんだとなると思うんです。使用許可という話がありましたが、どういうラインで、どういう物差しでしっかりと見ていくのか。","respondent":"青木都市開発課長","answer":"ウェルカム・ビジョンにつきましても、まず、皆さんとでつくりました都市再生ビジョンの中に掲げております継続的に発展していくための仕組みづくり、その１つとしての情報発信ですので、確かに抽象的な物の言い方になってしまうんですけれども、大崎のまちの活性化。","voiceIndex":90,"id":"exchange-039"},{"speaker":"三上委員","kind":"意見","question":"地域情報ボードというのは、ガラス面から少し飛び出して足をつけて取り付ける仕組みになっているのか、それともガラス面のところからそういうところから直接取り付けるような感じになっているのか。","respondent":"青木都市開発課長","answer":"全部で３７面ほど用意しているんですけれども、基本的には現在ありますガラスの手すりというのか、ガラス面を支えているステンレスか何かの柱がありますけれども、高欄と言いますけれども、そこに抱かせる形で、設置できているはずです。","voiceIndex":92,"id":"exchange-040"},{"speaker":"三上委員","kind":"質問","question":"このウェルカム・ビジョンはこのガラス面から飛び出すように地上面に設置するような形になりますよね。というところに、人の流れがそこにずっとあるということになったときに、ここの場所が適当なのかどうかということについては、どういう判断をされたのか。そうなったときにそういう人の流れの混雑状態に合わせて、事故のもとにならないのかとか、そのあたりはどういうふうに検証されたんですか。","respondent":"青木都市開発課長","answer":"先ほどから申し上げますように、大崎のイメージを刷り込むための装置ですので、どちらかというと、広報広聴課がつくったり、ケーブルテレビ品川で放送しているような、長い番組ではなくて、極端な話、大崎のメーカーさんの工場に行って工場のラインでも映しているような。","voiceIndex":94,"id":"exchange-041"},{"speaker":"三上委員","kind":"意見","question":"たしかに、改札を出てきた人にとって見ると刺激があって、いいのかわからないけれども、こういう自由通路という形で幅広い通路をつくった由に、人の流れがそういう横に流れていくというのは、どうなのかというあたりについて、それは当然考えたと思うんだけれども、そういう接触事故みたいなのはありませんよと、そのように言い切っていいのかどうかということなんだけれども。","respondent":"青木都市開発課長","answer":"このビジョンがあったことによって、直ちに事態が悪くなるというようなことにはならないというふうに考えて、中身についてもそういった運用を図っていくつもりです。","voiceIndex":96,"id":"exchange-042"},{"speaker":"阿部委員","kind":"質問","question":"これは音声を出すのかどうかということと、それから、放映時間は何時から何時までと考えているのかということを教えてください。","respondent":"青木都市開発課長","answer":"まさに、委員がご指摘のとおり、うるさいとか、目障りだとかという声もあるかもしれません。そういったものを地元の声を配慮しながら、運用しながら考えていくことだと考えています。","voiceIndex":100,"id":"exchange-043"},{"speaker":"阿部委員","kind":"質問・要望","question":"大勢が集まる場ですから、渋谷の屋外テレビみたいな感じになってほしくないという意味で音声のことを聞きました。基本的には山手線内の電車内広告などは音声抜きで伝わるように組み立ててある。ああいうイメージだとありがたいなと。仕組みはつくっておられるのか。それとも貸したんだから、エリアマネージメントが決めることで、区は要望を出すだけという関係にあるのか。","respondent":"青木都市開発課長","answer":"それに当たっては、当然地元からの町会の声とか、こうした委員会での請負の方々のご意見等をいただいておりますので、そういったものは区が受けたものは区から地元のほうへ伝えますし、エリアマネージメントでも。","voiceIndex":102,"id":"exchange-044"},{"speaker":"井上委員","kind":"質問・要望","question":"区民の方とか、地域の方からも出るか出ないかわからないので、そういう要望があれば対応できるような、そういう緩みもとっておいてほしいなというところは意見としてお伝えしておきたいということが１つと、もう１つは、先ほど６月の中旬に向けて協定を進めて決定していきたいということだったので、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-045"}]},{"id":"topic-04","title":"の区民住宅（あき家）入居予定者登録募集","agenda":"の区民住宅（あき家）入居予定者登録募集","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"参考までに聞かせてください。この１年間ではどの程度空きが出たんですか。","respondent":"齋藤住宅課長","answer":"現在の空きの数は３４戸です。今回募集すると、二十二、三ぐらいに毎年のパターンで減ると思います。","voiceIndex":109,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3908#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":35440,"voices":112}},{"id":"h20-20080512-9","meetingId":"h20-cm05","date":"2008年5月12日","dateIso":"2008-05-12","committee":"文教委員会","time":"午後１時０３分～午後４時１０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"校舎改築事業の進捗状況","agenda":"校舎改築事業の進捗状況","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"手当はしても、解体に伴って露出せざるを得ない状況というのは当然あるわけですから、この学校に限らず、これから幾つか工事があるわけですから、その辺のことも安心のためにお知らせいただきたいと思います。ですから、その辺をどういう考え方をされるのかを、ちょっと伺っておきたいと思います。","respondent":"田村庶務課長","answer":"５点目とダブりますが、品川地区の小中一貫校につきましても、やはり懇談会を５月からやってありますので、先ほどご説明の中で申し上げたとおり、基本計画がほぼまとまりつつありますので、地域との懇談会をやる予定ですので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"それから照明の関係ですけれども、５月の末から迂回工事を始めていただくのは全然構わないと思うんですけれども、地域の説明会でも伺っているところなのでそれは承知しているんですけれども、今、とにかく小学校部分だけでも、校舎はグラウンドの向こうですから、１００ｍはないですけれども、数十メートル遠いところにあるし、真っ暗だし、あと多目的広場のほうも真っ暗だし。","respondent":"市川教育次長","answer":"１点目のアスベストの関係ですけれども、これは３年前に区有施設のアスベスト対策で、区有施設全般の対応策を検討した結果を議会のほうにも報告させていただいてありますけれども、当時の考え方、原則的に囲い込みを含めて。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"でも一定の時間帯は、あるいはコースは生徒の授業で使うわけですから、当然そこは使えなくなって、一定程度の制約が出てくるので、なかなかその辺は使い勝手が悪くなっちゃうかなという意見もありましたので、そういうふうに一般開放をすることを考えていたのであれば、小中一貫校というところに施設をつくるのではなくて、別立てでしていただけるように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"山内委員","kind":"質問・要望","question":"ちょっと教えていただきたいんですが、第三日野小学校の渡り廊下がありますよね。この安全性というものを考えるときに、この道路から渡り廊下までの高さ。例えばここは住宅地域だから、あまり工事の車とかは通らないと思うんですけれども、比較的この背の高い車、例えば引っ越しの車とかが、そういう車が通るときの安全性とか、そういうのをちょっと教えてください。","respondent":"田村庶務課長","answer":"第三日野小学校の資料を見ていただいて、下段の３階平面図というのをごらんいただきますと、北校舎の３階平面図の南校舎棟の１階平面図、現地をご存じの方は、第２校庭が歩道橋を上がって、学校の正門から上がっていくという形なんですが、ちょうど階数で言うと。","voiceIndex":10,"id":"exchange-004"},{"speaker":"山内委員","kind":"質問","question":"それとこの計画、各学校に比較的多いのが、環境問題というものを配慮した校舎を目指して建設するということなんですが、これは例えばそれというのは、私も小山小学校を視察に行ったときに、例えばドアが大きくて、自然の光を取り入れやすい設計とか、例えば屋上緑化とか、あとはベランダをデッキ状態にして、比較的コンクリートをなくすというか、そういう形での環境に対しての対処だと思うんですが。","respondent":"田村庶務課長","answer":"やはり大規模な学校で、これから改築計画だとか一貫校を進めるということで、構造だとか地形がそれぞれ異なりますけれども、可能な限り、小山小学校もそうですけれども、屋上緑化だとか、あるいは構造によって、外気を入れて、できるだけ外気を利用した形にするとか。","voiceIndex":12,"id":"exchange-005"},{"speaker":"金野委員","kind":"質問","question":"２点ほどお伺いしたいと思います。１点目はプールに関してなんですが、第三日野小学校のプールは屋上のプールですよね。そして、荏原西地区のこの小中一貫校のプールは屋内プールで最上階のプールですね。西地区の屋内プールの天井の構造というのは、最上階なんですが、どのようになっているんでしょうか。","respondent":"和氣小中一貫教育担当課長","answer":"この部分につきましては、長い期間使えるようにということで、透明の部分がありますが、全部覆わないという形になります。ですから、伊藤学園のようにドームとかいう形ではなくて、固定式の屋根がつく予定になっております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"金野委員","kind":"質問","question":"それと同時にこの第三日野小学校のほうは屋上ですので、授業中、プールサイドで休むときに日除けの部分というのは、この絵を見るとどこかなという感じなので、夏場はどうなんでしょうか。","respondent":"田村庶務課長","answer":"第三日野小学校の日除けの関係ですが、この図面上は何もかいてございませんが、今後日除けをつくる形で考えておりますので、今の段階ではない形になっておりますが、今後はあるような形になるです。","voiceIndex":20,"id":"exchange-007"},{"speaker":"金野委員","kind":"質問","question":"単純な疑問なんですけれども、八潮の小中一貫校のこの図面で、それぞれ学年のクラスの配置が出ているんですけれども、この配置の根拠というんでしょうか、理由というんでしょうか、教えていただけますでしょうか。","respondent":"和氣小中一貫教育担当課長","answer":"とりあえずクラス数を確保するという意味でこの配置にしてあるということでございまして、全部３クラスですけれども、今のところは仮です。もうちょっと検討をした上で、具体的な配置は考えてまいりたいと考えております。","voiceIndex":22,"id":"exchange-008"},{"speaker":"金野委員","kind":"質問","question":"そうすると、私も日野学園と伊藤学園の配置が頭に入っていないんですけれども、この配置の仕方によっては、せっかくの小中一貫で１年生から９年生まであるので、学年できっちり小学校部と中学校部で分けるような配置じゃなく、何か異学年で交流を持てるような配置だったでしょうか。そういうのがあったんでしょうか。","respondent":"和氣小中一貫教育担当課長","answer":"新校舎のその配置も考えており、図書室の動線ですとか、プールへの動線ですとか、ランチルームへの動線とか、そういうものを踏まえまして、必要なときにどういう形で異学年交流をどうとれるのかということで、配置を再度考えてまいりたいと思っているところです。","voiceIndex":24,"id":"exchange-009"},{"speaker":"金野委員","kind":"質問","question":"そうすると、仮に今、こういうふうにクラスを分ける形でかいてあるけれども、何となくそういう形のものであると、この図面でいくと、一番左側の下の２階平面図の中に３年生と４年生、その横に８年生と９年生がいるというのは、これは仮にとしたんですけれども、何となくそういう異年齢交流というのも考えての配置はこんなふうになるという理解でいいんでしょうか。","respondent":"和氣小中一貫教育担当課長","answer":"今の八潮での実際の八潮地区なりのカリキュラムでいろいろ動いておりますけれども、これを実際１年間やってみまして、どういうのが一番効果的な交流になるのかというのを検証した上で、再度配置したいと考えています。","voiceIndex":26,"id":"exchange-010"},{"speaker":"金野委員","kind":"質問・要望","question":"最後、要望で。せっかくこの異年齢というところでの交流を、当然日野学園も伊藤学園もされてきたと思うんですけれども、異年齢の効果というのは非常にあるんだなというのを、ほかのところでだったんですけれども、感じたことがありますので、よりクラスの配置もそういったところも考慮していただくということなので、ぜひその辺もよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"利用できるところが第２体育館という形になるんですが、多分第２体育館も使われていくと思うんですけれども、ほかの施設なんかも、図書館を使ったりとか、そういうことなどとすると、離れているところまで行って貸していただくという形になっちゃうのか、その運用が非常にやりづらくなるのかなと、安全性はどうなのかなと気になりましたので、その点と、それから、第一日野小学校のところですが。","respondent":"田村庶務課長","answer":"ですから、こちらのすまいるスクールのところを、屋内平面図のほうにありますけれども、そちらのほうで、確かにけがだとか、連絡だとかという点を考えると、北側校舎の中に管理部門が入っていますので、その辺、確かにあるかなと思いますが、逆に第２体育館のほうも利用できる。","voiceIndex":29,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"第三日野小学校のすまいるスクールについては、ちょっと離れている。それから第一日野もわかりました。それと、建築計画はだれが決めたんですかということを聞きたかったんですね。わかりますか。ただ特徴の１つになっているんだろうなと思うんですけれども、その特徴の出し方がどういう出し方をしているんですかということをお願いします。","respondent":"市川教育次長","answer":"一番大切なのは、学校施設ですから、多様な学習活動への対応、これをいかに実現していくかという、そこのところが基本的なコンセプトになっています。","voiceIndex":31,"id":"exchange-013"},{"speaker":"石田（慎）委員","kind":"提案","question":"何点かお聞きしたいんですが、まず１点目は、報告書の中で準備会となっているんですけれども、品川地区だけ懇談会という形になっているのはなぜなのかがまず１点で、２点目はその次のページなんですが、八潮地区なんですが、１階平面図等を見しますと、グラウンドが５０ｍ走とか１３０ｍトラックだとか、そういった内容がかかれているんですけれども、ここだけ何で１、２としかかかれていないので。","respondent":"田村庶務課長、市川教育次長","answer":"それと２点目の八潮の関係ですが、ほかの改築だとか小中一貫と違って、ここのグラウンド１、グラウンド２というのは、ちょうどかぎ括弧のところが八潮公園となっていますけれども。最後の避難所との関係ですけれども、これは当然のことながら、地元の町会関係者、防災協議会の関係者の皆さん方と、防災課のほうできちんと問題の整理をして、単独改築の場合にはそのままというのがあるんですが。","voiceIndex":33,"id":"exchange-014"},{"speaker":"市川委員","kind":"質問・要望","question":"品川地区の小中一貫校は、先ほども説明ではほぼ基本設計がまとまって、改めて報告するというふうに伺ったんですけれども、ほぼまとまった段階で、何階建てで、高さとしてはどのくらいになるのか教えていただきたいんですけれども。","respondent":"田村庶務課長","answer":"まだ最終調整中なんですが、今のところ基本計画では小・中合わせて３２学級で、地上４階建て、塔屋１階というのを予定しています。","voiceIndex":36,"id":"exchange-015"},{"speaker":"市川委員","kind":"質問・要望","question":"ここの地域は中央環状品川線の換気塔が計画されている地区かと思うんですけれども、当然学校への環境というところは配慮されていると思うんですけれども、その辺、まちづくり事業部のほうとどういう協議がされているのか、教えていただきたいんですけれども。","respondent":"市川教育次長","answer":"もう一方で、学校改築の際には、当然のことながら、学校自体のさまざまな環境面での配慮をいたしますので、特に品川地区の場合には、周辺のグリーンベルトとのつながりの中で、環境保全も含めて、一層の学習環境の向上ということで、基本設計を進めてきているところです。","voiceIndex":38,"id":"exchange-016"},{"speaker":"市川委員","kind":"質問・要望","question":"換気塔の高さが２５ｍと聞いているので、この地域にとっては、とてもその辺が学校に影響があるんじゃないかという心配の声も聞きますので、ぜひ学校への影響というところはきちんと調査をして、まちづくり事業部のほうと連携をとりながら進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-017"},{"speaker":"西本委員","kind":"意見","question":"もう１点だけ。第一日野小学校の幼保一元施設のところですが、５階が０・１・２歳、４階が３・４・５歳になっているんですね。教育施設とつながっているんですが、それとプールが６階になっているので、騒音とかは問題ないのかとか、あとは外部との接触がどういう設計になっていくのか、幼保だと衛生面も含めてシビアにならないといけないと思うんですね。","respondent":"田村庶務課長、市川教育次長","answer":"それと出入りの先ほどの話のあれでしょうけれども、色的には水色のところ、一番左の１・２階平面図を見ていただきますと、スタジオだとか、右方の建物等が出入りできる動線という形になってあります。ですから、これで４階と書いてあるとかなり高低差があるように思うんですが、実際の利用にあたってはそんなに困ることはないと思います。","voiceIndex":41,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"要望として聞いていただきたいんですが、先ほどもちょっとお願いしたんですが、第一日野小学校のところはいろいろな使い方があるので、安全も含めて、どういう人の動きになるのかというのをお示しを今後していただきたいと思っているんですね。","respondent":"市川教育次長","answer":"これでは動線まで示した図面になっておりませんので、基本的には小学校は小学校、これは小学校のセキュリティの観点から、小学校の独立性というのはまず第一に考えてあります。","voiceIndex":44,"id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"この配置図のところで見ると、教室が南向きになっているのが、屋上緑化と書いてあるこのあたりの教室ぐらいで、あとみんな北側に窓が向いているという状況じゃないかなと思うんですけれども、そこをちょっと確認したいのと、敷地の関係でこういうふうにとらざるを得なかったのかなと思うんですが、その辺はどういう議論でこうせざるを得ないかなという経過になったのかをお聞かせいただきたいのが１つと。","respondent":"和氣小中一貫教育担当課長、田村庶務課長","answer":"先に校歌のご説明を申し上げます。残念ながら３月の開校式に間に合いませんで、一たん入ったんですけれども、もう１回調整をしたいということで、作曲家の先生に再調整をお願いしているところであります。ご指摘の校舎の向きだとか、その辺の話ですけれども、ここの図面を見ていただきますと、１年、２年、あるいは３年、４年と、低学年、中学年、高学年をこの校舎の中におさめるということで、当然そういう向きの話も出ていた上に。","voiceIndex":46,"id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"配置上せざるを得なかったという話で想像したし、そういうお話だったんですけれども、１日の大半を過ごすのが学校ですし、この周辺に住んでいらっしゃるお子さん、今は選択制ですから、必ずしもそうじゃないとは思うんですけれども、結構学校の中で過ごす太陽というのは、子どもの成長にとって貴重だと思うんですけれども、その辺はやむを得ないということでいいのかなとちょっと思ったんですけれども。","respondent":"市川教育次長","answer":"私どもも平地に建設できるんでしたら苦労はないんですけれども、特にここの敷地の場合は傾斜地ということで、かなりいろいろな制限の要因が伴ってございましたので、私どももいろいろな検討をした結果こういう配置になったということで、受けとめていただければと思います。","voiceIndex":49,"id":"exchange-021"},{"speaker":"南委員","kind":"意見","question":"それはそれとしてやむを得ないということは理解はできるところですけれども、今の校舎の配置からしても、ここの上の小さな図なんですが、子どもたちの生活する教室がどういうふうに配置されているのかわからないんですけれども、多分想像するのに、随分南からの光が取れ入れられるような状況になっているんだろうと思うんですけれども、そういう考え方をとろうと思えばとれたと私は思うんですけれども。","respondent":"市川教育次長","answer":"そこで、先ほどいろいろな検討の結果といった具体的な検討の比較対象したのが今の点ですので、あとはいかにこの設計上の工夫をしたかということは、物ができ上がった時点でもう１度見ていただいて、その上で説明をさせていただきたいと思います。","voiceIndex":51,"id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"最後ですけれども、グラウンドをできるだけ多くとりたいと、そこは教育委員会としては当然の希望だとは理解できるし、私もできたらそのほうがいいんじゃないかとは思います。校庭は今までと比べてどのくらい広くなったのか、この数字だとその辺は私も読み取れないので、そこをちょっと教えていただきたいと思います。","respondent":"市川教育次長","answer":"こういったことを含めると、実質の有効面積としては今の第１校庭と第２校庭を合わせたものより広い校庭が確保できたということで、先ほど言った広い校庭の確保ということを実現したと私どもは考えてあります。","voiceIndex":53,"id":"exchange-023"}]},{"id":"topic-02","title":"学校給食をめぐる状況","agenda":"学校給食をめぐる状況","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"値上げをするということで検討しているという話でしたけれども、１０年間値上げしてこなかったと。そして、この８区が改定をしたという話なんですが、私もいろいろ調べてみたら、４区程度しかわからなかったので、どういう区が改定されたのか、その改定の状況はどのくらいの値上げ、率でも額でもいいんですけれども、もしわかれば教えていただきたいと思います。","respondent":"富田学務課長","answer":"改定している区についてですが、８区の内訳は、文京区、千代田区、渋谷区、目黒区、荒川区、杉並区、豊島区、墨田区、以上でございまして、区により違いますけれども、本区と同様に１０年たっているというところは文京区１区だけでありまして、７年ぶりであるとか。","voiceIndex":60,"id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"こういう時期なだけに、私はそういうふうに思うんですね。そういうことを考慮された中で、時期と額を検討していると私は理解していきたいと思っているんですけれども、しかし、値上げを検討する以前の段階で、区としてやらなければいけない努力というのは何なのかという、もしこういうことをしていますみたいな、そういうことが紹介されているのがあれば教えていただきたいと思います。","respondent":"富田学務課長","answer":"ただいま家計負担というお話がございましたけれども、そういったことに配慮すればこそ、他区のように４月の値上げということでなく、ぎりぎりの辛抱をしてきたという状況があるかと思います。","voiceIndex":62,"id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"小麦の高騰、そしてバイオ燃料の小麦、トウモロコシとか、そういう穀物がそちらのほうに大きく生産そのものが変わってきただとか、また石油の価格の高騰だとか、いろいろあっての今日の事態なので、品川区あるいは日本の国だけがどうこうすればいいというふうにはなかなかならないので、本当に苦労するところなんですけれども、しかし日本の国民生活が今、本当に厳しい状況の中にあるだけに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"地域のものとかを取り寄せて、栄養とか、自然食品とか、そういう工夫はされていると思うんですが、仕入れのお肉１００ｇ幾らとか、そういう規定ってあるんですか。例えばお店によって値段が変わると思うんですね。それはどういう調整をしているんでしょうか。そういうのは、どうなっているんでしょうか。","respondent":"富田学務課長","answer":"産直野菜、多古町等々、産直の品物につきましては、先々まで値段が決まっていますので、比較的今回の値上げの影響は他ほどではないというところなのですが、すべてを産直野菜のところで補うというふうにもしておりませんので。","voiceIndex":65,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"そうすると、学校の仕入れ先によって、この金額で、価格を変えていくといったときに、それで十分なところもあれば、不十分なところも出てきてしまうということもあり得るんじゃないかと思うんですが、そこの価格の調整というのはどういう形で調整していくんでしょうか。","respondent":"富田学務課長","answer":"しかしながら、購入にあたっては、すべて共同購入でという方針を品川区は従来とっておりませんで、各学校の購入という形を継続している方針を持っておりますので、その辺はやむ得ないものかと考えています。","voiceIndex":67,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"この価格は多分値上げするんだろうなと思いますけれども、そのときの価格を決めるときに、学校によってばらばらなわけですね。もうちょっと価格を学校ごとによって工夫しなきゃいけないという部分を、何とか配慮できるような価格体系であったりとか、あとは余ったお金をマンモス校から小規模校に渡すとか、そういう価格的な負担を学校側の差がないような形にはできないものなんでしょうか。","respondent":"富田学務課長","answer":"２３区の中には学校ごとに給食費を決めている区も実はありますけれども、一般的には、給食会計というのはいわゆる私費会計ということで、学校長が運用していくわけですけれども、金額というものは区の中で統一の給食費を定めているわけです。","voiceIndex":69,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"そうすると、小さい学校を中心に考えると、例えば２５０円取らなきゃいけないところを、お金のやりとりをすることで２４０円でおさまるとか、そういうこともあり得ないことではないかと思うので、考え方としていろいろな方向を考えていただきたいなと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-030"},{"speaker":"金野委員","kind":"質問・要望","question":"１点目が、東京都で定めている栄養摂取標準の改訂というのは、これは定期的にというか、どんな割合でこれまでは改訂されてきたのかを教えていただきたいのと、また標準の数値というんですかね。算定の基準になるものというんでしょうか。例えば０歳から６歳までのお子さんの、例えばカルシウムを幾つ取らなきゃいけないとかという標準があるじゃないですか。","respondent":"富田学務課長","answer":"２点目として、食塩の量については、実態を考慮して、小・中・高別に定めた。ここが大きな変更点であります。文部科学省の新基準をもとにして、都としての基準を定めたということであります。","voiceIndex":72,"id":"exchange-031"},{"speaker":"金野委員","kind":"質問・要望","question":"それを基準に平成１６年度から改訂されて、食材の流れも含めて、栄養士が献立を考えてこんな工夫をしたんですよというのを何点か、全部じゃなくてもいいです。こういうものをしてきましたというのが何かあれば、教えていただきたいんですけれども。これらの食材を使ってですね。これを使わなきゃいけないという形なんですか。","respondent":"富田学務課長","answer":"これこれと一つひとつ申し上げられませんけれども、そういうふうに考えております。","voiceIndex":74,"id":"exchange-032"},{"speaker":"金野委員","kind":"質問・要望","question":"今、なぜこれを聞いたのかというと、これらが高いという１つの理由があって、これからの先、この学校給食費ということをどうしようかということも考えていることだと思うので、どこかに改善を求めたときに、より改善をしなきゃいけない給食費をどう抑えていくか、どうしたらいいのかということの考え方として、こういったものを１００％網羅、近づけるという考え方でいいのであれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-033"},{"speaker":"山内委員","kind":"質問・要望","question":"もちろんそれはニュース等で皆さんわかっていると思うんですけれども、その辺を納得していただくというか、そういう説明をしていただく、これが大事じゃないかと考えていますが、これはあくまで要望になってしまいますけれども、基本的には学校の食事というよりも、家庭の食事というものが基本だと思いますので、その辺は教育委員会もそういう部分はしっかりと認識を持っていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-034"},{"speaker":"市川委員","kind":"質問","question":"何点か聞きたいんですけれども、まず給食費というのは、食材費のみと考えていいのかということと、それからあと、８区が今年の４月から改定したという部分で、改定の幅というのはどのくらいの幅で改定しているのかということと、それから、２３区の中で給食はとても難しいということは私もわかっているんですけれども、給食費の額というのは全体の中でどのレベルなんでしょうか、教えてください。","respondent":"富田学務課長","answer":"文京区については、１２円から２８円の幅を持っているところです。現時点で品川区の保護者から徴収しております給食費ですが、小学校の低学年は下から３番目、中学年は５番目、高学年は４番目、中学校については、高いほうから１４番目という状況であります。","voiceIndex":78,"id":"exchange-035"},{"speaker":"市川委員","kind":"質問・要望","question":"それからもう１つお聞きしたいのが、給食費を滞納する人が多いということを最近ニュースとかでよく聞くんですけれども、滞納はうっかり徴収に応じられなくて忘れる場合と、あとどうしても払えないという方がいらっしゃると思うんですけれども、このうっかり未納というのではなく、年間として滞納するという割合というんですか、年間の額なんですけれども、品川の場合はどのくらいあるのか。","respondent":"富田学務課長","answer":"平成１６年度の各学校ごとの給食会計、仮集計をしたものでありますけれども、小学校、これは小中一貫校を含みますが、これについては未納率は約０.１％、中学校につきましては０.４％ということで、これはほぼ平成１８年度と同様の割合であります。","voiceIndex":80,"id":"exchange-036"},{"speaker":"市川委員","kind":"質問・要望","question":"額がどれぐらいなのかということもあわせて教えていただきたいのと、あと１００％保護者から集めるのは、給食費は１００％食材だと考えると、滞納者への補てんをどこかでしなきゃならないと思うんですけれども、その辺は品川はどのようにやっているのか。","respondent":"富田学務課長","answer":"未納額につきましては、未納ということで督促を続けている状況でありまして、各学校でも督促を重ね、教育委員会としても１００％徴収をすべく、今後、学校と協力してやっていくという予定にしているところであります。","voiceIndex":82,"id":"exchange-037"},{"speaker":"市川委員","kind":"質問・要望","question":"やはり自国で自給率が高いわけではないので、やはり今後とも輸入に頼らざるを得ない状況の中で、さらに値上げというのも予想されるんですけれども、そうした場合にはどうやっていくのか、また値上げということになるのか、その辺の考え方を教えていただきたいんですけれども。","respondent":"富田学務課長","answer":"最後に今後の値上げの状況はということでありますけれども、４月に上げてスタートした区については、また途中でということが起きたらどうしようということも言っているところでありますが、本区につきましては年度途中の改定でありますので、その辺。","voiceIndex":84,"id":"exchange-038"},{"speaker":"市川委員","kind":"質問","question":"先ほどの未納の方への対応というところで質問するのを忘れたんですけれども、区全体で８０万円というお金は、全体の給食費の割合からすれば大した額ではないかなと思うんですけれども、この補てんというのはどこから出されるものなんですか。８０万円を埋めていくことになるんですよね。それは税金というか、それが充てられると考えていいんでしょうか。","respondent":"富田学務課長","answer":"未納の金額については、公費での補てんということはしておりません。","voiceIndex":86,"id":"exchange-039"},{"speaker":"市川委員","kind":"質問","question":"公費での補てんがないというのは、どうやって補てんをしているんですか。","respondent":"富田学務課長、市川教育次長","answer":"各学校の給食会計の中で、まだ未納であるということで会計処理をしているです。要はいただくべき給食費はいただくという原則で各学校で対応しております、未納者に対して。","voiceIndex":88,"id":"exchange-040"},{"speaker":"市川委員","kind":"質問・要望","question":"最後に要望ということなんですけれども、私は値上げに対してできるだけの努力をした上で、それでもいたし方ないという場合に値上げはしても仕方がないかなと思うんですけれども、食材が上がったから安易に上げるということがないような、そういう道筋というものはしっかりつくって検討していただきたいということを、要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"その辺が私の今までとらえていた認識とちょっと違うので、やりくりでしているというのは大変な努力だし、それはそれとして本当にご苦労は敬服するところなんですけれども、またやり得るというのはわからなくてもないんですけれども、その辺の０.１％と０.４％をどう見たらいいのかなというのがちょっとわからなくなっちゃったので、教えていただきたいと思います。","respondent":"若林委員長、富田学務課長","answer":"給食費の未納の問題ですので、これで質疑を終わりにしますので、簡潔にお答えをお願いいたします。給食費をお支払いいただけない状況というのは、個別さまざまあろうかと思いますけれども、支払うことが経済的には可能であろうと思われる方々で、お支払いいただいていないという方々も何人かいらっしゃるというのも事実です。","voiceIndex":93,"id":"exchange-042"},{"speaker":"南委員","kind":"質問","question":"テレビでもよく取り上げて、夜、遅く学校の先生と一緒に一軒一軒訪ねて歩くみたいな報道もやっていた時期があって、悪質というのは本当にいかがなものかと思うけれども、払いたいけれども何らかの事情があって払えない、そういう方に対しては、一定程度の考慮はしていかなきゃいけないと思うので、一律に見ていきたくないと思うんですけれども、今までの説明から見ると、この未納している方々というのは。","respondent":"市川教育次長","answer":"こういう保護者に対しては、司法手続によっても払っていただく、こういう対応を今、体制としてはとっております。それからもう１つは、保護者の意向で、生活保護なり就学援助を受けたくないという方がいらっしゃるんですよ。","voiceIndex":96,"id":"exchange-043"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっとデリケートな部分まで踏み込んで聞いちゃったのは、先ほど申し上げたように、所得の低い方々への対策はやっておきながら、０.１％といえども、何でこれだけの数字があるのかというのがちょっとわからなかったので聞いたんですけれども、非常に苦労しているところだし、デリケートな部分であることは承知しながら聞きましたので、ちょっとお許しいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-044"}]},{"id":"topic-03","title":"平成２０年度小中学校新入学者増減","agenda":"平成２０年度小中学校新入学者増減","exchanges":[{"speaker":"南委員","kind":"意見","question":"小学校、中学校とも昨年と比較して、そんなに大きな数ではありませんけれども、減っているというところはどういうふうに見るのかと、あと国公立とか私立への進学について、この数字というのは、この間の受け入れから見るとどういうふうになっているのかという、その２点についてお尋ねします。","respondent":"富田学務課長","answer":"中学校につきましても、平成１９年度が２７.１％、国公立、私立をトータルした数が、平成１９年度は２７.８％で、今回、平成２０年度は２６.１％ということで、減少しているです。","voiceIndex":106,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"何回も聞いてわからなくなってしまうので確認したいんですが、希望申請、指定校変更、区域外就学ですね。ここでなんですが、希望申請というのは、例えば品川小学校で言うと、旧学区域では登録者数３７名、要はどういう人がここに入るのか。一応学校区域でお知らせが来ますよね。これはいつの時点のことなのかとか、そこの数字の定義というんですか、どういう人の数なのかご説明いただきたいんですけれども。","respondent":"富田学務課長","answer":"指定されて、教育委員会から通学指定の通知を出します。それが指定校になるわけですけれども、その指定校ではない学校に行きたいよという方が出た場合に、指定校変更という制度が、さらに希望申請の後でされるということになってまいります。","voiceIndex":108,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"もう少し整理していきたいんですけれども、旧品川小学校の旧の学区域がありますね。その学区域の中に住んでいるお子さんについては、そこを希望していれば何もしなくていいわけですね。品川小学校じゃなくて、同じブロックの城南小学校に行きたいといった場合に指定校変更ということですか。","respondent":"富田学務課長","answer":"希望申請です。","voiceIndex":110,"id":"exchange-047"},{"speaker":"西本委員","kind":"意見","question":"希望申請を出した方が、３９人ほかから品川小学校を選んだという形になるわけですね。その後、人数が許容範囲の中であればそのまま受け入れられるという形になるわけですね。定員はというか、増えちゃった分の人たちというのはどういう動きになりますか。","respondent":"富田学務課長","answer":"指定校変更には基準がありますので、人数内であれば受け入れていくという性質のものではございませんで、一件一件について妥当であるかどうか、学校の受け入れ枠があるかどうかということも含めまして、審査をした上で決定をするということになってまいります。","voiceIndex":112,"id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"そうしますと、指定校変更というところは、ブロックの中とか定数とかということ、もちろん最終的にはそれを踏まえてのあれになるんでしょうけれども、いろいろな事情のある方ということなんですか。","respondent":"富田学務課長","answer":"指定校が決まった後に指定校変更という制度をご利用いただいて、例えばブロックが違うところに行ったりとか、そういったご要望が出されるということでありますが、指定校変更については基準がありますので、例えば家からの交通の便であるとか。","voiceIndex":114,"id":"exchange-049"},{"speaker":"西本委員","kind":"質問","question":"選択制のわけだから、そこのブロックの中であれば、枠があればブロック外からでも希望ができるわけですよね。その上で、要はそれは決めたんだけれども、途中で変えますという人がこの指定校変更なんですか。選択制だから、もともとそういうものを加味した上で希望申請を出すんじゃないかと思うんですけれども、そうじゃない状況があるんでしょうか。","respondent":"富田学務課長","answer":"その上で指定校変更の制度を利用していただくということになりますので、理由を問わずにブロックを越えてご希望いただけるというのは、基本的にはないということです。","voiceIndex":116,"id":"exchange-050"},{"speaker":"西本委員","kind":"質問","question":"希望申請というのは、ブロックの中で完結できるものに対して、そこで指定校が決まりますよね。だけど、その後、一時的にブロックをまたがって申請するという形をするということになるんですか。それと抽選の戻りというのがあるんですけれども、これは待機の状態、抽選になってしまっている人たちが、抽選になっちゃったからもとに戻すよという方たちの数と認識してよろしいんですか。","respondent":"富田学務課長","answer":"は希望申請の数をはっきりさせるためにこの表をつくってありますので、希望申請を出された方の数、小学校で言えば６９５人、これはかっちりと固めて、まずはこの学校を希望された方々の数ということで出しています。","voiceIndex":118,"id":"exchange-051"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"石田（慎）委員","kind":"質問","question":"件数なんですが、五反田文化センターの例えば８,００８件、これは文化センターを使った利用件数ですか。それともこの併設施設を含めたものか。","respondent":"堀越生涯学習課長","answer":"こちらの数字は文化センターのご利用をいただいた数字を載せしています。","voiceIndex":127,"id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"そもそも文化センターの特徴は何でしょうかということなんですけれども、現在の品川区の文化センターに、図書館がついていたり、それは文化センターとは別になるわけで、文化センターの役割って何でしょうというところが、ちょっとわからなくなっているなというのがあるんですね。","respondent":"堀越生涯学習課長","answer":"そのほか、今度五反田のほうの改築をして、音楽ホールという形の特徴もあわせ持ちますので、そういった中で、また新しい文化センターの一面も出てきますので、そういった動きも含めて、集会所ですとか、いろいろな施設利用のネットワーク。","voiceIndex":129,"id":"exchange-053"},{"speaker":"西本委員","kind":"質問","question":"施設の特徴というところで、東品川、旗の台、南大井のところは空欄なんですね。例えば品川区に限らず、文化センターという考え方というのが、日本の中でとか変わってきつつあるとか、そういう動向というか、傾向はあるんでしょうか。","respondent":"堀越生涯学習課長","answer":"もちろんこれからさらに生涯学習という部分、大事な部分になってくると思いますので、そのあたりのことについては、これからの検討、今も検討しておりますけれども、またさらに進めていきたいと考えております。","voiceIndex":131,"id":"exchange-054"},{"speaker":"西本委員","kind":"質問・要望","question":"私は毎週東品川文化センターを利用しているんですけれども、そこの中でも特徴がどうなんだろうなというところがありまして、文化センターである意義とか、そういうところをちょっと考えていただきたいなと。今、説明されたように、生涯学習という形で位置づけということであるならば、それなりの役割というのをもう少し考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-055"},{"speaker":"南委員","kind":"質問","question":"各館ごとに企画をして、職員の方が地域の状況だとか、そういうものに合わせて企画、講座を組んでいたりとか、そういうことがなくなって、生涯学習課のほうで多彩な企画を組むようになって、もう１０年近くたつんだろうと思うんですけれども、今、課長がお話しされたような、地域の主体的な活動をどう支援するかというところで見たときに、これだけの規模の利用状況があるんですけれども。","respondent":"堀越生涯学習課長","answer":"ですから、見直しをして、貸館という見方という今のご意見だと思うんですけれども、より自主的な、主体的な展開が図られているんじゃないかと考えているところです。","voiceIndex":134,"id":"exchange-056"},{"speaker":"南委員","kind":"質問","question":"それと４番目の利用状況のところの数なんですけれども、件数という数なんですが、その辺の先ほど課長が力を込めておっしゃっていた主体的な活動が、この利用状況にどういうふうに出ているのか、あるいは生涯学習課としていろいろな企画を組むさまざまなプログラムとの関係で見て、この件数はどうなのかというのがよくわからないので、その説明をお願いします。","respondent":"堀越生涯学習課長","answer":"それと事業についても、区のほうで企画して、いろいろな地域の方にお願いしている部分ですとかがありますけれども、例えばシルバー大学ですとか、青少年の部分の事業ですとか、そういったものについては、かなり多くの方々のご応募をいただいておりますし。","voiceIndex":136,"id":"exchange-057"},{"speaker":"南委員","kind":"確認","question":"それはそれとして評価をしたいとは思っているんですけれども、この４番の利用状況が、先ほど私が伺いたかったのは、長い目で見てトータルの利用状況が上がっているということなので、それはそういうふうにお聞きしますけれども、文化センターを何年か前に改められて、課長がおっしゃったような主体的な活動を支援するという方向に持ってきたんだという、そこで見たときに、この利用件数というのは。","respondent":"堀越生涯学習課長","answer":"数字のほうから見させていただいて、非常に上がってきている、そのように私どもはとらえているところです。","voiceIndex":138,"id":"exchange-058"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"シルバー大学のほうでも、先日、入学式、女性が約１６０人ぐらいで男性が１２０人ぐらい、そのぐらいの方たちが新たに入学をし、出席をされている方以外の方も入っているわけですけれども、名称のことでちょっとお伺い、前にもちょっとお伺いしたことがあるんですが、この文化センターという名前が、一番古いところでは昭和４１年に文化センターという名前で命名され、施設が設置されているわけですけれども。","respondent":"堀越生涯学習課長","answer":"名称については、今、ここで特にこうだというものはないんですけれども、事業にとっても、施設にとっても、常に見直しというのは必要であろうと考えておりますので、非常に名称が団塊の世代の心をつかむというか、そのような部分が非常に大きな要素になってくると、今。","voiceIndex":142,"id":"exchange-059"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"学校の緊急連絡の方法ということでお尋ねしたいと思います。この文面から見ると、今年度から、品川区で導入する学校校内メールによる一斉配信システムを利用することにしますというふうに読めるんですが、これはどういったことになるんでしょうか。教育委員会なのか、品川区という言い方しかないのでちょっとわからないんですけれども、これはどういう状況なのかをまずお聞きしたいと思います。","respondent":"富田学務課長","answer":"スタートの予定は９月の運用開始を予定しておりますが、校務システムの検討メンバーがおり、かつ希望される一部の学校については、検証作業を行うため、６月中旬から運用開始する予定でありまして、この中に委員おっしゃられました伊藤学園も入っているです。","voiceIndex":147,"id":"exchange-060"},{"speaker":"西本委員","kind":"確認","question":"メールはメールでそのやり方があると思うのでいいんですが、６月ですから、緊急連絡の体制がとっていないんですよ、伊藤学園では。ですから、それを見ないとわからないんですね。緊急ですから、何かあったときの連絡だと思いますので、その体制が一方方向だというだけではなくて、確認も必要だし、送れなかったということもあり、そういういろいろなことを想定しながら検討をしているのかということですね。","respondent":"富田学務課長","answer":"そういった学校のメールシステムがどのようなものであるかはわかりませんが、現在、開設を準備しております教育委員会としてのメールシステムは、お子さん１人について５つのアドレスの登録が可能になるように予定をしておりまして、５カ所まで登録ができるということで。","voiceIndex":149,"id":"exchange-061"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろ方法によってデメリット、メリットというのがあると思うので、そこを出した形で検討していただきたいなと、これは要望で終わりたいと思いますけれども、あと連絡網については、ＰＴＡはＰＴＡでつくっているし、これは学校の中での問題ですから、それはＰＴＡの中で、必要であればつくりましょうという話になるでしょうしね。校長会とかでそういう話はできないんでしょうか。","respondent":"市川教育次長","answer":"そういうことも含めて、６月から検証ということで一部スタートさせていただいて、その上で９月からスタートさせるというスケジュールを組んでおりますので、校務システムの構築そのものについて、改めて文教委員会のほうに説明する機会があろうかと思いますので。","voiceIndex":151,"id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4632#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":52627,"voices":158}},{"id":"h20-20080512-5","meetingId":"h20-cm05","date":"2008年5月12日","dateIso":"2008-05-12","committee":"総務委員会","time":"午後１時０３分～午後１時５５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"次回から本格的な論議に入るということですけれども、前回報告があったタウンミーティングとの関係でお聞きしたいと思います。それから、５００人、３００人という規模の中で、区長との意見交換等あるようですが、実際にどのような運営を考えているのかお聞きしたいと思います。","respondent":"中川原広報広聴課長","answer":"なぜかといいますと、去年タウンミーティングに来ていただいた方々の感想が、区長の考えを直接聞けてよかったという感想と、区民同士でいろいろな意見があるということがわかってよかったということもありますので、いろいろな情報を共有化して、当日挙手して言う方もいれば。","voiceIndex":5,"id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"流れとしては、前回もご説明にあったようにわかりますけれども、実際に参加される皆さんは、当然新しく来られる方もいるわけですから、事前になるのか当日になるのかわかりませんけれども、資料の配布なり何なりが必要になると思うんです。当然、論議の前提になる資料は必要になると思うんですけれども、そこまで考えているのかどうか。皆さんに渡すべき資料は事前配布になるのか、その辺をお聞かせください。","respondent":"中川原広報広聴課長","answer":"事前にというのは、申し込み状況を見てみないとということがありますけれども、当日の流れの中でビデオという形で、品川区の歴史とか現在の状況、区が取り組んできたものについてはビデオで共有化し、その後、区長が今まで長期基本計画の中で説明しているようなデータとか。","voiceIndex":7,"id":"exchange-002"},{"speaker":"浅野委員","kind":"質問","question":"第２回品川区長期基本計画策定委員会で配られた別紙1)の資料は、前のものと中身は変わっていないということでいいですか。","respondent":"福島長期計画担当課長","answer":"数字が半年前からずれていたり、平成１９年度の結果がわかるものは載せたりですとか、最新のものをということで修正しています。ただ方向性ですとか、中身そのものについては以前のとおりです。別紙2)につきましては、出されたものをそのままという形です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"浅野委員","kind":"質問・要望","question":"別紙3)の長期基本計画体系骨子（案）を拝見させていただきまして、政策面ということでかなり細かいところまで書かれておりますけれども、書かれておりますと、どうしてもそちらのほうに引っ張られるようなことがあると思います。これは要望ですけれども、これに限らず活発な意見交換ができるように、ぜひとも皆さんの考えを引き出せるような基本計画の論議にしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"簡単なことですけれども、応募者が６９名で委嘱者が５０名、差し引き１９名の方は自己都合か何かで選ばなかったのでしょうか。","respondent":"中川原広報広聴課長","answer":"区政モニター設置要綱で、区政モニターは５０名以内となっていまして、運営上そのような形で遂行しています。","voiceIndex":17,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問","question":"つまり、６９名を５０名に絞ったのですね。どのような考え方で絞ったのかということを伺ったんです。","respondent":"中川原広報広聴課長","answer":"地域割、年代割、男女別を考えまして、三つの要件を掛け合わせて、それぞれ別々に書いてありますけれども、そのようなところからバランスを取って選ばせていただいている形になります。","voiceIndex":19,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問","question":"つまり、地域と年代でバランスを取って、広く区民の意見を反映させるために選んだということですね。これはお願いですけれども、結果として選ばなかった方々に対しては、十分に品川区の考え方を説明していただければ、次回の応募には、優先されることを検討していただくことをお願いしておきますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-007"},{"speaker":"土井委員","kind":"質問・要望","question":"となると区政モニター以外の施策、要するに、そのような皆さんはどうしていくのかという施策をしっかりしておかなければいけない、アイデアを提供されているのではないかと思います。今日は議題ではありませんから、ぜひその方向で、他のものでそういう思いを活用していけるように、あるいはいろいろと区の関係を持っていただけるようにしていただけるようにお図りいただきたいという、お願いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-008"},{"speaker":"原委員","kind":"質問・要望","question":"任期が１年から２年にされた状況を教えていただきたいと思います。そうすると区政モニターは、長期基本計画の委員も３０名の中の関係も出てくるのかもわかりませんけれども、５０名を選んだときに、特に欠陥条件というか、欠如条件というか、外すようなものがあるのかないのか、その辺を教えていただきたいと思います。","respondent":"中川原広報広聴課長","answer":"任期２年にした理由ですけれども、区政モニターの一番の特徴は、区民の声も毎年２,０００通ぐらいいただきますが、まず区の説明とか資料を出しまして勉強をしていただいて、そしてご意見をいただきます。","voiceIndex":23,"id":"exchange-009"},{"speaker":"原委員","kind":"質問・要望","question":"私から要望ですけれども、これは昔から言われていることですけれども、やらせにならないような形を取ってお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-010"},{"speaker":"土井委員","kind":"質問","question":"ということは、本来ならばそんなようなことをしないで、出したものは少し渡しますよ、でも歳入欠陥が生じますねという議論を国のほうにやらせればよかったのではないかと思いますので、その辺も含めて、それぞれの自治体の取り組みを、これからも同様の事態が起きないとは限らないし、ましてや今度仮にきちんとなったとすれば、また暫定ですから同じことが起こるわけなので、そのときの思いとして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問・要望","question":"つまり、この部分は国に何か要請していくとか、いろいろな事業を考えていくとか、対処を具体化していかないといけないわけではないですから。ただ、減収がある。それはわかったけれども、それに対して品川区ではどうするのかというところまで、しかるべきときには報告をしていただきたいということをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-012"},{"speaker":"武内副委員長","kind":"質問","question":"ほかによろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-013"},{"speaker":"土井委員","kind":"質問","question":"このことによって、今度は新たな土地が道路に面しているところが大きいわけです。本当に等価なのかどうか、その辺のことをここで聞いても仕方ないのかもしれないけれども、どのような考え方でやられるのかということをお伺いしておきたいと思います。それとこれによって、区が固定資産税とか、要するに区の歳入なり何なりに全く影響がないのでしょうかという話です。","respondent":"伊勢総務課長、日下部企画財政課長","answer":"５月８日に説明に来たときに聞きましたところ、等価であると。ただし、国家公務員勝島住宅は建物が残っていますので、解体の関係ですので、交換する土地の面積はもらうほうが大きくて、渡すほうが若干少ないという話でございました。税収関連ですが、ご案内のように固定資産税については、東京都に都税という形で入りますが、ただ当然のことながら国家公務員宿舎ということで、そこに居住される方も大分増えるということですけれども、区民税につきましては。","voiceIndex":37,"id":"exchange-014"},{"speaker":"土井委員","kind":"質問","question":"そうすると、固定資産税の歳入の仕方はいろいろあるのだろうけれども、固定資産税も確かにうちは集めてませんけど、そこで集めていて、そこからいろいろいただけているのだろうと思っているんですけれども、いただけてないとすれば問題ですが、そういうものですから、それがどのように見たらいいですかということも聞かせてください。","respondent":"日下部企画財政課長、市岡総務部長","answer":"固定資産税として収入をされたとしても、これについては残念ながら、例えば品川区にあるからその分を割り増しという形では算定されるような仕組みになっておりませんので、あくまでも都税として一括して収入がされて。現在は駐車場と相当老朽化した中層の国家公務員住宅ですが、これが非常に規模の大きな国家公務員住宅と大規模商業施設になりますから、固定資産税は評価額を基準にして課税されるものですので、間接的ですけれども。","voiceIndex":40,"id":"exchange-015"},{"speaker":"土井委員","kind":"質問・要望","question":"もう一つ、教えていただきたいんですけれども、国の部分と民間の部分が今までと比べると面積が変わるわけですね。例えば、国のところは税金を納めていただいているだろうと思いますけれども、納めていなかったら随分違うわけです。","respondent":"日下部企画財政課長","answer":"確かに、国が所有する部分については、国自体は課税されない対象ですけれども、その分は固定資産税としては入ってきませんが、それに相当する部分を法律によりまして固定資産税相当分を別な形で交付するという別の法律がありまして。","voiceIndex":43,"id":"exchange-016"},{"speaker":"土井委員","kind":"質問","question":"今のお話を聞くと、少なくとも大井競馬場のほうには面積的には小さい形で、そのかわり税の部分を見ているということでやったのだろうなと思えるのですけれども、というように聞こえたのだけれども、そういうことがあるのかなと思ってお伺いをいたしました。区には直接関係ないようなので終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"一部事務組合と東京都競馬株式会社との関係がよくわからないものですから、基本的なところを説明していただけますか。","respondent":"伊勢総務課長","answer":"東京都競馬組合は競馬事業を開催している形になりまして、開催場所が大井競馬場でございまして、大井競馬場の施設を所有しているのが東京都競馬株式会社です。","voiceIndex":46,"id":"exchange-018"},{"speaker":"菊地委員","kind":"意見","question":"施設を持っているのが東京都競馬株式会社ということであれば、品川区の資金が入っていて組合が運営されています。競馬一部事務組合がつくり上げた株式会社という意味なのか、それとも全く別枠としてつくり上げられてきたものなのか、もう少しその辺を説明していただけますか。","respondent":"市岡総務部長","answer":"端的に言えば、ここは大家さんで、競馬事業の許可を持っているのは競馬組合ということですが、かつては２３区がそれぞれ東京都競馬株式会社の株主でした。","voiceIndex":48,"id":"exchange-019"},{"speaker":"菊地委員","kind":"意見","question":"株主だとすれば、当然ここで競馬一部組合に入るか、それとも品川区に入るかよくわからないですけれども、そういう関係になっていくでしょうし。かなり大型の商業施設になりますけれども、そこでの損失が出てくれば、もし株主という形式を持っているのであれば、その損失についてもかぶさってくるのかなという気がするんですけれども、その辺をもう少し説明いただけますか。","respondent":"市岡総務部長","answer":"ただし、競馬事業に直接この会社がタッチしているわけではなくて、いわば大家さんとして競馬場以外の不動産も持っておりまして、そういうものを全体で競馬会社としても経営を行っているということですので、ここは本場所在区の品川区との関係が一番深いので。","voiceIndex":50,"id":"exchange-020"},{"speaker":"原委員","kind":"質問・要望","question":"等価交換という会話が出てきたものですから、明確にお聞きしておきたいのですけれども、等価交換をしますという説明があったのでしょうか、文書上からいくと土地の交換をということになっているので、そこを教えていただきたいと思います。","respondent":"伊勢総務課長","answer":"品川区に説明に来たときも、等価で交換しますという話をお聞きしました。","voiceIndex":52,"id":"exchange-021"},{"speaker":"原委員","kind":"質問","question":"要するに、不動産上でいう等価交換ではなくて、金額的に同じぐらいになるだろうということで、不動産の等価交換というのは主要目的も同じでなければいけないし、期間的な問題もあるというところなので、私がはっきり聞きたかったのは、金額的に若干の数字の違いはあるだろうけれども、説明自体が金額的に等価なんだという説明で来たのでしょうかということだけを聞きたかったのです。","respondent":"伊勢総務課長","answer":"同じような金額になるということをお聞きしました。","voiceIndex":54,"id":"exchange-022"},{"speaker":"浅野委員","kind":"質問・要望","question":"施設イメージを見ると、地上６階建てということで、競馬開催時は車で来る人が増えますし、自転車での買い物も多いと思いますが、周囲の道路に車が車が並んでしまうようなことがないようにしていただきたい。それから、やはり自転車で来る人は多いと思いますので、自転車が安全に通れるようなこともしっかり道路側を区側としても考えていただけないかなということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-023"},{"speaker":"武内副委員長","kind":"質問","question":"その他でほかによろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1782#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":14704,"voices":60}},{"id":"h20-20080513-14","meetingId":"h20-cm05","date":"2008年5月13日","dateIso":"2008-05-13","committee":"行財政改革特別委員会","time":"午後１時０２分～午後２時１８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の契約のあり方に関すること","agenda":"の契約のあり方に関すること","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"２点ほど教えてください。今回の総合評価方式の制度が整ったことによって、品川区の中にはこのいわゆる総合評価と、品川区簡易型総合評価と２つの仕組みができることになったんですけれども、今後、ある案件をどのような契約形態にしていくかを考えるときに、総合評価にするのか、それとも簡易型にしていくのか。この必要がある場合というのは、例えばどういった場合を想定されているのか、お聞かせください。","respondent":"阿部経理課長","answer":"２点目の落札者を決定しようとする時に、必要に応じてというのはどういうことなんだということですけれども、例えば非常に技術的に困難な場合とか、そういうもので改めて落札者の決定の基準を決めた時に、その学識経験者方に聞いて、やはり落札者を決定する時も。","voiceIndex":5,"id":"exchange-001"},{"speaker":"阿部委員","kind":"確認","question":"それから後半のほうは確認になるんですけれども、この必要があるかどうかを決めるというのは、この学識経験者を交えての決定基準を定めようとする時に、その決定時にももう一回意見を聞くかどうかということを決めるという手続きでいいのかどうかというのを確認したい。","respondent":"阿部経理課長","answer":"ですから、金額で３,０００万円以上にするとかしないとか、そういう決めではなくて、その中身によってどういう総合評価をしていくかという形になろうかと考えています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"阿部委員","kind":"質問","question":"逆に言えば、どんな工事でも必要ないという判断であれば、この先、実績がこの１件だけで終わってしまうということも仕組み上は可能なんですか。その辺の大まかな基準みたいなのは全く設けない中での発進ということになるんでしょうか。","respondent":"阿部経理課長","answer":"ただ、工事の内容によって、どういう形の総合評価方式を入れていくのかというのは、今後試行しながら、今回の一件だけではなくて、さまざまな工事に対応したものを総合評価方式を試行しながら決めていくということになるというふうに思っております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"阿部委員","kind":"意見","question":"一応それをメインに持っていくので、あとは運用で見てくれというようなことなのかなと思うんですけれども、これは今後についても運用の仕方を見ていかなければいけないと考えています。とりあえずそこまでです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"幾つか教えていただきたいと思うんですけれども、１ページ目のところに基本的な流れというものがありますので、そこに沿ってご説明いただけたらなと考えています。１つ目は、この学識経験者の落札者決定基準を定めようとする時、あと落札者を決定しようとする時というのは、いわゆるこの資料の流れの中では、どこになるのか。この流れの中で、こういうところでこうですよというのを教えていただけますか。","respondent":"阿部経理課長","answer":"落札者を決定する前ですから、この時です。もう１つは、今回の４ページ目の技術点の評価項目の公表の時期ですけれども、それはここの１ページの流れ図の３番目に説明会とあります。そのときにこれを公表して、参加している方に対しては公表をしております。","voiceIndex":12,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"先に、技術点の評価項目が、この説明会のところで公表されるということですけれども、どういう形で公表されるのか。つまり参加者だけなのか。それとも工事自体はたしかホームページでも集めるみたいなものだとかあったと思うんですけれども、どういう形で公開されるものなのか、教えてください。それとあと学識経験者ですけれども、どなたなのかということですね。そこもご説明いただけますか。","respondent":"阿部経理課長","answer":"その参加者に対して、今申し上げたとおり、説明会で公表しているというものです。学識経験者はどういう方かということですけれども、今回につきましては、もう既にこういう総合評価方式を行っております東京都建設局第二建設事務所の所長と、区の都市計画審議会の会長です。","voiceIndex":14,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"そうすると、この評価項目のほうは、参加者だけに公表するということでよろしいんでしょうか。それと、１ページ目の落札者の決定方法のほうで、技術力を見るところ、この評価項目のほうでも技術点がありますけれども、ここの考え方を１つ伺いたいのが、つまり区内企業というか、区内産業を発展・充実させるという意味で、地元企業という考え方というのは、ここにどんなふうにかかわっているのか。","respondent":"阿部経理課長","answer":"この評価項目での区内事業者ということですけれども、ここにつきましては、４ページに技術点の評価項目の中に事業者の信頼性、社会性という欄があります。この中で、例えば選択対象項目という欄がありますけれども、例えば地域における実績はどうなのか。","voiceIndex":16,"id":"exchange-007"},{"speaker":"中塚委員","kind":"確認","question":"単純にこの技術力だけで見ると、区を離れた大手のところのほうが、それは積み重ねているものも多くなってくると。そうすると、工事のものにもよるとは思いますけれども、区内で頑張っている方々が、結果としてこれではじくような仕組みになってしまうとどうなのかなという思いで、ちょっと伺ったんですね。そこをもう１度確認させていただけますでしょうか。","respondent":"阿部経理課長","answer":"区内企業の育成につきましては、例えば制限付き一般競争入札の中でも、区内業者に限って参加をいただいているという場面もありますし、区内の産業の育成については十分配慮していると考えています。","voiceIndex":18,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"資料の２ページの比較のところなんですが、簡易という言葉がとれたことで、どこが違うのかなと見て、一番重要な契約形態のところが、はっきり違いがあるので、この辺の中身を制限付き一般競争入札、随意契約、この間までの感覚では、違いは学識経験者のところぐらいかなと思っていたんですが、契約本体のここの違いのところがどういうふうにあらわれているのかと、あと１ページ目のところの流れにおいて。","respondent":"阿部経理課長","answer":"そういうふうに地方自治法施行令では定められておりますので、今回は地方自治法施行令に定められたような方式で行いますので、ここに書いてあります、契約の形態につきましては、制限付き一般競争入札になるです。","voiceIndex":20,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"意見","question":"ちょっとご説明を聞いてもよくわからなかったのが、品川区の簡易型総合評価というのも、一般競争入札の問題点を改善をするという意味では、価格の競争ではなくて、５０点、５０点のところの技術的なものも入れたという、この間のご説明からすると、そこと簡易をとった、さらに先ほど地方自治法上のところの違いだとおっしゃった、もうちょっとそこのところをわかりやすく説明してほしいです。","respondent":"阿部経理課長","answer":"今まで行いました品川区簡易型総合評価は、委託契約について行ってきたというものです。今回のものにつきましては、先ほど申し上げましたけれども、工事について行ったと。簡単に言えばそういう委託契約か工事かという違いが一番大きいところと思います。","voiceIndex":24,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"簡易型のほうは委託契約において使われる手法ということでは、今回、総合庁舎の耐震工事で、この試行については、今回工事ですね。それが１点。もう１つ、２ページのところにおいて、今回の総合評価は公募型とありますけれども、簡易のほうは指名型もあるんですけれども、この総合評価のシステムにおいて、今回は公募型だけれども、指名型もここの中に入っていくのかどうか、ちょっとその点を教えてください。","respondent":"阿部経理課長","answer":"今回は制限付き一般競争入札の形をとっておりますので、公募型という形になります。これから工事についてはすべてこういう総合評価を行っていくのかですけれども、あくまでも今回は試行ですので、何度か試行を重ねながら、本格的な実施に入っていくんだろうと思っています。","voiceIndex":26,"id":"exchange-011"},{"speaker":"阿部委員","kind":"確認","question":"何度もすみません。先ほど聞き落してしまいました。大変基本的な質問で恐縮なんですけれども、ここで工事総合評価方式と、あえて「工事」とうたっているんですが、これは地方自治法上は総合評価というのは工事に限定されたものなんですか。ちょっとそこを確認させてください。","respondent":"阿部経理課長","answer":"地方自治法施行令については、工事とか、あるいは委託とか、そういう区別はございません。","voiceIndex":28,"id":"exchange-012"},{"speaker":"阿部委員","kind":"質問","question":"そうすると、今回導入する総合評価方式について、工事総合評価方式と、あえて持ってきているのは、とりあえず品川区では工事案件にしか総合評価方式を入れないのだという意思であるのか。あるいはたまたま今回の試行になるものが工事案件であったので、とりあえず工事タイプを決めて、その後、また工事以外のものについても仕組みをつくっていくのだということなのか、ちょっとその辺を教えてください。","respondent":"阿部経理課長","answer":"今回、先ほど申し上げましたけれども、正式には公共工事の品質確保の促進に関する法律というもので総合評価方式を入れていこうということですので、今回は工事について、ここには工事総合評価方式と書いてありますけれども、そういうふうにつけたということで。","voiceIndex":30,"id":"exchange-013"},{"speaker":"阿部委員","kind":"質問","question":"その点、了解いたしました。そうすると、今回の工事総合評価方式と、簡易型総合評価方式で学識経験者の意見を聞いたものというのは、実態的にはほぼ同じになってしまうのかなと。とすると、この提言というか、まとめはちょっと気の抜けたものになってしまうのかなと思うのですが、学識経験者の意見を聞いた簡易型総合評価方式と工事総合評価方式というのは、何か違いがそれでもあるものなんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-014"},{"speaker":"阿部委員","kind":"質問・要望","question":"今のは、純粋にその仕組みの説明を求めたものであって、文言をこれからどうしましょうということではないです。ただ、仕組みとして総合評価方式と、学識経験者の意見を聞いた簡易型総合評価方式というものは、何かそれでも違いがあるものなのでしょうかという、仕組みの質問です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-015"},{"speaker":"鈴木（真）副委員長","kind":"確認","question":"二、三点確認をさせてください。今度工事総合評価が始まりますが、以前の段階で資料をいただいた中の簡易型総合評価、随意契約の際に価格点が５０点と出ていますよね。これは今度のケースも、前回の随意契約のときの委託に伴う契約のときの簡易型と一緒の点数配分ということでよろしいんでしょうか。それが１点です。これ、実施要綱をつくる前から、一応試行していたんでしたか。その状況を教えてください。","respondent":"阿部経理課長","answer":"価格点と技術点の話ですけれども、１ページのほうに申し訳ございません、ちょっと説明が抜けましたけれども、書いてありますが、今回のものにつきましては価格点が５０点と技術点が５０点、合計１００点で、それの総合合計点が高いものを落札者にするということですので。","voiceIndex":37,"id":"exchange-016"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"今度の工事の総合評価方式、これは耐震ということで比較的技術点を評価しやすいところもあると思うんですけど、これをやっていく上で、やっぱりどこかで実施要綱なんかをつくっていかなければいけないのではないかなと思ったもので、今回は実施要綱をつくらないで試行するということの判断ということでよろしいんでしょうか。","respondent":"阿部経理課長","answer":"後の件ですけれども、実施要綱ということではなくて、今回の総合庁舎耐震改修工事について、総合評価方式を入れていくという、１件の決定でやっております。ですから、要綱を定めているわけではございません。","voiceIndex":39,"id":"exchange-017"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"それともう１点、最後に工事に関しては総合評価方式を今回試行しましたので、前のときに、先ほど阿部委員のお話もあったし、飯沼委員からもあったと思うんですけれども、工事に関しては、簡易型総合評価方式というのは、もう今後は考えないということで、総合評価方式は工事に関しては、簡易型というのはないよと考えていいわけですね。","respondent":"阿部経理課長","answer":"副委員長がおっしゃったとおり、簡易型総合評価は、工事については、なかなか適用は難しいだろうと考えています。","voiceIndex":41,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど、技術点のことを聞いたので、価格点のほうもちょっと伺いたかったので、ご質問いたしますけれども、入札価格の予定価格というんですか、その決め方というのは、この工事総合評価方式の中で、まず変わるのか変わらないのか、教えていただきたいのと、入札価格の予定価格というのは、だれがどうやって決めていくものなのか。","respondent":"阿部経理課長","answer":"予定価格ですけれども、方式としては今委員がおっしゃったように、積み上げをやってあります。予定価格が変わるのかということですけれども、これは一般競争入札と同じですので、この総合評価を入れたことによって変わるということはございません。","voiceIndex":43,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"今回のこの方式でも、予定価格の決め方は変わらないというご説明だと思うんですけれども、なぜそう伺ったかというと、積算の積み上げが、どういうふうに積み上げているのかなというのが、実感として疑問に感じるときもあるんです。そんな狭いところにこんなトラックが通るわけないと。","respondent":"阿部経理課長","answer":"総合評価方式を入れたからといって、予定価格が従来のものと変わるということはございませんので、それは契約の考え方が価格点だけではなくて、品質を確保していくと。","voiceIndex":45,"id":"exchange-020"},{"speaker":"中塚委員","kind":"意見","question":"ちょっと私の聞き方があれだったかもしれませんけれども、総合評価方式の中の半分の価格点のほう、５０点というのが予定価格との差の割合で決まっている。技術点のほうは先ほど少し中身の説明があったんですけど、どうしてもこの価格点のもとになる予定価格、そこがちょっとよく今までのご説明では見えてこないので、そこをご説明いただけますか。","respondent":"阿部経理課長","answer":"それは積算基準という技術的なものがありますので、それを参考にして積み上げていくですので、決して根拠なく積み上げているというものではございません。","voiceIndex":47,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"こういった面では、委託のところを見ると、随意契約が多いという部分では、政令に従って、条件にのっとって結んでいるということですけれども、この随意契約のこの問題点を改善していく立場にあるというか、改善をされている中身であるというとらえ方でよろしいんでしょうか。その辺をぜひお聞かせいただきたい。","respondent":"阿部経理課長","answer":"もし、これでは履行能力が全くないということになれば、それはその業者はそれ以降できないという形になりますので、また改めて履行能力の評価をして、十分な履行能力を持ったものについて委託契約を行うという形になりますので。","voiceIndex":49,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問","question":"随意契約であるけれども、競争性のところも加味をされてきているというふうに受けとめましたけれども、委託に関しての部分において、この簡易型というのがとれるというか、方向的に一般競争入札の方向に行くというか、そういった方向性というのは国のところではどうなんでしょうか。","respondent":"阿部経理課長","answer":"もう１つは、さまざまな委託がありますけれども、この委託に対してはどういう学識経験者の方がいるのかとか、あと品川区だけではございませんので、多分そういう学識経験者のお話になれば、全都的な話になるでしょうから、その辺はなかなか難しいだろうと思っておりまして。","voiceIndex":51,"id":"exchange-023"}]},{"id":"topic-02","title":"の特定事件調査のまとめ","agenda":"の特定事件調査のまとめ","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"これ、１、２、３、４のくくり方をどう解釈するかにもよるんですけれども、この２番の中で言っている契約時における透明性の確保云々ということは、今日、議題にもなりました、総合評価方式にも当てはまることだと思うんですね。とすると、２番はこの２つの列挙ではなくて、工事総合評価方式を含めた３つの契約方式の列挙でもいいのかなと思うんですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-024"},{"speaker":"中塚委員","kind":"意見","question":"文言については、一定正副委員長にゆだねますけれども、３の「より客観性を持った仕組み」、この間の話し合いの繰り返しかもしれませんけれども、この「より客観性を持った仕組みづくり」とこの「公平性・透明性の確保」、「客観性」というのも欠かせないキーワードだと思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-025"},{"speaker":"高橋委員","kind":"意見","question":"ちょっとお尋ねしたいんですが、総合評価方式の試行はまだこれからも行われていくのかという点が１つと、それから先ほどちょっとお話があったんですが、総合評価方式は工事の内容によって評価項目と配点を変えていくという話があるとすれば、もしかしたら選定基準の策定について、案件によって変えていくので、こういう３番みたいな文言があったほうがいいのか、ちょっとそこがわかりませんので。","respondent":"阿部経理課長","answer":"委員、おっしゃったとおり、今後も工事については総合評価方式の試行はしていくと考えております。","voiceIndex":60,"id":"exchange-026"},{"speaker":"阿部委員","kind":"提案","question":"すみません、私の言い方が悪かったのか、その後の私の受けとめ方が全く誤解なのか。１番などは価格や履行能力については、全く総合評価方式でも同じことですから、総合評価方式について、その専門性・安全性を考慮せよというようなことをあえて別に外さなくてもいいのではないかと、そういうことで、１番と２番について提案をさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-027"},{"speaker":"鈴木（真）副委員長","kind":"提案","question":"阿部委員の提案はわかりました。ただ、正副委員長の間で最初まとめたときには、工事案件に対する総合評価方式、工事案件ということで考えたときに、まだ試行の段階なので、既に１番、２番は実施している部分、そこに一緒にこれから試行する分も含めるかどうかというと、今、ご提案いただいたんですが、私、個人的には３番の試行ということで仕切ったほうがいいのではないかなという気がしております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-028"},{"speaker":"中塚委員","kind":"意見","question":"私も今、副委員長からお話がありましたけれども、確かに３番は試行についてで、こうですよということなので、そういう意味では１と２とは違うものになってくるのかなと思うので、さっきははっきり言いませんでしたけれども、別のものではないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-029"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"１年間副委員長を務めさせていただきまして、ありがとうございました。なかなか最初のうちは活発な質疑が行われなかったんですが、最後になって大分まとめに近づいてから、活発な議論が行われたと思います。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5838#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":17699,"voices":72}},{"id":"h20-20080514-16","meetingId":"h20-cm05","date":"2008年5月14日","dateIso":"2008-05-14","committee":"街づくり特別委員会","time":"午後１時０４分～午後３時２２分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"「東京都観光汽船（株）による水上バス運航の終了」","agenda":"「東京都観光汽船（株）による水上バス運航の終了」","exchanges":[{"speaker":"南委員","kind":"質問","question":"最後のところで、品川観光協会に運航を打診しているような説明でしたけれども、こういうふうに船によるしながわ水族館への来館者が一定程度減っているという、そういう認識は区のほうは持っているのかどうかと、そういう依頼をしている、打診をしている。そういうことは来館者の引き上げ、多くする、そこに効果があるというふうに品川区としては見ているのかどうか、その辺の認識を伺いたいと思います。","respondent":"藤田道路公園課長","answer":"セット券の購入関係では３万６,０００人が、資料のほうにもあります、１９年度の１万５,０００人ということで、半分以下まで落ち込んできているというのが実態でございまして。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"意見","question":"こういう状況の中でどうこうと言うつもりは全くないですけれども、社会的な、経済的ないろいろな状況もある中ですので、水族館への来館者を多くするということには異論はありませんけれども、そのためにまた一定程度の費用が、公費の負担が増えていくので、そういうことはなかなか、今の状況のときには難しい状況があるんじゃないかなというのは思いますので、そのことは意見として伝えておきたいと思います。","respondent":"藤田道路公園課長","answer":"今後の観光協会等への今の打診についても、民間事業者としての独自の運航の検討ができないかというお願いをしておりますので、現段階で区の持ち出しを前提とした検討をしているものとは違うです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"ちょっとその辺が、こちらから打診で働きかけて運航したらどうかとか、してほしいみたいな、そういう言い方が言下にあったのかなというふうに思って聞いていたものですから、区としての公費の負担のところがやはり出てくるんだろうと思いましたので、その辺伺ってみたわけですけれども。なかなか社会状況があってのことなので、難しいかなというのは私としても思っておりますということだけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"ぜひ、これは要望しかないんですが、ぜひ品川観光協会をはじめ多方面にぜひ積極的に働きかけていただいて、せっかく品川区が新・水とみどりのネットワーク構想を立ち上げたところで、ここで冷や水を浴びせかけられるような、構想に対して若干の後退というようなイメージも出てきますし、ぜひ、品川区の魅力は、湾岸から見た品川区の景観も私はすばらしいものがあると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-004"},{"speaker":"稲川委員","kind":"質問・要望","question":"１点だけお伺いしたいんですけれども、参考資料、しながわ水族館航路の収支で、１１年度から１９年度まで折れ線グラフになっているんですけれども、大体常に２,０００万円ぐらいの赤字で来ている中で、１４年度と１５年度が出ていて、３,０００万から４,０００万ぐらいになっているんですけれども、わからないですけれども。２点、教えてください。","respondent":"藤田道路公園課長","answer":"これ、先ほど１３円４０銭というお話をしましたけれども、１ｔ当たり１３円４０銭ということで、私ども、水上バス等を念頭に置いていますので、その船が１日何回着いてもその値段は変わらないというような料金設定で行っているものです。","voiceIndex":11,"id":"exchange-005"},{"speaker":"稲川委員","kind":"質問","question":"もしそうでなくて、このためにつくっているのであれば、なぜなのかなというあれがあるんですが。例えば、今後、水上バスステーションの利用というのは、どういう利用が今後考えられるか、教えてください。","respondent":"藤田道路公園課長","answer":"当然、ステーションはつくるけれども、どこも利用者が見込めないというような形で着工するというわけにもいきませんので、その当初はおそらく並行してお話をし、見込みが立ったということで、着工をしたものというふうに考えてあります。","voiceIndex":13,"id":"exchange-006"},{"speaker":"稲川委員","kind":"質問","question":"最後に１点。先ほど、課長のほうからクルージングに出るための利用とか、単発的な利用があるというんですが、それは民間というか、個人の所有の部分で、そこに集まって、じゃ、クルージングに行こうというのもあり得るのか。民間の使用。民間がもし使用したときの使用料だけ教えてください。","respondent":"藤田道路公園課長","answer":"民間であろうが、どういった施設であろうが、東京都観光汽船も民間会社ですので、１ｔ当たり１３円４０銭という基準は変わりございません。","voiceIndex":15,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"わかる範囲で構わないんですけれども、バリアフリー法の関係で、５００名の席にスロープをつけて２００名になってしまうという話もありますけれども、これは船自体を取り替えなくちゃいけないという部分が発生するのかどうかということと、あと、葛西臨海のほうのルートも既に廃止というお話もちらっとありましたけれども、ほかのルートの廃止状況というか、運用状況というのは。","respondent":"藤田道路公園課長","answer":"それと同じときに、船についても、旅客ターミナルとか船についてもバリアフリーを図りなさいという法律になってあります。そのうち旅客船、船については、２０１０年までに船の５０％についてはバリアフリーの対応にしなければいけないというような法律になってあります。","voiceIndex":17,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"根本的なことをお聞きしたいと思います。３０か４０路線ぐらいあって、１路線だけ黒字だというところがある。これは要はどういう考え方を持つかということだよね。費用対効果。住民サービスも含めて、どういう効果を求めてやるか。それは、例えばコミュニティーバスだって、１回やったらやめられないんだよ。あんな言いわけみたいなことを言わないでと思うんだけれども、どう思うかということを聞きたい。","respondent":"岩田まちづくり事業部長","answer":"現在、観光汽船が運航している中でも、黒字路線というのは観光地と観光地を結ぶ路線、隅田川を中心とした、こちらに限定されているわけですので、先ほど担当課長が申し上げました、不要になったといいますか、使われなくなる桟橋も、観光汽船はこれで使わなくなりますけれども。","voiceIndex":19,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今まさに部長がおっしゃったような模索をぜひしていただきたいなと思います。本当にこれができるのかわからないけれども、例えばカヌーだとか、レガッタ、大学とかでそういう場所を探しているわけですよ。やる場所がないとか。そういうことも。もちろん競艇場もあるからそんな簡単にはいかないかもしれないけれども、あそこへ行けば、いい入り江になっているじゃないですか。広場が。これはお願いだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-010"},{"speaker":"西本委員","kind":"確認","question":"確認だけしたいと思います。先ほどからルートの一つとして考えていたということですが、いろいろ、今までの議論の中で、第二次長期基本計画のところで始まった中で、利用してくれるところを探していたという形だったという点があって、これは、ルート以外に何か観光という形での考え方で、当時品川区がＰＲをしたりとか、そういう関係はなかったのかということをお聞きしたいんですが。","respondent":"藤田道路公園課長","answer":"平成７年から運航を開始したわけですけれども、その中では、定期便としてのバスとしての運航、それから、周遊便のような形も当時はあったというふうなことで確認しています。","voiceIndex":22,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"品川区としてこれを何か利用したという経緯はあるのか。観光という視点で利用するというような動きは過去にあったんでしょうか。それとも全くなかったということの理解でいいんでしょうか。","respondent":"藤田道路公園課長","answer":"今後は、観光アクションプランとかもできてありますので、その辺と連携を図っていくことも非常に大切なことだというふうに感じてあります。","voiceIndex":24,"id":"exchange-012"},{"speaker":"西本委員","kind":"意見","question":"どういう形で観光協会に。ただ単にルートの一つとしてということなのか、それともお金は出さないけれども、利用価値があるんだったら利用してねという形なのか、それとも一緒に今後考えていくから、一緒にやっていこうよというようなスタンスというものか。どういう形で今依頼をしているのか。","respondent":"藤田道路公園課長、岩田まちづくり事業部長","answer":"まだ正式な依頼というような形ではありませんので、打診をしているというような段階です。その中で、１つは定期運航ができるか、できないか。先ほどもお答えしましたけれども、いわゆる移動ルートとして水上を使うというメリットが、これだけ２３区の発達した鉄道網、バス路線網が網羅されているところで、足として需要がこれからあるかといったら、これ。","voiceIndex":26,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"区のほうもある程度かかわりながら、事業連携をとりながらということがよくわかりました。であるならば、ある程度の経費の負担というのは当然あると思いますので、当然少なくするというのは、削減しながら……。必要なことにはある程度区のほうも金銭的な援助というか、そういうのも必要なのかなというふうに思いますので、有効的に使っていただきたいということで要望をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-014"}]},{"id":"topic-02","title":"特定事件調査の「新・水とみどりのネットワーク構想」","agenda":"特定事件調査の「新・水とみどりのネットワーク構想」","exchanges":[{"speaker":"南委員","kind":"質問","question":"目黒川と立会川の浄化対策、本当に長期間、改めて整理できたような気がするんですけれども、不勉強なのであれなんですけれども、目黒川のほうは、とりわけ上流域の自治体の対策というのはどういうふうになっているのか改めてちょっと、不勉強なところがありまして、教えていただければと思うんですけれども。","respondent":"家壽田下水道河川課長","answer":"ただし、これはかなり時間もかかりますし、速効性のある対策がなかなかできない。といいますのも、処理場、水再生センターに持っていく量というのは大体できているんですが、今度、出ていかないためには、雨の降った最初の水というのは大変汚く、汚れています。","voiceIndex":35,"id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"処理場での処理の用地が今どうこうということでのお話だったんだけれども、処理場そのものの機能というのはどの程度きれいになるのかと、それから、世田谷区自身の、目黒川という名前で呼んでいいんですか。よくそれもわからないんですけれども。ちょっと教えてください。世田谷区自身の対策、とっている対策があれば、どういうものなのかというのを、今の説明ではわからなかったので。","respondent":"家壽田下水道河川課長","answer":"ただ、そういったことを、我々も下流側の自治体として指をこまねいているわけではありませんで、目黒川浄化の３区連絡会という中で、世田谷区にも入っていただいて、目黒区ともどもこの目黒川の浄化についてはいろいろ議論、検討、必要に応じて協力もしています。","voiceIndex":37,"id":"exchange-016"},{"speaker":"西本委員","kind":"確認","question":"ちょっと確認です。立会川のほうですが、今いろいろ工事されているんですが、先ほど、５年間にという話なんですが、これは寿命が５年間という形なのか。コスト的には、どのぐらいメンテナンスにかかってくるのか。それだけ教えてください。","respondent":"家壽田下水道河川課長","answer":"費用につきましては、今回、立会川につきましては、立会川浄化としまして２,５００万円を、予算をとっておりますけれども、これ、５分の１とお考えいただきまして、設置と、それからいろいろなリース料を全部５分の１で割っておりますので、この５倍の金額。","voiceIndex":39,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"そうすると、これは、毎年毎年の継続して２,５００万ということで、それがずっと続いてくよ。例えばリース期限が伸びると、イニシャルコストがどんどんかかってくるという形になってくるんですか。","respondent":"家壽田下水道河川課長","answer":"今回の契約は、５年間で今回の機械を使い終わるという前提で考えておりまして、５年後どうなるかにつきましては、そのまま、耐用年数はあと２年残っておりますから、使うかどうかというのは、そのときの立会川の浄化の対策。","voiceIndex":43,"id":"exchange-018"},{"speaker":"西本委員","kind":"質問","question":"修理費とかいうのは多分、状況によっては、壊れてしまうとかいろいろあると思うんですが、それは、例えばそれも入った値段なのか。それプラスアルファ幾らか、そういう形でかかってくるのですか。","respondent":"家壽田下水道河川課長","answer":"そのときには、甲乙協議の中で、当方のほうでも若干河川の維持の予算を持っておりますので、業者側と協議した上で必要な対応をとっていきたいというふうに考えております。","voiceIndex":45,"id":"exchange-019"},{"speaker":"安藤委員","kind":"意見","question":"目黒川のほうからなんですけれども、今回の実験はいつからいつぐらいまでやるのかということと、あと、今回は高濃度ということで、昨年が海水のほうの実験をやっていましたけれども、来年度あたりにその２つの結果を見て、分析して、対策の大きな方向性を考えていくということで、そのスケジュールのほうもわかったらお願いしたいのと、まずそれをお願いします。","respondent":"家壽田下水道河川課長","answer":"契約し次第着手をしまして、実験ですから、去年やったように、今ある、既にあるものを持ってきて実験してもらうということですので、わりと、新しくつくるのと違いますので、早くできる予定でして、できれば６月ぐらいにセットをしたいなと。","voiceIndex":47,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"水とみどりのネットワーク構想のほうなんですけれども、これ、今回正式に決まって、区民の方に広報で５月２１日に知らせていくということなんですけれども、細かい内容というよりも、今自然環境に対する関心がすごく区民の皆さん、関心が高まっていまして、本当に緑だとか、そういうものを求める人というのはすごく多いなというふうに感じているんですけれども、これだけのこういう構想をつくって。","respondent":"松代管理工事課長","answer":"今回の構想ですけれども、２ページをお開きいただきまして、こちらのほうでこの位置づけがあります。基本は、前回もお話ししましたように、区の基本の計画たるものは今進めております基本構想、基本計画というもので、実施計画を練りながら具体的な施策をやっております。","voiceIndex":49,"id":"exchange-021"},{"speaker":"安藤委員","kind":"意見","question":"そういったところで、この構想をより、もっと何というか、この構想を通して環境づくりとか、みどりづくりの前進というか、啓発というか、そういう気運を高めていくような方向でどんどん、恐れずに知らせていってほしいというか。その中で、初めて、どうするかとか、緑を増やすためにはどうするかということで、いろいろな意見が上がってくると思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":51,"id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"そこで、ちょっと気がついたところがあるんですが、結局、雨が降るとまた濁ってしまうということならば、先ほどもそうですが、底辺部は全然変わらない状態じゃないですか。その辺の、底辺部の汚泥についてどう考えているのかをお聞きしたいのと、あと、ちょっとお聞きしたいんですが、先ほど酸素の溶解がゼロというときに、魚というのは自然とそれを察知して、そこから回避していなくなるんですか。","respondent":"家壽田下水道河川課長","answer":"２点のご質問についてお答えします。川の底にたまった汚泥という話をしましたけれども、川の、本当に豪雨になったときというのは、ホースが流されてしまうほどものすごい強い流れになっております。","voiceIndex":54,"id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"例えばこれを１年間実験したら、もうすぐという話ですよね。ある程度、じゃ、着工していこうということになれば、負担は背負わなくちゃならないというところの決め事はそんなに長い先の話じゃないと思うので、そこら辺の気合いのところを教えていただきたいなというのと、それから、立会川とか、目黒川で今、これ、関係あるのか教えてください。そこら辺の気持ちがあれば、教えていただきたい。","respondent":"岩田まちづくり事業部長、松代管理工事課長","answer":"予定では五、六年すれば、１滴も落ちてこなくなる。そうすると、もうほとんど、５年に１回しか５０mmの雨というのは確率的には降りませんから、５年間は海水が行ったり来たりしているだけの川に基本的にはなります。いつごろまでにですけれども、今後、この構想に基づいて、先ほどご説明しましたように、長期基本計画等の中で具体的に施策を打ち出してまいります。","voiceIndex":56,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"簡単でいいんですが、契約に対してですけれども、５月中に仮契約だということですが、このやりとりは区の中ではどこが担当の窓口でしょうか。","respondent":"松代管理工事課長","answer":"窓口は都市計画課街路事業担当のところに、４月から新しく用地担当を主に専任する管理職がおりまして、そこのところで今交渉をしています。都市計画課街路事業のところです。","voiceIndex":64,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"それで、５月に仮契約ということは、この区の暫定的な利用計画というのは了解のもとでということなのか。要は契約の中にはそれが、自由に使ってくださいよという形になっているのか、そこの折り合いというのはどうなって。自由に使える形ですか。","respondent":"松代管理工事課長","answer":"そういった中で、直近で仮契約を結びますので、その仮契約とあわせてこういう整備計画を進めますということは先方にも説明をして、了解を得ております。手続で、最終的に仮契約を結んで、整備等が着手できると、こういうような形で今進んでおるところです。","voiceIndex":66,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"この全体、そう見ると、経理課管理区域という形になっていますが、これも含めてこの全部のやりとりというのは、さっき言った都市計画課が全部やりますよということの理解でよろしいんですね。それで、あと、さっきの部分は、こういう使い方でやっていくよということで了解を得ているという形でよろしいということですか。","respondent":"松代管理工事課長","answer":"そういった意味では、先方も契約を前提として、了解のもと、承諾を得て進めておるものです。","voiceIndex":68,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6364#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":32633,"voices":74}},{"id":"h20-20080520-8","meetingId":"h20-cm05","date":"2008年5月20日","dateIso":"2008-05-20","committee":"建設委員会","time":"午前１１時０１分～午後３時４０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3910#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":1372,"voices":8}},{"id":"h20-20080527-6","meetingId":"h20-cm05","date":"2008年5月27日","dateIso":"2008-05-27","committee":"区民委員会","time":"午後１時１６分～午後１時３７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、議案審査","agenda":"の１、議案審査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"あわせて確認の意味も込めて、エンジェル税制とは何なのか、エンジェルとはだれを指すのかも含めて、ちょっと教えていただきたいんです。","respondent":"武内税務課長","answer":"米国などでは、新興企業の有力な資金提供者となっているということで、日本でも、１９９７年からエンジェル税制ということが取り入れられて、ベンチャー企業と言われるところの投資を優遇しているです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう一つの確認なんですけれども、今回の優遇措置で、特定中小企業、いわゆるベンチャー企業支援のためであるわけですけれども、改めて、ここで言うベンチャー企業の定義を教えていただきたい。ちょっとその疑問があったもので、お伺いしたいと思います。","respondent":"武内税務課長","answer":"そういうときに、ベンチャー企業の株を買った場合について、その部分を控除するというシステムが従来からあります。それは上場株を買ったからでしか恩恵を受けることはできないですね。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼副委員長","kind":"質問","question":"今、エンジェル税制のことで、エンジェルは個人投資家というお答えだったんですが、個人投資家というのは範囲があるんでしょうかね。大きな漠然としたものなのか、どうか、そこの点が１点。それから、優遇税制に該当して減税された件数がどのぐらいあったのか。それから、付則第１４条に該当するケースであると、区が判断するのは、どこでどのようにするのか教えてください。","respondent":"武内税務課長","answer":"現状において、利用率、どのぐらい減税になったのかということですけれども、区のほうで申告を受け付けているわけではありませんので、把握をしておりません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼副委員長","kind":"質問","question":"区のほうで把握をできるシステムになっていないと。この間の質問の中でも、国のほうで、この部分でなかなか伸びないので新たに、というところにおいては、これから国でやられる施策、この間、少し中身を教えていただいたんですが、その辺で、今よりも期待されるというか、中小企業の資金繰りの応援になっていくというとらえ方でよろしいのでしょうか。","respondent":"武内税務課長","answer":"そうしますと、当初、投資しますと、３年後の譲渡益というのが、優秀な企業になれば、利益も出るんでしょうけれども、その裏を返せば、倒産する企業もあるのかなということで、この辺で、ベンチャー企業に投資するのが、ほかの国に比べて少ないということは聞いております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"飯沼副委員長","kind":"確認","question":"一つだけ確認で、国のほうの政策転換というか、その部分はもう既に行われているんですよね。間があくのではなくて、もう既に行われているという理解でよろしいんでしょうか。","respondent":"武内税務課長","answer":"このシステムは、４月１日から制度として始まっているということです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"渡辺委員","kind":"質問","question":"前回の委員会の報告で、住宅ローン控除のほうの対象者の数字を伺った際に、４月末で２,６５１人いらっしゃると。","respondent":"武内税務課長","answer":"その予測は数百人とさせていただいて、５月からの申請は、まだ１件も受け付けておりません。","voiceIndex":15,"id":"exchange-006"},{"speaker":"渡辺委員","kind":"確認","question":"もう一遍確認で、今、６月９日の賦課決定の後で、漏れていらっしゃる方に何らかのアクションをされるということで、申告制度などで、普通だったらそこまではない経緯の中で、そういったことが、区民のためという点で、なされるという解釈をしてよろしいんでしょうか。確認です。","respondent":"武内税務課長","answer":"ですから、そういった意味では、今年始まった制度ですので、今後、平成１８年度に購入された方については、平成２７年まで続きますので、申告漏れがありますと、さかのぼってやるようなことでありますし、いつまでも知らないということになりますと困りますので、今回。","voiceIndex":17,"id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"自民党といたしまして、賛成という表現ですか、それとも承認という表現でしょうか。自民党会派としまして、承認ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"承認なんですが、ちょっとその理由を述べさせていただきたいんですけれども、この改正項目１については、これまで受けられていた住宅ローン控除が受けられなくなる対策のために行われるということですので、当然ですけれども、必要であり賛成という立場です。したがって、今回、専決処分された条例の改正に対して承認です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"}]},{"id":"topic-02","title":"でございますが、委員長報告","agenda":"でございますが、委員長報告","exchanges":[{"speaker":"飯沼副委員長","kind":"質問・要望","question":"早いもので、もう１年が過ぎてしまったなと思います。皆さん、１年間、ありがとうございました。１年間を振り返ると、私自身もまだまだ不十分というか、区民の生活実態が、ここでいっぱい論議を戦わせるような議会の活性化がまだまだ求められているのかなと考えています。これからも、課題としていきたいと考えています。理事者の皆さんも、１年間、ほんとうにありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2516#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":6381,"voices":31}},{"id":"h20-20080527-5","meetingId":"h20-cm05","date":"2008年5月27日","dateIso":"2008-05-27","committee":"総務委員会","time":"午後１時１８分～午後４時２０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"武内副委員長","kind":"質問・要望","question":"林委員長より、本日欠席との連絡をいただいておりますので、ご了承を願います。本日も効率的な委員会運営にご協力をよろしくお願いいたします。なお、お手元に平成２０年陳情第４号の写しを配付しております。これは、議長より参考送付を受けたものですので、後ほど、各自ご覧いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":1,"id":"exchange-001"},{"speaker":"武内副委員長","kind":"意見","question":"予定表の１、議案審査に係わる現地を視察に参りますので、委員および同行される理事者は、第３庁舎前のマイクロバスにご乗車ください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":2,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問・要望","question":"ちょっと、この辺をどういうふうに受けとめればいいのか、教えていただきたいんです。例えば第三日野小学校とか、第一日野小学校なんかは、今、計画審議の中で設定されているわけです。それから、財政としての、この後の流れといいますか、全体でほぼ９６億円ぐらいになりますので、どういうふうに入ってくるのかということを教えていただければと思います。","respondent":"阿部経理課長、市岡総務部長","answer":"今、出ましたけれども、例えば八潮につきましては、後で説明しますけれども、６月３０日の工期になっていますけれども、実は、最終の工期が６月でございまして、その前の４月には新しい校舎に移るという形になりますので。全国的に見ると、地方の敷地に十分に余裕があって、工事の困難度も比較的容易なところと、東京都のように、今日見ていただいたように。","voiceIndex":7,"id":"exchange-003"},{"speaker":"菊地委員","kind":"意見","question":"２年の債務負担という話、工期という話はわかるんです。ただ、前段で申し上げたように、今年度の当初予算を組むときに、議会で言うと第１回定例会のとき、ここで十分に出してこれた範囲なのかなという気がするんです。２年の債務負担行為って、第１回定例会で出すと、そうじゃなくなるというわけではないんですよね。ちょっと、そこをもう少し。","respondent":"市岡総務部長","answer":"非常に例外的には、補正予算と同時に契約議案を出すという例が全くないわけではないんですが、これは年間予算をもとにした学校の改築、新築の工事ですから、原則どおりこういうステップをとることが、ご審議を通じて議会のご意思を的確に反映するという原則ですので。","voiceIndex":10,"id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"別に、私は、学事制度審議会を支持するわけではないんですけれども、そこのところとの関係で考えたときに、今回の工事というのは、単純に耐震とか、そういうことではなくて、かなり大きな工事ですから、今の時期に手をつけていくということそのものをどのように受けとめればいいのか。この辺もちょっと、お聞かせ願えればと思います。","respondent":"日下部企画財政課長","answer":"学事制度審議会につきましては、小中一貫校の何校かにわたる構想とか、そういう規定の部分をまず一つの手法の前提として、それ以外の学校の配置のあり方ということについて、今、検討を進めているということで、少し切り分けてご理解をいただきたいと思います。","voiceIndex":12,"id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"第三日野小学校が全体では２６億円ぐらいでしょうか。いつもの話になっちゃうんですけれども、全体を見ると、第一日野小学校・幼保一体施設は、２社のうち１社が辞退するということで、この辺、どういうふうに受けとめればいいのかなと思うんです。","respondent":"阿部経理課長","answer":"それを見ましても、鉄鋼関係については、ほかの例えば食料品と違いまして、去年との比較では十数％値上がりしたということもあります。私どもとしては、建材、鉄鋼関係が値上がりしているという認識しております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"だから、どういうふうに改善をしていくのかというと、結局、東京都での年の見直し回数を増やしたとかという話がありましたけれども、それでも追いつかないという受けとめでいいんでしょうか。そこは、区としてどういうふうに改善できるのかというのが、よく見えてこないんです、この間の動きでも。もう一度、そこら辺を。","respondent":"宍戸施設担当課長","answer":"予定価格をこちらで算定するんですけれども、これまでは１回ぐらいの改定だったのを、年４回に増やした部分で、今回、東京都の財務局のほうでも、４月中旬に１回変えて、５月１日付でも、６月１日付でも変えるというような部分的な改定を加えているところです。","voiceIndex":16,"id":"exchange-007"},{"speaker":"浅野委員","kind":"提案","question":"補助金なんですけれども、うちの場合は、今回は三つの学校について補助金をいただけるということになっていますけれども、ほかの市区町村と数が重なって補助金が足りないということになれば、例えば、ちょっとずらしてくださいとか、当初の計画に対して、そういうようなものがあってずれたとか、そういうことって今まであったのかどうか、ちょっとお伺いしたいんです。","respondent":"日下部企画財政課長","answer":"少し厚みも増しつつあるというような状況です。","voiceIndex":18,"id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"そうしますと、品川区の場合は当初の予定どおり、耐震を含めて改築のほうも着々と進んできているという認識で納得をします。それともまた、特に考慮せず、当初の価格どおりやってもらうようになるのか、ここら辺を、ちょっと教えていただければと思います。","respondent":"阿部経理課長","answer":"この契約金額の変更というのは、区単独の話ではございませんので、国、あるいは東京都、２３区を含めまして全体の問題ですので、今後、国の検討状況を注視していきたいと考えています。","voiceIndex":20,"id":"exchange-009"},{"speaker":"浅野委員","kind":"意見","question":"これからどうなるかと思うんですけれども、やはり、業者の収益を圧迫しては困りますし、また、きちんとした工事をしてもらうためにも、それなりの金額が必要かと思いますので、ここのところは、動向を見ながら、業者ともうまくいい関係をつくりつつ、いい物件をつくってもらうように努力していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-010"},{"speaker":"土井委員","kind":"確認","question":"これは、総合的な発想であるかどうかは別なんですけれども、既存校舎解体というのがありますけれども、この図面等ではわかりませんので、ちょっとお伺いしたいんですが、例のアスベストの問題とか、そういうものはないと見てよろしいんですか。","respondent":"阿部経理課長、宍戸施設担当課長","answer":"１点目のご質問です。冒頭にも申し上げましたけれども、制限付き一般競争入札で行っております。ここには５社というか５組といいますか、その方がＪＶを組んで参加なさって、委員おっしゃったように、結果として、３社が辞退をしたです。アスベストについてです。非常に危険性があるという吹き付けアスベストについては、一切ございません。成形板については幾つかあるんですけれども、それも法に基づいてきちっと処理するということで考えております。","voiceIndex":23,"id":"exchange-011"},{"speaker":"原委員","kind":"質問・要望","question":"同じような質問になってしまうかもしれないんですけれども、今、第三日野小学校ということなんですけれども、若干関連して第一日野小学校の件も出てまいりますが、ちょっと質問させていただきたいんです。落札したほうが、予定価格よりほんとうに低い、もう９９.何％。これがいい、悪いということではないので、工事発注者としての意見があれば、また、ちょっと感想的なものがお聞きしたいんです。","respondent":"阿部経理課長","answer":"ただ、先ほども申し上げましたとおり、業者が辞退されたというのは、私どもとしては非常に残念だと考えています。","voiceIndex":26,"id":"exchange-012"},{"speaker":"原委員","kind":"質問・要望","question":"やはり、高騰でかなり辞退者が出ているというところもあるんでしょうけれども、私自身が指摘をさせていただきたいのは、やはり区民の税金でやるわけですから、当然国からも来ますけれども、結局、品川区が被害をこうむらないような形で工事をやっていただきたい。そこのところについて、もう１回。","respondent":"本間副区長","answer":"当然ながら、区民の利益になるような、きちんとした入札はしているわけですが、そのような予定価格を公表しているという状況からの面もあるとうことは、ひとつご理解いただきたいと思います。","voiceIndex":28,"id":"exchange-013"},{"speaker":"菊地委員","kind":"質問","question":"すみません、もう一つだけ。先ほどちょっと、浅野委員が耐震化も着々と進んでという話があったので、ちょっとお聞きしておきたいんですけれども、今回の議案でいえば、かなり大きな工事になっちゃいますけれども、耐震化そのものも、まだ手がつけられていない小学校、中学校が何校かあるように思うんです。小・中学校でどのぐらいあるのか、教えていただけますか。","respondent":"宍戸施設担当課長、市岡総務部長","answer":"小中一貫校ができ始めていますので、どういうふうに数えるのかというのは非常に難しいんですけれども、平成２０年度までに、耐震工事もやっていない、改築予定もないという、平成２１年度以降対応の学校が１２校あります。その結果に基づいて、緊急度、必要度の高いところから工事をしておりますので、今申し上げた数字は、相対的に、時期的に言えば、優先度をやや後に持っていっても可能だということでやっているわけで、別に残っているというとらえ方を。","voiceIndex":30,"id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"今、おっしゃられたことは、以前にもお聞きしました。終わった直前に、また基準が変わったというお話は聞いているんです。ということは、今のお話だと、１２校すべてが、その直前の改修の中で行われたので、現状で残っているんだというふうにとらえていいんですか。","respondent":"宍戸施設担当課長","answer":"当区におきましても幾つか不調になった現場もございまして、その辺の割り振りということで、平成２０年度は夏休みの耐震改修工事は１１校にさせていただいているんですけれども、そういう形で振り分けさせていただいているというものです。","voiceIndex":33,"id":"exchange-015"},{"speaker":"菊地委員","kind":"質問・要望","question":"今までの基準ではだめだ、危ないということで基準が変えられたわけですから、今のお話で、とりわけ二重投資というんですけれども、よしんば統廃合になる学校だとしても、明日そういう地震がくるかもしれないわけですから、そこに手をつけずにいるというのは、品川区は、ああいう教訓をどのようにとらえるのかということに、今の話だと疑問を持たざるを得ないんですけれども、そこら辺はどうなんでしょうか。","respondent":"日下部企画財政課長","answer":"確かにいろいろな事情がありまして、少し先送りというような、平成２１年度以降になってしまうというような学校もありますけれども、これについても、区としては、やはり早急に耐震改修を進めていくという基本方針に変わりはございませんので。","voiceIndex":35,"id":"exchange-016"},{"speaker":"武内副委員長","kind":"意見","question":"ほかに発言がないようですので、これで質疑を終了いたします。これより、第３０号議案、第三日野小学校改築工事請負契約について、採決をいたします。ご意見がありましたら、お願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-017"},{"speaker":"菊地委員","kind":"質問・要望","question":"第三日野小学校の改築について、反対するものではないんですけれども、ただ、今、お話があった第三日野小学校にしても、第一日野小学校にしても、かなり巨額な税金使って改修する中で、やっぱり最後にお聞きした学校耐震の問題で、そこで出ていた地元の要望だとか、二重投資だとかという枠組みを一気に越えて、耐震改修の手がついていないすべての学校は、きっちりと早急に行うべきものだと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-018"},{"speaker":"武内副委員長","kind":"意見","question":"ご異議なしと認めます。よって、本案は原案のとおり可決決定いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-019"},{"speaker":"武内副委員長","kind":"意見","question":"ご異議なしと認めます。よって、本案は、原案のとおり可決決定いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-020"},{"speaker":"武内副委員長","kind":"意見","question":"ご異議なしと認めます。よって、本案は、原案のとおり可決決定いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-021"},{"speaker":"武内副委員長","kind":"意見","question":"ご異議なしと認めます。よって、本案は、原案のとおり可決決定いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問","question":"これだけ大規模な工事であるし、それからもっと言うと、これから議案として出てきます庁舎の耐震工事についても、もし同じような状況であるなら、工事の安全というものが保たれているとは思うんですけれども、しかも、これらの契約は特に問題ないと思いますよ、だけれども、この第一日野小学校・幼保一体施設については、競争もなくて、他の会社が辞退をして、ある意味。","respondent":"阿部経理課長","answer":"工事の金額の件ですけれども、先ほど、副区長からもご答弁申し上げたとおり、厳密な積算を行いまして、その結果の金額を予定価格として公表しているものです。","voiceIndex":49,"id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問・要望","question":"外見的な見方かもしれないけれども、これを公平な競争でやるなら、５社ぐらいあって、辞退なしで応札の中で一番低いところが落とすというのならまだわかるんだけれども、たまたま金額が大きくて、結果として１社が辞退をしたということになっているわけですから、やっぱりそのことについては、気持ちとしてなんですけれども、公正なことをやっているとは思うんですけれども、やっぱりもっともっと透明な形を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-024"},{"speaker":"菊地委員","kind":"意見","question":"どうしても、今の伊藤委員の話と似たような話になってしまう部分があるんですけれども、ほかの電気設備だとか、給排水設備だとか、そちらのほうは、どの案件を見ても、あまり辞退をされる業者はいませんよね。一方で、こういう本体工事については、よく辞退をされる業者がいる。確かに金額的にも全然違う部分があるんですけれども、その辺の違いはどういうふうに見ていらっしゃるのか。それだけ。","respondent":"阿部経理課長","answer":"先ほどからご意見が出ておりますけれども、本体工事につきましては、資材の関係のことが、辞退が多いということと関連しているのかなとは思っています。","voiceIndex":52,"id":"exchange-025"},{"speaker":"菊地委員","kind":"質問","question":"確かに、これまでの話だとそういうことなんでしょうけれども、ただ結局は、今のご答弁だと、総務委員会で、これまでもいろいろな形でこういう意見が出されたけれども、そこは全然変わっていないし、変えようがないんだというとらえ方をしてもいいんですかね、私のほうは。","respondent":"宍戸施設担当課長","answer":"それ自体を変えなければならないとなると、やはり一つの区だけで、うちの区は見込みも含めてこうします、上乗せしますということは非常に難しくて、こういうふうな事態を踏まえて、国でどうするかということになります。","voiceIndex":54,"id":"exchange-026"},{"speaker":"土井委員","kind":"質問","question":"同じようなことを聞くんですけれども、結局、ＪＶを組む条件がいろいろあるわけですよ。そのかわり、ちゃんと責任を持った業者が入ってくる、目に見える業者がやるわけですから、むちゃくちゃなことはやらないと。そうすると、今度は逆に、区内業者育成という話は全然ふっ飛んじゃうことになるので、ここのところは僕は悩むところなんですけれども、どうお考えでしょうか、ちょっと聞かせてください。","respondent":"阿部経理課長","answer":"今回の第一日野小学校・幼保一体施設の場合ですけれども、先ほども説明がありましたが、ホールがありますので、ホールをやった経験がある会社というのが、いわゆる第１グループ、親会社と言いますけれども、今回は３社で組んでいますけれども、それ以外の２社の第２グループ。","voiceIndex":56,"id":"exchange-027"},{"speaker":"原委員","kind":"質問","question":"今のはお願い事です。そうなってくると、工事自体の技術力、今も土井委員のほうからお話があったように、地域業者の育成と勉強、要するに技術力をアップしていただくという意味合いでは非常に大きいものだと思うんですけれども、特に安全をほかよりも一層という言い方はおかしいけれども、非常に高低差ですとか、いろいろな問題があるエリアですから、その辺について、一言お話を伺いたいと思います。","respondent":"宍戸施設担当課長","answer":"したがいまして、区内業者とチームワークよく、きちっとした工事をしていただけるものと、こちらとしては確信しておりますし、議決をいただいた後に、架設計画その他、十分工事会社とも練って、十分な説明をしてご安心いただいた上で、実際の工事にかかればと考えております。","voiceIndex":58,"id":"exchange-028"},{"speaker":"武内副委員長","kind":"質問・要望","question":"６番のほうも７億円近いんですけれども、ほかは大体８億円台なので、さっきの原委員の話と逆で、そんなことはないでしょうけれども、我々からすると逆に、こんなに違っちゃうと逆に大丈夫なんだろうかということがあるので、なぜこんなに安くできたのかがわかれば、しっかりやってくれればいいんですけれども、何か特別な技術的なものでそのぐらい安く見積もれたのなら、それでいいんですけれども。","respondent":"阿部経理課長","answer":"１点目、申しわけございません、記入ミスです。２点目の、電気設備工事ですけれども、積算等は変わりございませんので、落札者がどうしても工事を取りたいという意欲なのかなと思います。","voiceIndex":60,"id":"exchange-029"},{"speaker":"武内副委員長","kind":"質問・要望","question":"非常に頑張っていただいてありがたいんですけれども、そういう面では、できればしっかりチェックという言い方はおかしいんですけれども、まさかそんなことないと思いますけれども、特に金額がかなり違っていますので、きっちり品川区のほうで考えている内容がちゃんと担保されて、履行されるようにお願いしたいと、これは要望させていただきたいと思います。ほかによろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-030"},{"speaker":"武内副委員長","kind":"意見","question":"ほかに発言がございませんので、これで質疑を終了いたします。これより、第３４号議案、第一日野小学校・幼保一体施設および（仮称）教育複合施設改築工事請負契約について、採決をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-031"},{"speaker":"武内副委員長","kind":"意見","question":"ご異議なしと認めます。よって、本案は原案のとおり可決決定いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-032"},{"speaker":"武内副委員長","kind":"意見","question":"ご異議なしと認めます。よって、本案は、原案のとおり可決決定いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":65,"id":"exchange-033"},{"speaker":"武内副委員長","kind":"意見","question":"ご異議なしと認めます。よって、本案は、原案のとおり可決決定いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-034"},{"speaker":"武内副委員長","kind":"意見","question":"ご異議なしと認めます。よって、本案は、原案のとおり可決決定いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-035"},{"speaker":"菊地委員","kind":"質問","question":"生徒数なんかも、わかれば教えていただければと思います。","respondent":"宍戸施設担当課長","answer":"生徒数としては、現在、６４８人です。プールですが、ほかの小中一貫校も同じですが、温水プールということで、かなり長い期間使用することができます。","voiceIndex":71,"id":"exchange-036"},{"speaker":"菊地委員","kind":"質問","question":"日野学園でやられていますよね。夏場、子どもたち自身が使えないという話も、ちょっと耳にしているんです。本来、子どもたち自身が、夏休みだろうと何だろうと利用できる体制で考えるべきなのではないかなと、今のプールのあれを見て思うんですけれども、どうなんでしょうか。","respondent":"宍戸施設担当課長","answer":"したがいまして、屋外のプールで、天候を気にしながら使うよりも非常に有効に使えていると聞いております。それから、一般開放につきましても、そういうふうに、そのほかの期間に非常に安定してカリキュラムが組める関係上、夏休みに開放しても全然支障がないと聞いております。","voiceIndex":73,"id":"exchange-037"},{"speaker":"菊地委員","kind":"意見","question":"総務委員会の席で、どう言えばいいのかよくわからないんですけれども、少なくとも、子どもたちが実際にはなかなか使えない、要するにお金を出さなくちゃならないとかいうあり方というのは、学校施設として考えたときにどうなのかと。二つつくるのか、三つつくるのかは別としても、施設としてはやっぱり、そこは考えるべき部分ではないかなと思うんです。","respondent":"日下部企画財政課長","answer":"その辺の基本的な考え方というのは、今後もそれをベースにしながらカリキュラムの編成等をしていくと考えておりますので、そういうご意見があったということで受けとめていきたいと思います。","voiceIndex":75,"id":"exchange-038"},{"speaker":"菊地委員","kind":"質問・要望","question":"よろしくお願いします。ただ、施設の有効活用という言い方で言えば、学校施設ですから、当然のことながら、夏休みだろうと何だろうと、子どもたちがまず中心になって利用できて初めて有効活用なんだと思うんですよね。実際に動いている日野学園のところでも、先ほどの施設担当課長ではないですけれども、そういう話を漏れ聞いておりますので、ぜひそこはよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-039"},{"speaker":"伊藤委員","kind":"質問・要望","question":"すべての小学校にかかわるところだと思うんですけれども、教室の中については、まだまだこれから議論していくんでしょうけれども、私たちがずっといい続けてきたところの一つに電子黒板というのでしょうか。ですから、イメージとしては、教師とパソコンがあって、それをプロジェクターを通してスクリーンに反映させる。それについては、ちょっと答弁をいただいておきましょうか、まだまだ検討の段階ですかね。","respondent":"福田企画部長","answer":"ご質問の趣旨につきましては、教育のあり方というふうに理解することができますので、私どもは私どもなりに、それから、教育委員会事務局にも、その旨をお伝えをして、どういうふうにできるのか検討させていただきたいと思います。","voiceIndex":78,"id":"exchange-040"},{"speaker":"菊地委員","kind":"質問","question":"これらが今実際に動き出した中で、だれもが納得できるような検証をきちんとして、区民に対して明示をすべきだと思うんです。ですから、今回の施設を新たにつくり上げるというところでは賛成をしますけれども、教育そのものについて、果たしてどうなのかという検証を明確にすべきであると思いますし、その教育のあり方そのものについては反対をする立場で、この議案について賛成すると言えると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-041"},{"speaker":"武内副委員長","kind":"意見","question":"これより、第３８号議案、小中一貫校八潮学園建設建築工事請負契約について、採決をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":84,"id":"exchange-042"},{"speaker":"武内副委員長","kind":"意見","question":"ご異議なしと認めます。よって、本案は原案のとおり可決決定いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":85,"id":"exchange-043"},{"speaker":"武内副委員長","kind":"意見","question":"ご異議なしと認めます。よって、本案は、原案のとおり可決決定いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-044"},{"speaker":"武内副委員長","kind":"意見","question":"ご異議なしと認めます。よって、本案は、原案のとおり可決決定いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-045"},{"speaker":"武内副委員長","kind":"意見","question":"ご異議なしと認めます。よって、本案は、原案のとおり可決決定いたしました。以上で、議案審査を終了いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-046"},{"speaker":"武内副委員長","kind":"質問","question":"予定表３の委員長報告についてですが、議案審査の結果報告については、正副委員長にご一任いただけますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1784#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":27498,"voices":90}},{"id":"h20-20080602-6","meetingId":"h20-cm06","date":"2008年6月2日","dateIso":"2008-06-02","committee":"区民委員会","time":"午後１時０３分～午後４時４０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、幹部職員紹介","agenda":"の１、幹部職員紹介","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"区政協力委員会のことですが、協議会を行って、地区別に４回ぐらい行うということですけれども、区民要望などを正確に把握して区政に反映することが一つの大きな内容だと思うんですけれども、実際にどのような話し合いが行われているのかお伺いしたいと思います。それから、ここにどのように魂を入れていくのかということが大事になってくると思いますので、その辺の考え方もお伺いたいと思います。","respondent":"中山地域活動課長、高濱生活安全担当課長、金子産業振興課長","answer":"具体的な内容については、さまざま地区ごとに極めてローカルな具体的なまちづくりのあり方に関するご質問があったり。保護者の方からも安心できるという声をいただいておりますし、また今年度ですけれども。中小企業ワークライフバランス支援事業ですけれども、これは次世代育成支援対策行動計画に基づく一環としたもので。","voiceIndex":52,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"中小企業のほうですが、ワークライフバランスは、去年１年課長もかかわっていて講習会も出られたと思うんですけれども、何か見えてきたことはどういうことなのかお伺いしいと思います。そのような影響調査は含まれていないのかどうか。含まれていないのでしたら、それは行うべきではないかと思います。","respondent":"金子産業振興課長、小野区民課長","answer":"モデル事業そのものは今年度も継続して展開するわけですけれども、来年以降、どういった事業ができるかということは、私どもは常々事業展開している中で考えながら検討しておりますので、今年度事業を展開する中で。自衛隊の募集事務にかかわるご質問ですけれども、１４ページにも根拠として書いてありますように、これは政令に定める法定受託事務という形になっておりまして。","voiceIndex":56,"id":"exchange-002"},{"speaker":"渡部委員","kind":"質問","question":"一つだけ、事務事業概要の地域活動課の中で２ページなんですが、１３地域センターの中で窓口事務が二通りに分けられているところの理由を教えてください。例えば、私が地域の方から「なぜ、荏原第三地域センターで届出ができないのか、他に行かなければいけないのか」と言われた場合、どのような返事をすればいいのか、なぜ分かれているのか教えてください。","respondent":"中山地域活動課長","answer":"これは平成１２年のときに組織的な見直しを行った際に、地域センターを異動処理もできるところと、その他のところと分けたわけです。","voiceIndex":59,"id":"exchange-003"},{"speaker":"渡部委員","kind":"意見","question":"仮に、それがわからないで行ってしまった人がいた場合は対応なさるのか。せっかく来ていただいたけれども、もう１回ご足労願うけれども、本庁に行ってくださいというような対応をされているのか。","respondent":"中山地域活動課長","answer":"結論から言うと、その地域センターでできない事務については、近隣の処理ができる地域センター、もしくは本庁に丁重にご案内するという形になっております。","voiceIndex":61,"id":"exchange-004"},{"speaker":"宮崎副委員長","kind":"質問","question":"国民健康保険のところと産業振興のところで聞きたいと思います。もう１つは、今回メタボリックシンドロームに着目して、今までの内容と変わってきます。例えば、平成２４年度は平成２０年度比１０％減少となっているんですけれども、この目標にいかないとどういう影響が出てくるのか。例えば、区民の保険料へのはね返り等がどのような感じになってくるのか、その辺の大まかな仕組みをお伺いしたいと思います。","respondent":"本城国保年金課長","answer":"今のところはそちらまでですが、それを踏まえた保険料の設定になる見込みだと思います。","voiceIndex":63,"id":"exchange-005"},{"speaker":"宮崎副委員長","kind":"質問","question":"先日、ある方から「区内にいろいろ散歩コースがあるすけれども、ウォーキングコースとかジョギングコースがあったら一定の年齢以上の方にお知らせして、健康づくりを支援する１つの手助けになると思うんですけれども、散歩コースだけではなくて、ウォーキングコースとかジョギングコースとか何かやったらどうだ」と言われて、「ああ、そうだな」と思ったんですけれども。","respondent":"本城国保年金課長","answer":"ご質問の後段の部分からですが、今回の特定健診で今までと違う大きなところは、特定保健指導につながるですので、それぞれの方の状況に合ったウォーキング等も含めたプログラムを提示して対応していくことになります。","voiceIndex":65,"id":"exchange-006"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"実際に他区ではほかの自治体との乗り入れをやっています。それから、産業振興のほうで１点だけなんですが、区内の中小企業の方々は募集してもなかなか社員が来ないので困るという声を聞きます。学生のほうに、品川区内の企業が募集していることが伝わっていないのではないかという気もするし、その辺のところは何か工夫があるのか、考え方とか現状も含めて何かあったらお聞かせいただきたいと思います。","respondent":"金子産業振興課長","answer":"これも非常に大きな問題で、定年が明確にない会社もありますけれども、一定程度延長して対応している企業が多いように聞いております。","voiceIndex":67,"id":"exchange-007"},{"speaker":"宮崎副委員長","kind":"意見","question":"ハローワークと連携という話ですけれども、もっと新卒獲得への働きかけというか、戦略というか、そういうものがあってもいいのかなという感じがしているんです。そこのところはもう少し考えたほうがいいという感想を持ったところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"１５ページの大気汚染調査でお伺いしたいと思います。この間、１０年間で喘息患者が小・中学校に行く子どもの中では倍加しているということもあって、一般的に大気汚染が大分改善されている中でも、そういう実態があるということで、ＰＭ２.５についてもきちんと規制していこうという流れになりつつあるわけですけれども、ここの事業の中ではＰＭ２.５の扱いはどうなっているのか伺いたいと思います。","respondent":"工藤環境課長、島袋品川区清掃事務所長、秋山資源循環推進課長","answer":"１点目が、大気汚染についてのお尋ねです。私どもは環境測定ということで、大気汚染に関しましては常時継続的に把握しています。事業者に対するごみ減量の指導ですけれども、先ほど資源循環課長が説明したと思いますけれども、７５ページにありますけれども。容器包装リサイクル法に基づくプラスチック容器包装を私どもは今回モデル実施しているわけですけれども。","voiceIndex":79,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"例えば自販機で飲み物を１本買うと缶で出てきますけれども、リターナブルの缶を普及させて、中身だけ自販機で売るような、そこまでいかないまでも、そもそも商品をつくる事業者側がこれをつくったらどういう影響を与えるのだろうか、ごみにならないだろうかというところまで考えていただきたい面もあるんですけれども、そういうふうに企業の考え方を変えていく、姿勢に立たせることが大事だと思うので。","respondent":"秋山資源循環推進課長、工藤環境課長","answer":"ごみとして出てしまうものがありますので、どうしてもリサイクルできないものについてはサーマルリサイクルということで、今回実施するという形で考えておりまして、事業者についてもペットボトルの減量等しておりますので。その部分での範囲ですけれども、まだお話がない。ただし、さまざまなマスコミ、新聞等でも話題になっているということですので、引き続き委員がご質問をされた点につきましては、状況を把握しまして、対応していきたいと考えております。","voiceIndex":83,"id":"exchange-010"}]},{"id":"topic-02","title":"の学校の夏季休業中における地域食事サービス","agenda":"の学校の夏季休業中における地域食事サービス","exchanges":[{"speaker":"宮崎副委員長","kind":"意見","question":"細かいことですが、要するに配食ボランティアが夏休み期間中も配食ボランティアに配ってもらうということではなくて、配食ボランティアには別のことをやってもらうとことですね。そのまま配ってもらえばいいのではないかという気がするんですけれども、その辺はなぜこうなるのかよくわからないんですけれども。","respondent":"中山地域活動課長","answer":"例えば、学校から商店街に持っていって、そこでボランティアという形を取れなくはないんですけれども、昨今は猛暑等もありまして、ボランティア自身も夏休みの期間に頑張っていただいているわけですが、ボランティア自身もかなり高齢化等が進んでいる中でいろいろ考えたものです。","voiceIndex":91,"id":"exchange-011"},{"speaker":"宮崎副委員長","kind":"質問","question":"そうすると、夏の間は暑いので休んでもらおうということならわかります。４回と２回のお知らせと名産品というのは、参加人数が少なくなっていくこともあるかなということですね。要するに、ボランティアが少なくなるかもしれないということですか。","respondent":"中山地域活動課長","answer":"確かに、夏だけで見れば、２カ月は休みたいということになれば、従事者が減る可能性はあります。","voiceIndex":93,"id":"exchange-012"},{"speaker":"宮崎副委員長","kind":"意見","question":"状況はわかりましたけれども、私の知っているボランティアはやる気のある方なので、ボランティアの意見を聞いてからやっているのだろうと思うんですけれども、もしかして水を差すようなことにならないかと心配なので聞いてみたんですけれども、わかりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-013"}]},{"id":"topic-03","title":"の緊急資金「景気対策経営サポート資金２００８」","agenda":"の緊急資金「景気対策経営サポート資金２００８」","exchanges":[{"speaker":"稲川委員","kind":"質問","question":"簡単にお答えいただければと思うんですが、９番の平成１９年度の実績が２０９件となっているんですが、融資実行ではなく平成１９年度の申し込み件数は何件になっているのか。実際どのぐらいなのか教えてください。多分、２０９件の申し込みがあって、２０９件に実行していないと思うので、融資が受けられなかったところは、何が理由だったのか。それから、審査にどのぐらいの時間がかかるのか教えてください。","respondent":"金子産業振興課長","answer":"融資が適用できない場合には、そのほかの経営指導をきちんとするということは、商工相談員の責務として課しているものですので、そういった形で対応しています。","voiceIndex":101,"id":"exchange-014"},{"speaker":"稲川委員","kind":"質問・要望","question":"外から入ってくる話で恐縮ですけれども、緊急資金ということですから、やはりここに申し込まれる方はせっぱ詰まった方が多い中で、品川区がやっているから、行けば何とかなるだろうというような話で行く方も多くて、中には違う解釈でとらえて、品川区に申し込めばだれでも借りられるという感覚でいる方も中にはいらっしゃると思うので、その辺をもっと周知して、しっかりやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"新たな支援策も検討していく必要があるのではないかと思うんです。例えばほかの自治体でこういうことをやっているところがあるとか、そういったことをつかんでいることがあれば伺いと思います。","respondent":"金子産業振興課長","answer":"他区の新たな支援策ということなのか、他区の動向ということなのか、わかりかねる部分があるんですが、同じようなものの他区の動向という意味では、城南５区の中では港区、目黒区、世田谷区につきましては。","voiceIndex":104,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"やはり、共産党としては全く実態とかけ離れたお金が回り回って、何の罪もない真面目に働いている人たちあるいは発展途上国の人が食糧難になってしまうような、行き過ぎた投機というのはおかしいのではないかという立場で、それは国際的に一致して規制をすべきだという考えですけれども、やはりこういう支援策をやっていくと同時に、大もとのところで異常なぐらいの原油高ですから。","respondent":"金子産業振興課長","answer":"国への予算要望等々につきましては、２３区の区長会あるいは全国の市長会でまとめているところでありますので、それについては別途検討させていただきたいと思います。","voiceIndex":106,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"国への予算要望は区長会でということですけれども、どのような要望をこの問題に関してされているのかということと、ぜひその要望の中に国に対して意見を言うときに、品川区も代表の人なわけですから、区民の立場に立って、罪のない方々を苦しめるような、投機家の無法な儲ければ何でもいいというような投機は規制すべきという、国はそういう立場に立つべきだということを。","respondent":"金子産業振興課長","answer":"今現在高騰している現状がありますが、この先マスコミ等の報道のように、さらに続伸していくのかあるいはこのラインで落ち着いていくのか、その辺は状況としても見極めていかなければならないと思いますので、そういう意味では注視しながら予算要望等の機会にあわせて。","voiceIndex":108,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"原因は一様ではないかもしれないですけれども、実際に政府でも公式に認められているわけですから、いろいろな理由があるにしても、そのうちの大きな理由ということは明白なわけです。ですから、その区民感情にぜひ寄り添っていただいて、今の営業や暮らしを圧迫している高騰の原因になっているものに対して、何とか原因に対してきちんと改善していくという立場に立っていただきたいと強く思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-019"},{"speaker":"宮崎副委員長","kind":"確認","question":"確認しておきたいんですけれども、今回の目的は「原油、素材等の価格高騰により」ということになっていて、対象者のところでは「以下のすべての要件に該当することが必要です」ということです。対象者のところに、原油、原材料等の高騰ということが入ってくるのかどうか、目的にはあるけれども、その関係がよくわからないので、どうなんでしょうか。","respondent":"金子産業振興課長","answer":"委員ご指摘の原油、素材等の価格高騰というのは、あくまでも資金を設けるための目的でありまして、対象者に関しましてはこれの影響がかなり幅広くさまざまな業界に及んでいることから、全体の業種で考えておりますので、限定的に考えているわけではないということで。","voiceIndex":111,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2518#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":57830,"voices":117}},{"id":"h20-20080602-7","meetingId":"h20-cm06","date":"2008年6月2日","dateIso":"2008-06-02","committee":"厚生委員会","time":"午後１時０２分～午後３時４９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"阿部委員","kind":"質問・要望","question":"大変それが使いやすかったものですから、児童保健事業部のこの概要の中にも、それを書くことが可能なのか。それとも、相乗りしているものが多いから書けないということであれば、それはそれでいいんですけれども、もしあれば便利だなと思ったものですから、私としては、できればやっていただきたいと思っています。","respondent":"古川児童保健事業部長","answer":"貴重なご意見をありがとうございました。事務事業概要がよりわかりやすくという視点でのご意見だと思いますので、今回、どこまでできるか、この後また冊子を製本いたしますので、可能な限り対応していきたいと考えております。","voiceIndex":49,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど、どんぐり保育園の５２名の定員枠の拡大ということでしたが、定員枠の拡大のところと、１０７.８％とか、１０１.９％という、弾力化という言い方をしていいんでしょうか、その辺の数の考え方というんですか、どういうところでこうしていらっしゃるのかという大もとの考え方とか、算定の公式とかがあるのか。","respondent":"平澤品川区保健センター衛生課長、小林保育課長","answer":"診療所につきましては、平成１５年１０月１日で１８８ベッドあったものが、１４５ベッドにかなり減っているわけですけれども、こちらにつきましては。この定数と弾力化の数の考え方というお尋ねですけれども、定数につきましては、あらかじめ施設計画に基づきまして、継続的、かつ安定的に維持すべき入所定員ということで考えております。","voiceIndex":51,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"意見","question":"今の弾力化のところからすると、地域の需要と、今はほんとうに保育園不足の中では、困難度を勘案しながらというところでは、どこまで弾力化できるのか、するのかというあたりの線をどこに引いていらっしゃるのかを、一つお願いします。それからもう１点、３１ページに。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"あまり細かく言うつもりはないんですけれども、せっかく今日、そんなに時間が押し迫ってもいないし、全体的に聞けるお伺いできる機会ってあまりないので、これからいろいろ聞いていく基本になるところなので、ぜひよろしくお願いいたします。","respondent":"小林保育課長","answer":"１点目の弾力化のめどといたしましては、４月当初、１５％、年度途中の１０月前後になりますが、２５％、これを超えますと弾力化の規制枠はございません。この指針に沿って、必要な対応をしてまいりたいと思っています。","voiceIndex":56,"id":"exchange-004"},{"speaker":"浅野委員","kind":"質問","question":"国の医療制度改革により、健診については、各医療保険者により行うものとされました。区では、国民健康保険加入者には国保年金課が健康診断などを実施し、後期高齢者医療制度対象者には、高齢事業課が実施しますが、委員会をまたがるこうした例や、他課とリンクした事業の審査はどのような取り扱いをするのでしょうか。","respondent":"古川児童保健事業部長","answer":"ただ、後期高齢者につきましては、当然、こちらの所管ですから、当委員会での対応と考えております。","voiceIndex":58,"id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"東京都の一般財源化になったことによって、今後、区の助成というのは今までどおりに続けていってほしいという要望を聞いているんですけれども、そこら辺のところは、今後も続く方向で考えていいのかということだけ教えていただきたいと思います。","respondent":"平澤品川区保健センター衛生課長、小林保育課長","answer":"ちょっと表の見方が、若干ご説明不足だったかとも思うんですけれども、１１４ページの表８－１です。初めに診療所なんですが、「診療所」と書いてありまして、有床、無床と書いてあります。来年度以降、区の助成の水準が、見通しはどうかということにつきましては、それぞれ来年度の環境の中でより適切に、必要な項目に助成を行うように検討していくところで、現段階で、その水準については言及することは、ちょっと困難です。","voiceIndex":60,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は土日でしっかりとは読めていない、斜めに読みました。今日、せっかくこの場で、プロの理事者の皆さんがこんなに並んでいるところで、今日を逃すと、後で電話でお伺いしたり、お互いに時間のロスでもあるので、５時を過ぎたのだったら、私も控えますけれども、まだ時間があるので、ぜひ、率直に聞かせていただきたいと思うんですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一番最初の高齢者福祉編です。仕事の中身がわからなかったのがあったので、すみません、１ページの福祉改革担当主査というのがあるんですが、この仕事の中身がわからないので、ぜひこれを教えていただきたい。今、三期目なんですけれども、四期の検討が始まるということなので、いつ、どの辺で四期の検討がされるのかというところも教えていただけたらと思います。","respondent":"高橋障害者福祉課長、冨岡高齢福祉課長","answer":"福祉改革主査ということで、障害者の中の福祉改革担当ですが、社会福祉の改革に関することで、私どもで自立支援法ができて、その前に支援費ができた、あの経過の中で、ずっと社会福祉制度というものを一般的に言って。第四期の介護保険事業計画の策定のスケジュールというような中身ですが、まず、この制度推進委員会におきまして、第三期の状況がどうだったのかということを把握いたしまして。","voiceIndex":73,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"(5)に長寿医療制度（後期高齢者）と書いてあるんですけれども、「長寿」という名前のつけ方って、これは一般的に使われるようになったのでしょうか。保険料の通知が、７月に、これから届くということと、ちょっとその辺の徴収方法も教えていただきたい。多分、通知が来て保険料がわかると、また再びいろいろ問い合わせ、苦情が殺到するのではないかなと思うので、その辺の対応についても教えてください。","respondent":"永尾高齢事業課長","answer":"１０月、１２月、２月と、２カ月分ずつ天引きをするように準備しております。普通徴収の方につきましては、７月から来年３月までの９カ月間を１年分でお支払いいただくということで、納付書を送る予定です。納付書と決定通知については、７月中旬を予定しております。","voiceIndex":76,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"後期高齢者の医療制度の問題は、今すごくいろいろ取り沙汰されているんですが、配っていただいた新聞報道の資料の中で、他区で独自の対策をとり始めている自治体が出てきているので、その辺のお考えがあるかどうか、お聞かせいただきたい。これは要望です。","respondent":"永尾高齢事業課長","answer":"他区の独自対策という点ですが、新聞等で幾つか見てはありますが、品川区としましては、国のほうが、今のところ６月１５日の天引きに向けて検討されているという情報が入っておりますので、そちらの動向をよく見ながら、うちのほうも考えてまいりたいと思います。","voiceIndex":78,"id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今日の説明を受けて、一昨年の厚生委員会のときにもお聞きしたかもしれないんですけれども、資料を見ていて何かおかしいなと思ったのは、児童保健事業部と福祉高齢事業部の資料が、例えば平成１７年度、１８年度、１９年度と書いてあると、右から書いてあるのと、左から書いてあるのとある。どういう統一性を持っているのか。どういう状況なのかという点を教えてください。","respondent":"冨岡高齢福祉課長","answer":"最初の数字の並べ方ですが、部は違うとはいえ、同じ委員会に属する所管ですので、調整の方向で検討します。","voiceIndex":80,"id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"２３ページには、実績ということで、事業所別に細かいのが書いてあるんですけれども、概要のところには、事業所別に書かれても、なかなかちょっと見ていくのも見にくい状況があるので、これをまとめた形で介護保険の実態がわかるようなものにしていただけないかなと思うんですけれども、いかがでしょうか。それをまず第１点、お聞かせください。","respondent":"冨岡高齢福祉課長","answer":"介護保険の給付実績等につきましては、一覧表等、わかりやすい表をつけるように検討させていただきたいと思います。","voiceIndex":82,"id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほどの介護老人保健施設にしても、区内の介護老人保健施設は、１施設で１００人ということですけれども、実際に他の自治体の介護老人保健施設を利用されている方もたくさんいるわけですから、療養病床なんかについては、多分、ここにはほとんどないのではないかなと思うんです。今の時点で、そういうふうに言われたので、ちょっと個別の問題で申しわけないんですけれども、お聞かせいただきたいと思います。","respondent":"冨岡高齢福祉課長","answer":"個々のケースで、ちょっとそれは私どもで調べさせていただきたいと思います。一般的にどうこうということはやっておりませんので。","voiceIndex":84,"id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"後期高齢者医療制度なんですが、４月から始まって、問い合わせや苦情がほんとうに殺到して、区の窓口としても大変だったのではないかと思うんですけれども、報道でも、全体でどれぐらいの苦情、問い合わせがあったということも出ていたことがあったかと思うんですけれども、品川区としてはどれぐらいあったのかについて、ちょっとお聞かせいただけないでしょうか。","respondent":"永尾高齢事業課長","answer":"問い合わせの件数ですけれども、先ほどもピーク時で１００件ということで、毎日の苦情の件数は、実はトータルの計算はされていないんですけれども、これから納付書をお送りしたときに、もっとお問い合わせ等が来るのではないかと予想しております。","voiceIndex":86,"id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"７月の保険料の額を通知したところで、かなりの問い合わせの殺到が予想されるのではないかということが書かれていたんです。診療所が、後期高齢者診療料を取りますという申請をして、本人が同意をして初めて取れるということになると思うんですけれども、後期高齢者診療料を取るとしているところが、品川区内にあるか、どうか、把握をしていたら教えていただきたいと思います。","respondent":"永尾高齢事業課長","answer":"診療料の件ですけれども、実際に品川区での数というのは、実はあまり把握をしておりません。ただ、東京都のほうでは、広域のほうでは、３割程度ということは聞いております。","voiceIndex":88,"id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"もう一つ別の件なんですけれども、都南病院の跡地の工事については、予定よりもちょっとおくれたということはお聞きしたんですけれども、先ほど、平成２０年度竣工ということで報告があったと思うんですけれども、平成２１年４月から開設ということでいいんでしょうか。このことだけ、ちょっと確認をお願いしたいと思います。","respondent":"冨岡高齢福祉課長","answer":"今、副委員長のお話にありましたように、年度内に竣工して、予定ですけれども、４月から開設というふうに詰めております。","voiceIndex":90,"id":"exchange-016"},{"speaker":"阿部委員","kind":"質問","question":"すみません、１件だけ手短にお願いいたします。高齢者福祉編の７７ページなんですけれども、数日前の報道だったと思うんですけれども、医療における柔道整復の不正請求が非常に多いというような報道があったかと思うんです。今、この表を見ていますと、確かに数字としては結構な形になるのかなと。もし品川区として何か見解があれば、あるいは、今後の対応があれば教えてください。なければ、結構です。","respondent":"永尾高齢事業課長","answer":"柔道整復の不正請求についてですけれども、現在、品川区ではそういう現状はございません。","voiceIndex":92,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3204#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":49656,"voices":99}},{"id":"h20-20080602-8","meetingId":"h20-cm06","date":"2008年6月2日","dateIso":"2008-06-02","committee":"建設委員会","time":"午後１時０３分～午後２時４５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１番目、幹部職員紹介","agenda":"の１番目、幹部職員紹介","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"今ご説明のあった事業の前段で、街づくり特別委員会との仕切りのところで、先ほど委員長から災害対策については、街づくり特別委員会でというお話がありましたけれども、災害対策はすごく多岐にわたる部分がありまして、今ご説明のあった事業の中でも、何となくこれは災害対策なのかなというのが、下水道事業、あるいは建築課の事業にしても、種々ありますので、まず、どの程度とらえればいいのかというのを。","respondent":"松澤委員長","answer":"改めて街づくり特別委員会の調査事項ということで、八潮のまちづくりに関することについては、前年度の街づくり特別委員会の調査事項を継続する考えで、八潮地区に関することを調査項目とする。","voiceIndex":50,"id":"exchange-001"},{"speaker":"菊地委員","kind":"意見","question":"その仕切りは必要なんですけれども、ただ、この建設委員会でやる質疑についても、どうしても関連してくるものがたくさん出てくるかと思うんです。そこが、街づくり特別委員会で報告されて質疑があったりしても、建設委員会のほうでも、必要な部分、関連する部分として、どうしてもそこに入らざるを得ない部分があると思うので、その辺を委員長のほうでぜひ考慮しながら、お願いしたいと思っています。","respondent":"松澤委員長","answer":"重複することはあるかもしれないけれども、あいまいな部分が残っていると考えておりますので、質疑のときでもあんまり向こうに踏み込むことはちょっという形にしますけれども、できる限り、原則的には質疑に生かしたいと思っています。","voiceIndex":52,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問・要望","question":"事業のことで１つだけお聞かせいただきたいんです。これだけではなくて、ＣＯ２の問題とか、今、まちづくりを進める極めて重要な部分があると思うんですけれども、再開発等で高層ビルをつくられるということと、ソフト面みたいな、環境問題というのをどういうふうに、新たな位置付けとしてあるのかどうか、そこだけお聞かせ願いたいと思います。","respondent":"青木都市開発課長","answer":"そういったものをより積極的に受け入れる、もしくは目標を達成していこうという形で、指導、誘導していくことを想定しておりまして、そういった形では、各所管委員会でご議論いただいたことが、個別具体のものをつくる段階で。","voiceIndex":54,"id":"exchange-003"},{"speaker":"菊地委員","kind":"意見","question":"ただ東京都から何か出てきました、あるいは国の指針がありますからということだけではなくて、やっぱり現実に生まれている状況というのを、まちづくり事業部がきちんと捉えていく中身だと私は思うんですけれども、今の話だと、何かあったら、それと照らし合わせるみたいな感じに聞こえたんですけれども、その辺をもう一度お願いします。","respondent":"岩田まちづくり事業部長","answer":"ただ、学者は、いろいろな学者が自分の研究エリアで、それぞれのご意見をよく言われるんですけれども、学会として正式に認められた形で出てきたものであれば、東京都と国が、私どももそうですけれども、まともにとらえて検討していかなければいけないと思うんですけれども。","voiceIndex":56,"id":"exchange-004"},{"speaker":"菊地委員","kind":"質問・要望","question":"そういう中で、今、学会で認められているかどうか、私もわかりませんけれども、少なくとも学者たちの中で、こういう状況を研究し、こうした状況が生まれる可能性を指摘しているわけですから、この間あった集中豪雨なんかにしても、やっぱり温暖化との関係での集中豪雨だったわけですから、私は、きっちりとした開発と環境問題についてというのは必要だと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"１つ、資料のつくり方でお伺いしたいんですけれども、事務事業概要が、事業費として予算額が計上されているのはとても見やすくていいと思うんですが、昨年と比較していくと、記載に随分と違いがあるんです。この違いはどういうことなのかということをお伺いしたいと思います。","respondent":"松代管理工事課長","answer":"これも、基本的には毎年度、平成１９年度版、平成２０年度版ということでつくっております。今、委員のほうでお示しになりましたのは、例えば、管理工事課のほうでいいますと、平成２０年度予算額というところの数値が、ということでよろしいでしょうか。","voiceIndex":59,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問・要望","question":"こういうところが幾つかあって、逆に、今までトータルだったところが、(1)(2)(3)というようなところで示されているというところがありますので、今後ぜひすべてにそういう記載の仕方をしていただければと思ったものですから、その辺について、特にできないことでなければ、そういう記載にしていただいて、どういうふうに事業が発展しているのかとか、事業が終わったために。","respondent":"松代管理工事課長","answer":"今、委員からお話がありましたように、数字の予算的な表示につきましても、なるべく事業それぞれの内容をわかりやすくする意味でも、ひとつ検討します。","voiceIndex":63,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひよろしくお願いします。次に、４１ページの総合的なまちづくりの推進というところ、これは新しい項目かと思いますけれども、もう少し踏み込んだ事業内容が、検討委託ほかというところで、これはどういう検討委託なのかとか、その辺のところをもう少し見える形で説明いただければと思います。","respondent":"藤田道路公園課長","answer":"それがある程度見えてきた段階で、この事業の中身が、どのように進めていくべきかというのがはっきりしてきますので、今の段階ではこの程度の記載になっておりますが、いずれにしても、地域の方々と一緒にやっていくということが非常に大切だと考えておりますので。","voiceIndex":65,"id":"exchange-008"},{"speaker":"井上委員","kind":"意見","question":"まちづくりについてのソフトというのはすごく幅が広いので、ちょっとわからないんですけれども、ここの事務事業概要に載ってきているというところは、ハード面というところも大きいかと思うんですけれども、ここの住民が考えるハードの協働というところでは、たまたまここは建設委員会だから、建築紛争なんかが相当ここの協働の必要な部分というふうに、私はとらえているんですけれども、そういう部分で。","respondent":"藤田道路公園課長","answer":"そういった意味では、まちづくりに限らず、いろいろなところで行われている事業も、総合的に合わせることでいろいろできることがあると考えていますので、建築紛争絡みのことも、広い意味では中に取り込みながら、考えていくべきと考えております。","voiceIndex":67,"id":"exchange-009"},{"speaker":"井上委員","kind":"提案","question":"２つだけ、あと詳しくはいろいろな担当課にお伺いしたいと思いますけれども、昨年と、３４ページの高潮護岸の維持管理の部分の経費と、３６ページのしながわ水族館の運営経費が上がっているんですが、特に事業として特殊なものがあってそうなっているのかどうか、細かくてすみませんが、教えてください。","respondent":"藤田道路公園課長","answer":"３４ページの高潮護岸の維持管理についてですが、平成２０年度、東京都港湾局のほうから、北品川の天王洲の運河沿いの一部を、区に引き継ぐ予定になっております。","voiceIndex":69,"id":"exchange-010"},{"speaker":"藤原副委員長","kind":"質問","question":"事業部の組織についてお伺いしたいんですけれども、用地担当課長というポジションが紹介されましたが、前年度はなかったような気がするんですけれども、まず、何で新設をしたか、それと具体的にどのようなことをやるのか、その２点、まずお伺いします。","respondent":"岩田まちづくり事業部長","answer":"職務内容は、区が買う土地の地主との交渉、あるいはいろいろなサービス、例えば、売った後の税金対策をどうするかという、地主側に対するアドバイスとか、アフターケア、そして、区で買う場合も、さまざまな公的な処理にきちっと対応するために、職として置いたということです。","voiceIndex":71,"id":"exchange-011"},{"speaker":"藤原副委員長","kind":"質問","question":"交通安全担当課長からも、街路事業担当課長からもさっき説明を受けて、ああということでわかったんですけれども、委員会ですから、出席するのは当たり前ですけれども、名前の紹介だけではなくて、やはりそれだけ重要な、終盤に差しかかって、区としてやっていくんだという心意気で専門職ということで担当課長という形にするのであれば、ちゃんとこういうことをやるという形で。","respondent":"岩田まちづくり事業部長","answer":"今日の事務事業概要のご説明の中で、用地担当課長が職務を分掌している事業というのはないんです。","voiceIndex":73,"id":"exchange-012"},{"speaker":"原委員","kind":"質問・要望","question":"今の部長のお話からすると、これは感覚的にはどうも専門職で、タスクフォースみたいな形になっていて、他の部署のヘルプ的な役割なのかなという気もするんですけれども、そうなってくると、区が直接に買い上げるものと、建設委員会ですから、ストレートに聞いてしまえば、品川区土地開発公社、これとの関連、その辺をざっくりと結構なので、教えていただきたいと思います。","respondent":"岩田まちづくり事業部長","answer":"したがって、お金が残っていればいいんですけれども、なかなか時期によって、地主が買ってくれというときに、きちっと手だてができないというのが、往々にしていますので、そういったものを区が直接買う前に、公社で代行取得していただいて。","voiceIndex":75,"id":"exchange-013"},{"speaker":"原委員","kind":"質問・要望","question":"今日はこれ以上聞きませんけれども、もう一点だけ、形としてはあくまでも、民間と違って、公益性を持って公社となっているということの確認をさせていただきたいのと、そこのところ、要するに、タイムラグの問題等いろいろあるというのは、ご説明で非常によくわかりましたので、そうすると、ケースによっては、これは品川区だけではないんでしょうけれども、公社が買い上げる。","respondent":"岩田まちづくり事業部長","answer":"買ったものはすべて区に引き取ってもらうというのが目的の会社です。当然金融機関からの借入に当たっては、担保は当然区が保証をつけてやっているです。","voiceIndex":77,"id":"exchange-014"},{"speaker":"三上委員","kind":"質問","question":"衆議院において再議決されたガソリン税、これ、１カ月おくれの分ということについては、完全に廃止されるか、品川区には１６億３,０００万円ぐらいの影響があると言っていたわけですけれども、それについては、国としては全く影響なく配りますと言っているのか、それとも、１カ月分、おくれた分については先というような話になっているのか。","respondent":"梶都市計画課長","answer":"これは補助ではなくて、税収が入るんですが、そちらに関しましては、１年間のうち１カ月分だけが税率が低かったものですから、その部分に関しましては、１億円弱ほど下るのではないかと思いますけれども、こちらに関しましては、どのような。","voiceIndex":79,"id":"exchange-015"},{"speaker":"三上委員","kind":"質問","question":"そうすると、国の補助事業については、ほぼ１００％出てくるということが確約されていると。そうすると、多少なりとも、１億円近くなる地方税収の分については影響があるということ、それはどういう事業になるんですか。","respondent":"梶都市計画課長、岩田まちづくり事業部長","answer":"ただいまのところで、地方税収のほうなんですが、こちらのほうは、例えば、経常的に行う道路の維持管理ですとか、あと街路灯の事業、そういったものに関連してまいります。執行しなかったわけですから、２カ月おくれで出発するということになりますので、国庫補助関係で、来るはずの補助金が来なくて、区費を投入するということは、幸いなことに起きなかったわけですけれども。","voiceIndex":81,"id":"exchange-016"},{"speaker":"三上委員","kind":"質問・要望","question":"国の様子を見なければいけないなんていうことになると思いますけれども、区長会でも、しっかりお金をもらえるような、そういう算段を整えていただきたい。国債発行でという話になると困るんだけれども、そうならないような形で、財源確保については、努力していただきたい、お願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-017"},{"speaker":"松澤委員長","kind":"提案","question":"その他を行います。その他で何かありますか。よろしいですか。なければ、私のほうからご案内を申し上げます。今年度の委員会運営についてですが、建設委員会として年間を通して協議したい課題や、常に意識しておきたい調査事項等、委員の皆様のご意見、ご要望をお聞きして、今後の委員会運営の参考にさせていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3912#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":31780,"voices":87}},{"id":"h20-20080602-9","meetingId":"h20-cm06","date":"2008年6月2日","dateIso":"2008-06-02","committee":"文教委員会","time":"午後１時０５分～午後２時４７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"山内副委員長","kind":"意見","question":"副委員長の山内です。どうぞよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"川西委員","kind":"確認","question":"３８ページ、指導主事は１０人配置されているということになっているんですが、これは地域、学校別、どういうふうな内容で分担をされているか教えてください。特別支援教育係の中で相談というのがあるんですが、特別支援ではなくて一般の教育相談というのは、日常的な細かい相談というのは、教育委員会の窓口としてはどこが一番分かりやすく教えていただけるところですか。具体的に教えてください。","respondent":"富田学務課長、河野指導課長、小川品川図書館長","answer":"したがいまして、小学校と中学校の受給率に差が出るということは、小学校から中学校に上がる時点で。それから２点目の教育相談センターのマイスクール八潮の跡地への移転ですが、基本的には、現在行っている教育相談機能。ＴＯＣの地下１階にあります。","voiceIndex":32,"id":"exchange-002"},{"speaker":"川西委員","kind":"質問","question":"指導主事のことなんですけど、６ページの組織図に「指導主事（１０）」と。この１０と書いてあるのは、私が知りたいのは、小学校担当、中学校担当、それから特別支援担当というふうに分かれているというご説明でしたが、それの一覧表というのはどこに行けばいただけるのか教えてください。","respondent":"河野指導課長","answer":"こちらの指導主事のところに「１０」と入っておりますが、これは指導主事だけではなくて、いわゆる学校経営指導員という、もと公立小学校・中学校の校長先生方、その方たちも含めて１０名というふうに記載しています。","voiceIndex":36,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"概要というか、全体的な考え方を伺いたいなと思ったんですが、品川区教育委員会の教育目標が１ページ目から続いていますけれども、冒頭に「日本国憲法および教育基本法の精神に基づき」とありますけれども、この「精神に基づき」というのはどんなふうな理解なのか伺いたいなと思います。具体的なことを伺いたいと思います。全体的な考えを聞かせていただけますか。","respondent":"市川教育次長","answer":"教育目標と基本方針、当然のことながら公教育として実施しているわけで、この国の上位規範である日本国憲法と教育基本法の精神に基づくという枕書きを書いているわけですけれども、これが具体的に示すものとしては、教育目標の上段のところに二つの○印で示しています。","voiceIndex":38,"id":"exchange-004"},{"speaker":"中塚委員","kind":"意見","question":"ほかに、児童の権利に関する条約の趣旨と、教育改革プラン２１の趣旨、それぞれどういうふうなことなのかというのをお聞かせください。","respondent":"河野指導課長","answer":"それからプラン２１の趣旨については、私は先ほど８ページのところで説明いたしましたように、プラン２１の目的そのものは、「明るく楽しい学校をつくり」「夢と力をはぐくむ学校づくり」ということで、教員みずからの意識改革を図った上で。","voiceIndex":40,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"そうすると、ちょっと具体的なことになるんですけれども、中国四川の地震を受けて、多くの保護者の方が町中の学校はどうなるのかという心配の声がよく聞かれるもので、全体像を、今までの経過も含めて、現状を教えていただけたらと思うんですね。現状の耐震化の状況をご説明いただけますか。","respondent":"田村庶務課長","answer":"それ以外に耐震補強工事という形ではございませんが、先ほどの事業概要でもお話ししたように、校舎の改築計画対象の改築工事を実施しているですので、それを含めますと、現在小学校は６校やっておりますので、３８校中３１校ということで８２％。","voiceIndex":42,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"大体夏行うということを伺っているんですけれども、そのあたりというのはどんなふうになっていくのかということと、あと、裏返しなんですけど、耐震化の予算としては変わっていない、改築校にもまだ決まっていない学校というのがいくつかあるんですけど、そういうところというのはどういうふうに考えていらっしゃるのか教えていただけますか。","respondent":"田村庶務課長","answer":"それと、平成１７年度にすべての学校について耐震診断を実施したということで、計画的に地形だとか、老朽度だとか、その診断結果を踏まえて、緊急度の高いものから順に実施していくというような形で、特に夏場に工事が集中するということで。","voiceIndex":46,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"わかりましたが、必要性に応じて順次行うというのが気になるんですけれども、ぜひ、１日も早く耐震化を進めていただきたいと思います。これは新規事業になるんでしょうか、理解が間違っていたら教えてください。逆に中１でもかかってくるんですけれども、そこが対象になっていないということなのか、その辺の理由も含めて。たしか今年からのものだと思うので、ご説明いただけますか。","respondent":"富田学務課長","answer":"それと、お話にありましたように、小中一貫校の標準服の経費につきましては、昨年度までは就学援助の対象とはしておりませんでしたが、今年度より新たに対象としたものでありまして、これは、小学校についてのみということでありまして、毎年対象とするということではなく。","voiceIndex":48,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"じゃあ、今年度のみということは、来年は対象ではないということなのでしょうか。それとも、常に小学校１年生のところは続けていくという考えなのか、教えていただけますか。","respondent":"富田学務課長","answer":"既設の小中一貫校と同様に、新１年生を対象とするです。","voiceIndex":50,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"給食調理代行のところで、今後、全校で計画というお話で、現状何校だというお話がありましたけれども、今年、来年、再来年、いつまでに全校をという計画のところだけ教えていただけますか。","respondent":"富田学務課長","answer":"平成２０年度、今年度から給食調理代行を導入したのは６校であります。来年度以降につきましては、今後、計画を策定してまいります。","voiceIndex":52,"id":"exchange-010"},{"speaker":"西本委員","kind":"確認","question":"例えば仕切りの中で、幼保ですから厚生委員会の方になってしまうのか、それとも、今後、この議論の中では、行政サイドとしてはどういう仕切りを考えているのかをお聞きしたいと思います。それから生涯学習課の方は、総合型スポーツということで動き始めていると思うんですが、今後の流れで、年内にどういう方向づけをして動くのかを伺いたいと思います。その辺の仕切りを聞かせてください。","respondent":"市川教育次長、富田学務課長、和氣小中一貫教育担当課長、堀越生涯学習課長","answer":"一番最後の項目を私の方から。確かに他課との連携事業、あるいは教育委員会全体として他の事業部と連携して取り組んでいくということがあります。校務システムの検討に当たりましては、検討委員会を立ち上げまして、学校の教員の方々に五、六名でしたか参加していただきながら。一貫校以外の連携校につきまして、それぞれ、今までの具体的な実践を踏まえて、今年度特に強化をしてまいりたいと思っておりまして、今。","voiceIndex":54,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"連携事業についてですが、もちろんそういった方向で質問していきたいと思うんですが、その仕切りですね。どこからどこまで、どこでどういうふうにしているのかというのは仕切りをお願いしたいと考えていますので、よろしくお願いします。それで学務課のところで、学校判断で決めていくということですが、それはセキュリティの考え方にかかってくるんですね。そこだけ、よろしくお願いします。","respondent":"富田学務課長","answer":"おっしゃるように、それでは保護者同士の連絡だとか、話し合いだとか、さまざまな情報といった場合には、それはそれとして、それぞれの学校のＰＴＡなりが自分たちとしてその辺をどう考えていくのかというようなことも内容としては出てくるんだと。","voiceIndex":59,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"その洗い出しの中で、問題点はどこにあるのかということをきちんと知った上でＩＴ化を進めていくということをやっていかないと、それで崩れていくというか、なくなってしまうものが当然出てくるわけですから、それでいいというのではなくて、もっと大切なことがあるんじゃないかということは、教育をしていく中でも必要なことなんじゃないかなと思いますので、これは私の意見ということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-013"},{"speaker":"山元委員","kind":"質問・要望","question":"教えていただきたいんですが、３７ページのところの特別支援教育の体制づくりと課題というところなんですが、「小学校のカウンセラーを倍増しました」とありますが、もとがどのぐらいなのかちょっとわからなくて、教えていただきたいということと、それから中身をもっと充実するために体制を変えたというか、そういう意味で変えたのかということ。","respondent":"河野指導課長","answer":"小学校でスクールカウンセラーを配置するという事業は、平成１８年度から実施してまいりました。","voiceIndex":62,"id":"exchange-014"},{"speaker":"山元委員","kind":"質問・要望","question":"今度は１７ページのところなんですが、その他のところで「通学安全監視委託を実施しています」ということで、先ほど、シルバー人材の方と、また地域の方にお願いをするというお話がありました。現実的に報酬というか、ボランティアでお願いをしているのか。特に地域の方が気になるんですが、どのぐらいの方が携わっていらっしゃるのか、わかれば教えていただきたいんですけれども。","respondent":"田村庶務課長","answer":"１７ページの下段の通学安全監視委託ですけれども、シルバー人材センターに委託している部分と、地域協力者にということで、現実的な話になりますと、ボランティアとはいいながら、シルバー人材センターとほぼ同等の有償ということで、お支払いしているということです。","voiceIndex":64,"id":"exchange-015"},{"speaker":"市川委員","kind":"質問","question":"すべての学校に配置されるのか、それとも必要に応じていろいろな学校に配置するのか、その辺を伺いたいということと、２７ページの学校給食のところの給食内容で、米飯給食を現在週２回から３回実施というふうになっているんですけれども、この米飯給食を何回実施するのかというようなことは決められているのか、それとも独自で決めることができるのか、その辺を教えてください。","respondent":"河野指導課長、富田学務課長","answer":"理科支援員の配置事業ですが、これは支援員が学校を巡回するのではなく、学校が支援員を指定して、ある一定の期間、実験や観察の準備等のお手伝いをしていただくという制度です。実際、現在パンですとか麺類がかなり高騰してきておりますので、実際には米飯の回数はもう少し増えていっており、パンが週に１回程度、麺が１カ月に数回というふうに聞いております。","voiceIndex":66,"id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これをずっと読んでいくと、「規範意識」と一番最初に書いてあるけど、それ以外のところで、例えば指導課でもどこかでこういうところをやっていくよというときに、こうやって植えつけていくんだみたいなものの具体策が書いていないような気がするんですけれども、これは当たり前のことで、学校が常々やっているからここにはあえて書いていないんだよというのか、そうはいっても。","respondent":"市川教育次長、河野指導課長、田村庶務課長","answer":"当然のことながら、教育行政と密接不可分の事務事業を担当しているわけでございまして、文教行政にかかわりのある範囲でご質問いただいたことについては。そういう中での地域の方とのふれあいであるとか、子ども同士の人間関係の中のさまざまなもの、問題行動も含めてですけれども。それはすごくボリュームが多いので、どういう記載の仕方にするかは今後の検討にして。","voiceIndex":69,"id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問","question":"これぐらいの、Ａ３ぐらいの紙でまとまると思うんです。それはこれでやめておきます。それで、一つだけちょっと。聞く機会がここぐらいしかないのかなと思うけれども、前の委員会でちょっとだけ私も伺ったんだけれども、ここに書いてあることで、教員の独自採用というようなことにも、考えてみればなるのかな。校長先生の再任用が昨年２人で今年は４人とか５人。","respondent":"河野指導課長","answer":"この再任用管理職、本来定数がありますので、再任用管理職が１人いるということは、逆にそのポストがあかないために、次に控えている要員だとか候補の方が上がれないということもありますので、だれを再任用管理職として残して。","voiceIndex":73,"id":"exchange-018"},{"speaker":"川西委員","kind":"質問","question":"１８ページで、先ほど耐震工事のことで聞くのを忘れたんですが、平成２０年度の主な工事と予定校と書いてありまして、その中に耐震補強は９校ありますね。工事がほとんど夏休み中に行われるという今までの慣例によりまして、これは６月になりますと契約時期になって、７月以降に工事日程が決まるんですけれども、大体短いところで何カ月ですか。これは金額的に、ほとんど指名競争入札ではないですよね。","respondent":"田村庶務課長","answer":"額も、耐震補強工事でも大きな工事だと１億円を超える工事になることもあります。大体平均すると８,０００万円から１億円ぐらいの工事になりますので、指名競争入札ということで処理したいと考えています。","voiceIndex":75,"id":"exchange-019"},{"speaker":"川西委員","kind":"質問","question":"わかりました。ここでやめておきますけど、後ほどお話をお伺いできれば、もう実施設計等はわかっているんですね。教えていただけますか。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"耐震のところで、工事が最低でも１カ月半、長くて３カ月というところで、どうしても校舎だったり体育館や校庭の一部が授業で使えない時期が生まれてしまうのはやむを得ないなと思うんですけど、中学校の部活動とか、体育の授業の場所の確保というのが何とかできないものなのかなと。そういうところの工夫というのはどんなふうになっているのかということを教えてください。","respondent":"田村庶務課長、武内委員長","answer":"やはり工事優先ということで、若干不便はかけますけれども、近隣の学校と相談をしながらそのときには対応してもらうというような形でやっているところです。ほかにご質疑等がないようですので、予定表２の事務事業概要を終了いたします。次に予定表３のその他を行います。その他で何かありますか。","voiceIndex":78,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4634#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":30422,"voices":83}},{"id":"h20-20080602-5","meetingId":"h20-cm06","date":"2008年6月2日","dateIso":"2008-06-02","committee":"総務委員会","time":"午後１時０３分～午後２時５８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"経理課のところで出ている、２５ページの都南病院跡地のこの施設、今建設中だということは承知しているんですけれども、改めて、簡単な質問なんですが、いつごろこれは完成予定なのかというのを、その日時があまり、私もよくわからないので、もし、その辺だけでもちょっと教えていただきたいというのが１つと、あと、区の広報「しながわ」が１７万３,０００部発行ということなんですが。","respondent":"宍戸施設担当課長、中川原広報広聴課長","answer":"都南病院跡地の高齢者施設の工事のスケジュールです。手元に細かいスケジュールがないんですけれども、本体工事につきましては、平成２１年２月末までの予定となっています。外溝工事がそれに引き続いて、平成２０年度中にある予定です。それはなぜかというと、月３回やっているということと、広報紙を配布してから先着何名様という募集がありますので、シルバー人材センターに頼みますと日にち的に何日かかかりまして、非常にそういった意味で。","voiceIndex":43,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"１点だけ伺いたいと思いますけれども、広報「しながわ」の関係なんですが、ホームページにアップしているという、今の、いろいろな文書などを通じてということは、それはそれとして別に否定するものでも何でもないんですけれども、しかし、なかなか届かないという部分をどういうふうに、じゃ、フォローしようかという、そこのところが今の説明ではわからなかったので、実際問題、先ほども紹介しましたように。","respondent":"中川原広報広聴課長","answer":"広報紙はやはり一番、区の情報をお届けするのに、大事な媒体と考えています。","voiceIndex":46,"id":"exchange-002"},{"speaker":"山路副委員長","kind":"質問","question":"総務課の２４ページ、施設担当。昨年、不調ということで入札、当時ありましたけれども、きのう、朝日新聞には、公共工事代金上乗せという国交省の発表がありましたね。この辺について簡単に説明していただけますでしょうか。","respondent":"阿部経理課長","answer":"そうしますと、今度、国土交通省で具体的なルールのやり方を決めますと、それを参考にしながら東京都あるいは２３区全体でどういうような対応をとっていくかというような決め方をしていくと、そういう手続に、具体的にどういうふうになるのかが示されれば、それに従って。","voiceIndex":48,"id":"exchange-003"},{"speaker":"山路副委員長","kind":"質問","question":"今後、例えば学校建築とか、耐震化、この工事が遅くなったり、ずれたり、非常に、この資材の「単品スライド条項」というんですかね、今説明していただいたの。この辺についてのフォローが非常に厳しいんじゃないかと思っていたんですけれども、その辺の、国交省と区との考えというのはどういうふうになっていくのか。","respondent":"阿部経理課長","answer":"ですから、それが明らかになった以降、具体的に、既に契約したものに適用するわけですけれども、どういうふうな形で適用できるのかどうか、そういう検討に入っていくということになると思います。","voiceIndex":50,"id":"exchange-004"},{"speaker":"金野委員","kind":"質問・要望","question":"それについては、広報広聴機能を強化しつつという一文が読み上げられて、ご説明をいただいたんですが、そういう視点に立ってみたときに、例えば１０ページの「しながわガイド」、これは転入者に配布をするというふうになっているんですが、平成１９年度、去年は６０周年を記念して発行したということで、この後は、いわゆるこれは定期的に全戸配布という形でしているものなのか。","respondent":"中川原広報広聴課長","answer":"世論調査というのは、地域とか、世代とか、男女比を圧縮した、品川区のひな型をつくって実施するものですので、そういった意味では、各年代間とか、地域的に、全域的にお聞きする項目、調査の強みを生かした内容で実施する予定です。","voiceIndex":52,"id":"exchange-005"},{"speaker":"金野委員","kind":"質問・要望","question":"「しながわガイド」のほうは、そのように、平成２１年度予定というところであるということでありましたので、これは、基本、確認なんですが、いただきたいという人には全員配布をされているものだと思うんですけれども、まだまだここを知らないで持っていらっしゃらない方というのは意外に多いんだなというのを感じました。ですので、いただけるのであれば、その周知をお願いします。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-006"},{"speaker":"南委員","kind":"意見","question":"さっきの広報「しながわ」の件なんですけれども、郵送は郵券を預かって発送しているというお話と、お隣ご近所の方々の協力関係の中でという、そういう説明が最終的なところでありましたけれども、お隣近所の援助というのは、それはそれとしていいんですけれども、郵券を預かって発送するというのは、そういうご希望の方がいらして。","respondent":"中川原広報広聴課長","answer":"庁内、地域センター、文化センター、図書館等、公的な施設には全部置いてありますので、ちょっと歩けばあるところにはありますので、そこら辺でいかがでしょうかということで考えております。","voiceIndex":55,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"となると、新聞等々で届かない方は自分で取りに行きなさいと、そういった情報を取りなさいって。要するに。いろいろな世帯の方がいらっしゃるし、いろいろな形態の生活をしていらっしゃる方もいらっしゃるわけですけれども、そういう方々にやはり、こういう時代ですから、品川区のやっていること、自分の安全も含めて、生活をしていく上で、情報を提供していく。","respondent":"福田企画部長","answer":"取りに行きなさいと言われますと、非常に冷たいような印象が、そういう印象が区民の方に伝わるといけませんと思いますので、お答えをしますが、品川区といたしましては、費用対効果、このことを十分に勘案しながら、できる限りの方策を尽くしていると。","voiceIndex":57,"id":"exchange-008"},{"speaker":"南委員","kind":"提案","question":"私は、それはちょっと、かえって別の意味のハレーションというか、問題になってくるんじゃないかなというふうに思うし、そういう見解でとらえているのであれば、私は違うというふうに思うので、やはり届ける努力は、どういう形かは今つぶさに、具体的な提案はできませんけれども、届ける努力というのはしていくという立場に立つべきだと思うんです。その点についてはどうですか。","respondent":"福田企画部長","answer":"で、区としては、なにも、取りに行くとか、行かないとかいう話ではなくて、できるだけ広報紙を身近なところにお届けをする、身近なものとして扱っていただく、このような基本的な考えによりまして、広報紙の配布事務を行っているところです。","voiceIndex":59,"id":"exchange-009"}]},{"id":"topic-02","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"質問","question":"内容はもちろん、長期基本計画の検討委員会の中で審議されるものですから、その審議とこの委員会との、総務委員会との関係、その辺をどういうふうにとらえたらいいのかなという、基本的な姿勢として伺いたいと思っているんですけれども、ここで報告を受けて、私たち、報告を受けて、それなりの質問とか、そういうのをして、深めて、理解するように努力するわけですよね。この長期基本計画の内容については。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-010"},{"speaker":"南委員","kind":"確認","question":"その意見を例えば反映させてほしいみたいなことがあった場合には、必要なルートを通じたあれなりがあるんだろうけれども、ダイレクトに、とんでもない、こういうふうにしなさいとかとそういうつもりはないし、そんなことはできないということは承知の上なんですけれども、ここの委員会で出た質疑等々についての扱い方というのは、検討委員会の中でどういうふうに。ちょっとその辺の確認をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"最後には、工事が始まる学校は、当然、保護者の皆さんには説明をしなくてはいけないと思うんですけれども、特に山中ですか、アスベストのところ、万全の体制をとってやるのは言うまでもないことですけれども、そういうこともあるので、保護者への説明はどういうふうに予定されているのかということも、４点目として伺っておきたいと思います。","respondent":"阿部経理課長、宍戸施設担当課長","answer":"先ほど、３校という話ですけれども、これは冒頭申し上げましたけれども、契約予定価格が９,０００万円以上のものを報告していますので、それが３校だです。１１校は計画どおりやる予定です。保護者への説明ですが、庶務課と連携いたしまして、しっかり、その辺についてはご理解をいただいた上で、工事に臨みたいというふうに考えております。","voiceIndex":75,"id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"特に夏休みの期間に工事をする予定だという、こういうことですね。わかりました。あれば、どういうものなのかというのをこの際、伺っておきたいと思います。答弁漏れしていたのであれですけれども、幼稚園は学校と併設しているところは当然入りますけれども、学校とは併設していない単独の園舎の幼稚園、あるいは児童福祉施設についても伺ったんですけれども、そこについても教えていただきたいと思います。","respondent":"日下部企画財政課長、宍戸施設担当課長","answer":"補助金の関係ですが、国については、今申し上げましたように２分の１。それが、３分の２という方向で、今検討がなされているという段階です。それから、東京都につきましては、東京都としての補助金という制度はございません。児童施設の耐震化ですけれども、これにつきましても、今年度、９施設耐震化工事をやる予定になっておりまして、平成２０年度中に完了させる予定となっています。","voiceIndex":78,"id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"もし違っていたら、教えていただきたいんですけれども。しかも、私たちが住んでいるこの大都会は、今後３０年の間にたしか７０％の確率で地震が起きるということも、報道的なところですけれども、ありますし、やはり一刻も早く命を守る公的なところできちんと整備をしておくことが本当に大事なので、そういう点で、どういう計画になっているかということを、改めてこの際教えていただきたいと思うんです。","respondent":"宍戸施設担当課長","answer":"それに加えまして、学校のほうの平成２１年度以降に予定されている施設につきましても、でき得る限り早い時期に、計画的に耐震化を図っていくというふうに考えているところです。","voiceIndex":81,"id":"exchange-014"},{"speaker":"南委員","kind":"確認","question":"でき得る限り早い時期にということなんですけれども、だから、できる限りという、範囲をできるだけ、今年度はここの範囲だけれども、来年度ぐらいには終了するとかという、そういうめどというのは持ちきれないでまだいるということなんですか。そういう方向で検討していると、予算も含めて検討していきたいということなんですか。その辺を確認したいと思って。それで終わりにしたいと思います。","respondent":"日下部企画財政課長","answer":"残りの部分につきましては、例えば１校につきましては、周年行事と重なるので、これは平成２０年度に予定していたものを平成２１年度にしてほしいという地元の要望を受けて、来年に回したというようなケースもあります。","voiceIndex":83,"id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"それはまだ具体的な基本計画も多分やれていない、手がついていない状況なんだろうというふうに思うので、そうなると３年、４年先ということになりますので、その間何もないことを願うわけですけれども、本当に簡単な工事だけでもやったほうがいいんじゃないかなと、あの大地震を見たときにすごく思うんですけれども、そういうことで、くどく質問しちゃって恐縮なんですけれども。","respondent":"市岡総務部長","answer":"については一定の、今幾つか出ましたような条件を勘案しながら、着実に計画を実施していると、こういう方針は区のほうは明確に持っておりますので、そういうご懸念はないのではないかなというふうに思います。","voiceIndex":85,"id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"今、耐震改修工事のところなんですが、品川区、この、今、３つを見ましても、ほぼ耐震補強工事の方法ですか、方法がみんな同じだと思うんです。ほかにもいろいろな請負工事の方法があるかと思うんですが、その辺、品川区として、この工法を積極的に採用しているのか、工事内容を指定して進めているのか、その辺をお聞かせください。","respondent":"宍戸施設担当課長","answer":"そのほかにつきましては、本当にどこの工事会社でも対応できるような内容で。","voiceIndex":87,"id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"最後、１点だけ。ということは、この工事費の中で、ある程度、ここを使うということですから、固定した金額というのはすぐ出てきてしまいますね。すると、その中の、金額として、箇所にもよると思うんですが、大体１カ所当たりどれぐらいの経費というのは、それは出てこないですか。そうですか。わかりました。じゃ、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問","question":"簡単なことなんですけれども、この資料をいただいた中で、さっき説明の中でありましたけれども、浜川小学校の1)と9)になっていますけれども、2)から8)ですね、おそらくあるのは。そのほかにもあるんでしょうかということが１つと、それから、ここだけ、浜川小学校だけ「他１施設」という表現になっているんです。そうなんですかということが一つ。その２つをお聞かせいただければと思います。","respondent":"宍戸施設担当課長","answer":"それで、浜川小学校の場合は1)から9)ぐらいまでございまして、非常に小さい施設もありますし、それから、耐震診断の結果、安全が確認された棟もあります。","voiceIndex":90,"id":"exchange-019"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"須藤委員長","kind":"質問・要望","question":"つきましては、年間を通して協議をしたい課題、調査事項等につきまして、委員の皆さんからご意見をいただきたいと思います。急な話ですので、きょう、今ここで言って、ぱっとなかなか出てこないと思いますので、調査をしたいテーマ等がございましたら、今月、６月１３日、来週の金曜日までに、文書にて事務局のほうに提出をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1786#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":40144,"voices":98}},{"id":"h20-20080603-14","meetingId":"h20-cm06","date":"2008年6月3日","dateIso":"2008-06-03","committee":"行財政改革特別委員会","time":"午後１時０３分～午後３時１３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"今の説明でちょっとわからないところがありまして、お聞かせを願いたいというふうに思います。それから、あと入札方法、ずっと年度で書かれていますけれども、工事案件の現場説明の廃止とありますけれども、これはちょっと私全く知識がないものですから、これはどういう内容のものであったのかをまずお聞かせを願いたいと思います。","respondent":"阿部経理課長","answer":"そうしますと、あってはならないことではありますけれども、談合の機会が発生するというおそれがありますので、そういう観点から現場説明会を廃止しているというものです。","voiceIndex":33,"id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"最後のほうの現場説明会廃止、今品川区では一般競争入札なんかですと発注額を公表して業者が入札に応じていますけれども、最近の状況を見ますと、辞退という業者さんが非常に多くなっているわけですけれども、そもそも先ほどの談合云々という話がありましたけれども、その辺を抜きにして、実際にこうしたまず現場で工事案件について説明をしていくとかという流れがないことによって。","respondent":"阿部経理課長","answer":"ですから、工事の内容につきましては、参加する事業者の方はすべてご存じだというふうに考えております。現場説明会を廃止したことによって、先ほど委員がおっしゃったような事態とか、そういうものにつながっているという認識は持ってございません。","voiceIndex":35,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"もう一点、ちょっと今聞くのを忘れてしまいましたけれども、１３０万円以下のいろんな物品の発注とか、随意契約が多いのかもしれませんけれども、１３０万円以下の随意契約の部分では、区内業者がほとんどだというふうに考えてよろしいんでしょうか。","respondent":"阿部経理課長","answer":"物品につきましては、随意契約の割合が８９％、指名競争入札が１０％、制限付き一般競争入札が１％です。受託につきましては、随意契約が８２％、指名競争入札が１７％、制限付き一般競争入札が１％です。","voiceIndex":37,"id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"全部の数字を教えていただきましたけれども、細かい工事案件あるいは物品についてのところで、ぜひちょっと、次回でも結構ですし、また資料でも結構なんですけれども、区内業者に実際にどの程度どういうふうに仕事が回っているのかというところを、資料になるんでしたら委員長にお願いをしますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-004"},{"speaker":"井上委員","kind":"質問","question":"先ほどに関連して、工事案件の現場説明の廃止というところで、教育委員会のほうでプロポーザルでやるところは、そういう現場説明というのがあったように思ったんですけれども、そちらと両方同じなのか、全然こちらと教育委員会は違う契約のものを持っているのかということについて教えてください。","respondent":"阿部経理課長","answer":"たぶん委員がおっしゃった現場説明があったというのは、委託なんかの場合のプロポーザルだと思うんですが、その場合には業者の説明の場、あるいは業者が自分の考え方を述べる場がありますので、ただ、工事案件につきましては。","voiceIndex":40,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"そもそもそういう案件がないということがわからなければ、入札で手を挙げることもできないんですけど、ちょっとそこら辺が素人考えなんですけどお伺いしたいなと思ったのと、あと先ほどの質疑の中で、区内業者ができる工事は区内にということが原則ということをおっしゃったんですけれども、例えばこの前の臨時会の中でも、大きな工事が多かったんですが、区外の業者も結構入っているんだなと思ったんですが。","respondent":"阿部経理課長","answer":"平成１９年度のを評価いたしまして、やはり本格実施をすべきだと、委託契約におきましては簡易型総合評価を本格実施していいという判断をいたしましたので、平成２０年度からは本格実施をしておるです。","voiceIndex":43,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと順番が逆になってしまうんですが、最後のことなんですが、ちょっと何でいいというふうになったのかという中身がちょっと知りたいので、そこをちょっと簡単でいいんですけどもお伺いしたいのと、あと周知の方法の件ですが、ネット上でまず案件をお知らせして、その後公告というのはどういうやり方でやっているのかなというのを突っ込んで聞きたいのと。","respondent":"阿部経理課長","answer":"それでいくというものですので、そういう面で価格だけではなく、履行能力を判断する必要があったということに基づきまして、この方式を進めていくべきだという結論に至りましたので、平成２０年度からは本格実施をしているというものです。","voiceIndex":45,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"すみません、最後の点なんですが、基本的にネット上でお知らせして、詳しく知りたければネット上で公告を詳しく見るということなのかなと思ったんですけど、なかなか中小零細のところで、いろんな案件が出ると思うんですけど、あまりインターネットと縁がないような業者とかというのは、そういうところというのはそもそもそういう案件の情報に目がとまるという機会がなかなかないんじゃないか。","respondent":"阿部経理課長","answer":"これは先ほど申しましたけれども、東京電子自治体の中では、そういう中で登録をしなきゃいけませんので、ネットを見られないという業者はいないというふうに思っています。","voiceIndex":47,"id":"exchange-008"},{"speaker":"阿部委員","kind":"質問","question":"２点ほどお伺いしたいと思います。それともう一つ、これはちょっと入札方法ということから外れてしまうかもしれないんですけれども、品川の場合、工事を発注した後でのバリューエンジニアリングというのはどの程度考えられているのか、それがまた契約の段階から盛り込んでおかないとなかなか進まないことかなと思うんですけれども、現在どのような扱いになっているのか教えてください。","respondent":"阿部経理課長、市岡総務部長","answer":"ただ、具体的に今まで、ちょっと私今年の４月からなったものですから、まだ具体的に事業者提案ですね、そういうものがあったのかどうか、その辺までちょっと確認してございませんけれども。そういう趣旨で先ほど課長がご説明したです。","voiceIndex":49,"id":"exchange-009"},{"speaker":"阿部委員","kind":"質問・要望","question":"とりあえず施行令で決まっているということであれば、直接動かすのは難しいということだと思うんですけど、地方都市での５,０００平米と品川の５,０００平米というのは全く意味が変わってくると思いますので、運用などでできることがあるのであれば、またそういった方向でもご検討いただければなと思います。ぜひ早急に俎上に乗せていただければと、これも要望でよろしいです。","respondent":"市岡総務部長","answer":"それで、バリューエンジニアリングについては、おそらく近々こういう要素を、例えば契約の中の、先ほど総合評価方式というのをご説明申し上げましたけれども、この要素の中に一つ加えるとか、こういう可能性があります。","voiceIndex":52,"id":"exchange-010"},{"speaker":"浅野委員","kind":"提案","question":"２点ほどお伺いしたいんですが、一つは入札予定価格３,０００万円以上の案件で、予定価格を事前公表という点ですけれども、こちらの予定価格については、たぶん積み上げ方式でいろいろと検討された価格を用意されると思うんですけれども、過去において、やはり不調に終わった件ですとか、また、想定外のことも起きているかと思うんですけれども。","respondent":"阿部経理課長","answer":"ただ、今委員がおっしゃったとおり、今般の事情によりまして不調のようなケースが出ていることも確かですけれども、現時点では今のような形、要するに積算基準に基づきまして積み上げまして、それを参考にして予定価格を公表するという考えに基づきましてやっておりますので。","voiceIndex":54,"id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"３,０００万円以上の案件についてですけれども、こちらの積算基準に基づいているということは、業者のほうもこの積算基準に基づいていて、同じ考え方に基づいて積算をしているということが前提になっているから、あとは価格だけのある意味では勝負というところでいいのかどうかということをお伺いしたいと思います。","respondent":"阿部経理課長、市岡総務部長","answer":"積算基準の話ですけれども、私どもは今東京都の財務局がつくっている積算基準、それを参考にしておりますけれども、事業者の方、個人事業者の方も当然そういうことはご存じで、ほぼそういうものに従って積算をしている。あるいはそういうルートを持っているとか持っていないとか、あるいは履行期間の長短、こういういろいろな要素が複雑に絡み合っていますので、数学的にはじくと同じ結論が出るというものではありませんし、また逆に言えば。","voiceIndex":56,"id":"exchange-012"},{"speaker":"原委員","kind":"質問・要望","question":"というのは、たぶん意味合い的には育成ということで、品川であまり山どめができないとか、そんなような業者がＡランクのところから教えてもらいつつ、品川区の企業に発展していってもらいたいというところの意味合いとかが非常に強いんだと思うんですけれども、そういうことなのかどうなのかということをちょっとまずお返事をいただきたいんですが。","respondent":"阿部経理課長","answer":"というのは、一番このＪＶの場合に大きいのは、やっぱり区内業者の育成ということもありますけれども、区内業者の活性化というか、仕事を回していくという意味合いも大きいものですので、今申し上げたような方法をとっています。","voiceIndex":59,"id":"exchange-013"},{"speaker":"原委員","kind":"質問","question":"それで、具体的な例として、今日スタートなものですから、ざっくり大きい枠からお聞きしたいんですけれども、昨年度も同じ行財政改革特別委員会の中で出てきて、要は企業間の、前回の委員の中で個人の企業名を出せというような話が出たものですから、本年度は契約のことに関してということで四つの方法があるのはわかるんですけれども、もう少し大きくざっくり聞きますと、契約の中には秘密保持契約とか。","respondent":"阿部経理課長","answer":"私ども経理課の前に、どういう契約をだれがしているのかというものを閲覧できるようにしていますので、基本的には今申し上げたどの工事をどこの業者が落札したのかというようなことがわかるようにはしています。","voiceIndex":61,"id":"exchange-014"},{"speaker":"原委員","kind":"質問","question":"これはよくわかりません、私のほうは。そういうふうなお話を聞いたりするものですから。先ほど部長のほうからお話があった品川区の開発公社の話で、これは買い戻しの話が出たんですけれども、こういった開発公社と区との間の問題も同じような形になっているんでしょうか。お教えいただければと思います。","respondent":"阿部経理課長","answer":"開発公社は、区から委託を受けて土地を購入しているというものです。先ほどありました契約の前の話ですけれども、ちょっと情報提供というのは私どもには来てございませんので、ちょっとお答えのしようがないという状況です。","voiceIndex":63,"id":"exchange-015"},{"speaker":"原委員","kind":"質問","question":"そうすると、区のほうではそういったことはやっていない、行政のほうではそういった紙はないよという解釈で理解してよろしいでしょうか。","respondent":"阿部経理課長","answer":"情報提供というのは、例えばどういう情報を提供するということでございましょうか。","voiceIndex":65,"id":"exchange-016"},{"speaker":"原委員","kind":"質問","question":"情報提供じゃなくて、情報を提供されるという形のものがあるのかなというふうに、一般的に。というのは、情報提供ということは別に悪いことではなくて、要はさっきの入札参加じゃないですけれども、区民のためになるためのいろんな方策があるというふうに承っているんですけど、それについて。ですから、区がしているのではなくて、一般から区に対してという意味合いです。","respondent":"阿部経理課長","answer":"私、ちょっと以前のことは承知しておりませんけれども、私が４月から来てからは情報提供されるという事例はございません。","voiceIndex":69,"id":"exchange-017"},{"speaker":"須藤委員","kind":"質問","question":"入札でいろいろ変遷されてきているんですけれども、近年、先ほど浅野委員も言ったように材料費がうんとぽーんと上がってきているので、予定価格を逆に決めちゃうと、そこに入れないよという業者がいるんじゃないかなと思うんだけども、そういうあたりのできるだけ調整しますという話なんだけど、予定価格をやってきて、いい、いいというかな、いいからやっているんだろうけども、そういうこととか。","respondent":"阿部経理課長、市岡総務部長","answer":"これは新聞情報によりますと、今回のような鋼材のような単品が上がった場合については、国交省もルールの適用を具体的に考えていくということがございましたので、今後としては。実は短期間にいろんなそういう業務をやらなきゃいけないということで、かなり所管では苦労したというふうに聞いておりますが、私どもはそのように理解しております。","voiceIndex":71,"id":"exchange-018"},{"speaker":"須藤委員","kind":"意見","question":"今回この項目、契約のあり方ということになってきているので、昨年度も入札かな、何かそういう先ほど原委員も言ったように、同じようなというような表現をしたんだけど、委員会全体としてこの辺の絞りを整理していかないと、また去年と同じような話が出てきちゃう、今の説明を聞いていると、また同じような順々になってきちゃうかなというような思いがあるので、また正副にお願いしたいんだけど。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-019"},{"speaker":"須藤委員","kind":"確認","question":"そのあたりを委員の皆さん、しっかりコンセンサスを得ておかないと、先ほどいろいろ質問されてくると、全体、広くなった質問になってこようかと思うので、そのあたりを、今日は説明をいただくけども、本来こういうところで今期は特別委員会としてやっていくんだということをもう一度皆さんで確認しておきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-020"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほどの質問で、ほかの方からもあったんですが、二つあるんですが、工事総合評価方式のところで、先ほどの答弁で、価格だけでやっていたものを、履行能力も判断するという視点でということだったんですが、ちなみに、今までの中で、価格だけでしてきて、ちょっとこれはまずかったかなというような事例があれば、それをちょっと紹介していただきたいというのと、もう一つ、契約のところで、担当課のほうから。","respondent":"阿部経理課長","answer":"業者推薦ですけれども、これはここで言いますと、随意契約になるわけですけれども、例えば建物の設計なんかの場合に、建物の実施設計をした業者に工事の監理、実際工事に入りますから、工事の監理を行います。","voiceIndex":77,"id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"業者推薦をする場合には随意契約という流れになるということだと、金額とか条件とか、そういうところの制限というのは外されるケースが、今のは実施設計で、設計した人が工事をしたほうがいいという、メリットがあるということだったんですが、ほかにもこういう場所しかないので、こういうところをするとか、こういう団体が能力というか、そういうノウハウを持っているからというようなことも広くとらえて。","respondent":"阿部経理課長","answer":"随意契約の場合、地方自治法施行令で決まっている金額で決まっているものは、例えば今申し上げた工事、工事ですと、先ほど申し上げましたけれど、１３０万円未満の工事については、随意契約はできます。","voiceIndex":79,"id":"exchange-022"},{"speaker":"菊地委員","kind":"質問・要望","question":"前段でありました契約の意義というところで、法律あるいは条例遵守をしてというお話があったんですけれども、私議員にならせていただいてすぐあたり、２０００年だったか２００１年ごろに、契約とか入札に関する法律というのができて、一括下請けの発注を禁止するだとか、二次下請けの契約金額についてきちんと報告をするとかと、そういう法律ができて、その報告を受けた覚えがあるんですけれども、その中で。","respondent":"阿部経理課長","answer":"たしか委員がおっしゃったのは公共工事の入札及び契約の適正化の促進に関する法律だと思いますけれども、その中では、今おっしゃった下請けのところを具体的にどう書いているかというところまでは、私ちょっと申しわけございませんが十分に把握しておりませんので。","voiceIndex":81,"id":"exchange-023"},{"speaker":"原委員","kind":"確認","question":"８番、９番でちょっとここのところですが、これは街づくり特別委員会のほうということなのかな、いいですね。確認事項なんですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-024"},{"speaker":"阿部委員","kind":"質問","question":"それぞれ建物があるわけですが、築年数は書いてあるんですけれども、耐震基準なんかの関係で今後このまま使えそうなものと、ちょっときついなというものとをそれぞれ教えていただければと思います。","respondent":"久保田行財政改革担当課長","answer":"こちらの建物につきまして、それぞれまだこれから用途の検討とかもしなければなりませんので、耐震診断等もその用途に応じていろいろやっていかなければならないのかなというふうには考えております。","voiceIndex":90,"id":"exchange-025"},{"speaker":"阿部委員","kind":"質問","question":"今の段階では線引きはできないということだったかと思います。東品川の清掃作業所なんですけれども、これは比較的新しいんですけれども、私の記憶に間違いがなければ、廃棄物をたしかプレスして船に積み込む、かなり特殊な構造の建物だったかと思うんですけれども、ああいったものというのは、転用のしやすさというのはどうなんでしょうか。ちょっとお伺いします。","respondent":"久保田行財政改革担当課長","answer":"こちらにつきましては、平成１２年のときに東京都のほうから移管をされてきたんですが、そのときに用途制限がございまして、平成１２年から２０年間にわたりまして清掃で使うという用途制限がついておりますので、この用途制限の部分。","voiceIndex":92,"id":"exchange-026"},{"speaker":"阿部委員","kind":"質問","question":"都との調整は今後の時間的なめどというのは、ある程度でもわかっていれば教えてください。","respondent":"久保田行財政改革担当課長","answer":"大変申しわけないんですけども、時間的にいつまでという形ではちょっとまだ調整がついておりませんで、これから、前からも言っているんですけど、まだこれから、当面は調整が必要かなというふうに考えています。","voiceIndex":94,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"これから個々の具体的な検討をしていくときの大きな根本姿勢として、やはりどうやって区民の方の切実な声、要求を反映していくかという仕組みが非常に大切だと思うんですね。繰り返しになってすみませんけど、そこで今区が考えている、どうやって地域要求を取り入れていくかというようなお考えをちょっとお伺いしたいと思います。","respondent":"久保田行財政改革担当課長、福田企画部長","answer":"それで、具体的に地域の声をどういう形で聞いていくかというご質問ですけども、それにつきましては、施設によっていろいろと地域の事情等もあると思いますし、それぞれの施設の使い道、用途につきましてもさまざまだと思いますので。当然区民、広く区民のご要望に区は耳をかさなければならないというふうにも考えておりますし、また、公の財産ということに着目をいたしますと、場合によっては、例えば東京都全体。","voiceIndex":96,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"その周辺に住んでいる方々が、やはりそこに住んでいて実際にいろいろ生活されてきて、地域性とか土地のこととかをよくわかっていると思うので、やはりまず第一に重視すべきなのは、地域の方々のまず意見を聞いた上で、それで全体の、区全体のこともあるでしょうし、都や国のこともあるでしょうし、やはり、第一は地域に住んでいる方の声を本当にくみ取るということが大事だと思うんですけども。","respondent":"久保田行財政改革担当課長","answer":"実際に跡地活用のお話ということになれば、地域のほうに入っていって、説明会なりいろいろやる場面も出てきますので、そういうときに直接地域の声を吸い上げることもできると考えております。","voiceIndex":99,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"いろんな方法が今出されましたけれども、区政協力委員会、それは町会長が入っていますので、そこの場もあるでしょうし、あとタウンミーティング、あと説明会というお話もありましたけども、やはり私はこの一つ一つについてどの地域にとっても、これまでずっとあった施設なわけですから、一つ一つについて説明会なり、あるいは意見公募なりをしてもいいぐらいの私はあれだと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-030"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今日、１から７まで今ご説明いただいたんですが、当然さっきのお答えのようにこれからの跡地利用ということで、現段階での情報といいますか、利用に関しては当然白紙というか、これから考えましょうというところだと思うんですが、現実、この用途地域の中で、これまでの経緯から国や都だとか近隣との流れの中で、制限とかなかなかここはこういう方向性だよと決まっているような制限。","respondent":"久保田行財政改革担当課長","answer":"地域ということのお話がございましたけども、委員ご指摘のとおり、地域というものは品川区全体という地域もありますので、先ほど来からお話が出ておりますけども、こうした公有地、広い土地につきましては、品川区全体の財産でもありますので。","voiceIndex":102,"id":"exchange-031"},{"speaker":"石田（慎）委員","kind":"質問","question":"その３年間というのは、何も活用しなかったらむだになってしまいますし、そういった考え方をお聞きしたいと思います。平地にして、あれをちょっと設置すればすぐできてしまう。そういったものが民間ではやられている中で、行政としてはそういった空白期間というものの考え方というのはどのような考え方をお持ちなのか、その２点をちょっとお伺いしたいと思います。","respondent":"久保田行財政改革担当課長","answer":"委員おっしゃるように、私どものほうも既にあくという期限が決められておりますので、できるだけそういうあいた後、むだな期間がないように計画的に活用について検討を進めて、むだのないようにやっていきたいというふうに考えております。","voiceIndex":104,"id":"exchange-032"},{"speaker":"石田（慎）委員","kind":"質問","question":"そうすると、基本的には空白期間はできる限りつくらないで、跡地活用の案を進めていきたいというのが区としての考えという理解でよろしいのでしょうか。","respondent":"久保田行財政改革担当課長","answer":"繰り返しになりますけども、期限が決まっておりますので、基本的にはあくことのないように、むだのないように、できるだけそういう形で話を進めていきたいなというふうに思っております。","voiceIndex":106,"id":"exchange-033"},{"speaker":"阿部委員","kind":"質問","question":"今出てきている９カ所ないし７カ所、それぞれをどうするかというだけではなくて、これだけ出た機会にというのもなんですけれども、区内の公共施設の全体像というのをきちんとどうしたらよりバランスがよくなるかという全体像を考えた上で、場合によっては既存の施設の機能をここに移して、そちら側をあけるといったような考え方もあるんじゃないかと思うんですけれども。","respondent":"久保田行財政改革担当課長","answer":"今のご質問ですけど、既存の施設を空けて、こちらの新しいところというご質問だと思うんですけれども、私どものほうでいろいろと品川区のほう、バランスよく配置ができているかというところの検証も必要だとは思いますけども、いろいろとそういう広い視野を見ながら。","voiceIndex":108,"id":"exchange-034"},{"speaker":"阿部委員","kind":"質問","question":"最後のところ、たぶん、ごめんなさい、ちょっといろいろ解釈しようがあったかなと思うんです。ごめんなさい。要は、この７カ所、それぞれ１対１で物を考えていくというだけではなくて、もう少し広く自由に設計していく中で、最終的にどのようにしていくかというところまで突っ込んで話をしていくということでよろしいでしょうか。","respondent":"福田企画部長","answer":"したがいまして、区としては広く考えたいなというふうには思っておりますが、ただ、その一方で、やはり土地にはそれぞれの属性がありますし、それから用途指定ですとか、それから用途制限、高さ制限というような前提になるものがありますので。","voiceIndex":110,"id":"exchange-035"},{"speaker":"井上委員","kind":"提案","question":"本当に品川区では土地もないところでこれからそういう必要なものが今たくさん上がっているわけなので、そういうところの検討に当たって、プロジェクトのような専門的にそこを検討できるような連携をとってということではないものを考えたらどうかというふうに思うんですが、その辺のお考えが一つと、あと資料の提案の仕方についてちょっとお伺いをしたいんですが、先ほど３番、５番のところで。","respondent":"久保田行財政改革担当課長","answer":"区民のニーズを取り入れていくかということですけれども、プロジェクトチームなりをつくってやっていくかということがあると思うんですけれども、街づくり特別委員会でまた議論。","voiceIndex":112,"id":"exchange-036"},{"speaker":"井上委員","kind":"質問・要望","question":"考え方としてＴＯＣだとか、仮の大崎在宅支援センターだとか、そういったところがやっぱり情報の出し方として、そのことについても区民からの要望とかいろいろな声を反映させるためにも、決定事項しかこういったところに出せないものではないと思うので、その辺はやっぱり情報の開示というところをもう少し広くとらえていただきたいというのは要望しておきます。","respondent":"日下部企画財政課長","answer":"総合体育館につきましては、今もご質問にございましたけれども、すでに体育館としての機能は移転をしておりますけれども、大崎の東口の五丁目第一地区という再開発のエリアの中に入っておりまして。","voiceIndex":114,"id":"exchange-037"},{"speaker":"井上委員","kind":"質問・要望","question":"だから、同じような考え方で大崎の在宅支援センターとか、そういうところもこういう考え方を持っているという視点に立てば、同じようなたまたまあいているところをどうこうするということではなくて、区有財産としてあるこういったものをどう考えるかという資料策定にしてほしいという前提があっての要望なんですけれども、一応こういう資料をいただいたときに。","respondent":"福田企画部長","answer":"したがいまして、ご意見の趣旨は理解をするところですけれども、やはり１件１件、これは慎重に対処する必要があるというふうに考えております。","voiceIndex":116,"id":"exchange-038"},{"speaker":"須藤委員","kind":"質問","question":"それともう一つは、長期基本計画の絡みが出てくるので、計画の策定委員会は策定委員会としてできているわけですから、そこと連携をとるような仕組みができてこないとおかしいんじゃないかなと思うんだけども、そのあたりはどういうふうにお考えでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-039"},{"speaker":"須藤委員","kind":"質問","question":"ですから、全体の進め方というのをちょっとお話ししていただいて、それは３でやろうとしたんだけども、その前にこういう考え方で今日はこの資料をやっていますというお話で、概略説明ですよというようなことにしていかないと、皆さんいろんな質問、考え方がこうなってきちゃうと思うので、ですから、今委員長がお話のように施設のあり方。","respondent":"飯沼委員長","answer":"前段でもちょっとお話をさせていただいたんですが、跡地利用と施設の有効活用についてという２点で調査研究をしていきたいと考えていますけれども、中身的にはどう絞っていったらいいのかあたりも、今日のその他のところで皆さんのご意見をいただく中で。","voiceIndex":120,"id":"exchange-040"},{"speaker":"須藤委員","kind":"意見","question":"先ほど来阿部委員からもお話があったように、品川区全体としてのバランスというのが担当課長からも部長からもあって、だから、そこまで僕らが今あるものをこうやってこっちに移して逆にそこにこういうものをやったりとか、いろんな考え方ができようかと思うんだけど、そういうことも我々の中で研究していく、調査していくということでいいのかな。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":122,"id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回の公有地をどう使うかというのは、本当に大きなお金ももちろん大事な財産ですし、巨大な大きなプロジェクトだと思うので、ここに区民参加を徹底して勝ち取るということが私はすごく大事な大きなテーマになってくるんじゃないかなというふうに思っておりまして、例えば地域の声、地域とは何ぞやという話がありましたけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-042"}]},{"id":"topic-02","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"逆な考え方からしますと。区民の皆さんのご意見を伺うということも非常に重要なことだと思いますけれども、伺う中でも、そういうベースとなるものがあれば、ある意味では論議がしやすいというふうに考えておりますので、この点、２点、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-043"},{"speaker":"井上委員","kind":"提案","question":"公有財産のときも、原小学校のときにも私も行財政改革特別委員会で議論させていただきましたけれども、本来こういうところというのは、こういうふうな長期基本計画の中で、行政としても今浅野委員がおっしゃったようにこういうものが必要だと考えているというのもあるかと思うんですが、一方で、区民がどういうものが必要であるかというのが本来私たちがここで提案すべきことなので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":129,"id":"exchange-044"},{"speaker":"阿部委員","kind":"質問","question":"今の井上委員のおっしゃるとおりだと思っています。特に契約のあり方についてですね。ですから、どうなんでしょう、これは契約というのはかなり技術的に押さえておかなければ、技術的というか、知識として知っておかなければいけないことがまずあって、それを月に１回、１時間、２時間でやっていくと、また１年間終わってしまうんではないかというちょっと危惧があります。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-045"},{"speaker":"菊地委員","kind":"質問","question":"ですから、私はこの委員会でこういう契約やなんかに関して言えば、アメリカでやられているリビングウェイジ、いわゆる生活できる賃金とかという考え方、あるいは総合評価制度なんかだと、地方では今自分のところの基準を設けて環境の問題をするだとか、そういったことをやっている地方もありますけれども、そういうことに対するきっちりした意見、調査をしていくべきなんだろうなというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-046"},{"speaker":"須藤委員","kind":"質問","question":"契約のやり方には、先ほど委員長のほうからお話しいただいたので、随意契約ですか、そういったものということで、前年度と違うよと、ある程度絞ったお話をされていたので、そのあたりを出して、皆さんで議論していかれたらどうか。正副で少し、２番目のほうについては整理をされたらと。１番目についてはある程度絞られてきていますので、そこを中心に課題をみんなで検討していかれたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-047"},{"speaker":"金野委員","kind":"提案","question":"それでやはり、品川としてこの行政改革をどうしたらいいかということを考えたときに、やはりむだを省いて使うべきところは使うという、この考え方は非常に私たち公明党としても持っている大事な視点であるところへ、品川としてはどうむだを省いて皆さんのためにどう使っていくかという観点から、やはりこの１番の契約のあり方というのは非常に専門知識も要することなので、できれば早目に。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":133,"id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと可能かどうかわからないんですが、ちょっと意見として言いたいなと思ってあえて言いたいんですが、ちょっと繰り返しになっちゃうんですけど、繰り返しは避けたいと思うんですが、公有地の活用に関すること、当面跡地利用ということでお話しするということで委員長から冒頭説明があったと思うんですけども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-049"},{"speaker":"阿部委員","kind":"質問","question":"先ほど資料を早目にというお話もありましたけれども、資料そのものというよりも、大体何月ぐらいには契約のことをやるんだとか、それが一たん全部終わってから公有財産をやるんだ、いや交互にやるんだとか、そういうちょっと長期的な見通しなり順番なりということがある程度事前に流れとしてわかっていると、それに沿ってこちらとしてもその準備をしたり、事前に現場を見たりとか、いろいろできると思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-050"},{"speaker":"井上委員","kind":"提案","question":"やっぱり区民の方からも旧荏原第二中学校の場合には、いつどういうふうに提案したらいいのとか、区民の人たちもいろいろなこういう状況はわかっているので、どういうふうに区民が提案をしていけばいいの、どこに言っていけばいいのというような、そういう流れが今品川区はないという意味では、そういうところの仕組みづくりこそ議会で、ここで検討できればなというふうに思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":136,"id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5840#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":40164,"voices":139}}]);
